INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (132, 'Cottage Cheese Eggs', 'Budget Bytes', 'https://www.budgetbytes.com/cottage-cheese-eggs/', 15, 15, 0, 2, 2, 0, 2.0, 'serving', '1. Whisk the 3 eggs with 1/8 tsp salt until the mixture is an even yellow with no streaks of white left. | 2. Lightly whisk in the 2 Tbsp cottage cheese, leaving some of the curds intact. | 3. Melt 1 Tbsp butter in a nonstick skillet over medium-low heat until it foams but has not browned. | 4. Pour in the eggs and let them sit for a few seconds, until the edges start to turn opaque. | 5. Gently push the cooked egg toward the center, tilting the pan so raw egg runs onto the hot surface, and stir only occasionally. | 6. Take the pan off the heat while the eggs are still slightly glossy, since they keep cooking from the pan''s heat, and serve right away.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (132, 1, NULL, 'egg', 3.0, 3.0, 'each', 'large', NULL, 0, '3 large eggs');
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (132, 2, NULL, 'salt', 0.125, 0.125, 'tsp', NULL, NULL, 0, '⅛ tsp salt');
