INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (133, 'Creamy Tomato and Spinach Pasta', 'Budget Bytes', 'https://www.budgetbytes.com/creamy-tomato-spinach-pasta/', 25, 25, 0, 4, 4, 0, 4.0, 'serving', '1. Boil 1/2 lb penne in a large pot of water until tender, about 7 to 10 minutes, then drain well. | 2. While the pasta cooks, saute the diced onion and minced garlic in 1 Tbsp olive oil in a large skillet over medium heat for 3 to 5 minutes, until the onion is soft and translucent. | 3. Add the can of diced tomatoes with their juices, the oregano, basil, red pepper flakes, 1/2 tsp salt and 1/2 tsp black pepper, then stir in the tomato paste and 1/2 cup water until smooth. | 4. Turn the heat to low, add the cream cheese in pieces, and whisk until it melts into a creamy sauce. Stir in the Parmesan until melted. | 5. Fold in the spinach and cook 2 to 3 minutes, until wilted. | 6. Add the drained pasta, toss until coated, and adjust the salt and pepper before serving.', NULL);
