INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (135, 'Tomato Lentil Soup', 'Budget Bytes', 'https://www.budgetbytes.com/tomato-lentil-soup/', 60, 20, 0, 6, 6, 0, 6.0, 'serving', '1. Dice the onion, mince the garlic, and cut the carrots into quarter rounds. Saute them in 2 Tbsp olive oil in a large soup pot over medium heat until the onion softens, and meanwhile peel and dice the potato into 1/2-inch cubes. | 2. Stir in the tomato paste and cook 2 to 3 minutes, until it starts to coat the bottom of the pot. | 3. Add the potato, the stewed tomatoes with their juices, the lentils, paprika, basil, oregano, pepper and 4 cups vegetable broth, and stir. | 4. Cover, bring to a boil, then lower the heat and simmer about 40 minutes, until the lentils are very tender and starting to break down. | 5. Stir in the soy sauce and add salt to taste, depending on how salty your broth is. | 6. Serve hot, ideally with crusty bread.', NULL);
