INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (136, 'Thai Red Curry Vegetable Soup', 'Budget Bytes', 'https://www.budgetbytes.com/thai-curry-vegetable-soup/', 35, 35, 1, 4, 4, 1, NULL, NULL, '1. Mince the garlic, grate the ginger, cut the sweet potato into 1-inch cubes and the bok choy into 1-inch strips (keeping stalks and leaves apart), slice the red onion, and chop the cilantro. | 2. Heat 2 Tbsp oil in a large pot over medium heat, then cook the garlic, ginger and 3 Tbsp red curry paste for 1 to 2 minutes. | 3. Add the sweet potato, bok choy stalks and 4 cups broth, bring to a boil over medium-high heat, then reduce to low and simmer 5 to 7 minutes, until the sweet potato is tender. | 4. While the soup simmers, boil the rice vermicelli in a separate pot of water for 2 to 3 minutes, until tender, then drain. | 5. Stir the coconut milk, fish sauce and brown sugar into the soup, taste and adjust, then add the bok choy leaves and let them wilt. | 6. Divide the noodles among four bowls, ladle the soup over them, and top with the red onion, cilantro, lime wedges and sriracha.', NULL);
