INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (137, 'Chicken and Lime Soup', 'Budget Bytes', 'https://www.budgetbytes.com/chicken-lime-soup/', 70, 25, 0, 6, 6, 0, 6.0, 'serving', '1. Dice the onion, celery and seeded jalapeno and mince the garlic. Cook them in 2 Tbsp olive oil in a large soup pot over medium heat for about 5 minutes, until the onion is soft and translucent. | 2. Add the chicken breast, 6 cups chicken broth, both cans of diced tomatoes with green chiles (with their juices), the oregano and the cumin. Cover, turn the heat to high, and bring to a boil. | 3. Once boiling, lower the heat and simmer covered for 45 minutes. | 4. Lift out the chicken, shred it with two forks, and return it to the pot. | 5. Squeeze in the juice of the lime (2 to 3 Tbsp) and stir in the roughly chopped cilantro leaves. | 6. Serve with a few slices of avocado in each bowl.', NULL);
