INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (138, 'Teriyaki Chicken Bowls', 'Spend With Pennies', 'https://www.spendwithpennies.com/teriyaki-chicken-bowls/', 30, 30, 0, 4, 4, 0, 4.0, 'serving', '1. Put the broccoli florets in a medium bowl with 2 Tbsp water, cover with a plate, and microwave 2 to 3 minutes until tender-crisp. | 2. Cut the chicken into bite-size pieces and season with 1/4 tsp salt and 1/8 tsp pepper. | 3. Heat 1 Tbsp oil in a large skillet over medium-high heat, cook the chicken 3 minutes without stirring, then stir and cook about 4 minutes more until almost cooked through. Move it to a plate. | 4. Add the soy sauce, 2/3 cup water, garlic, ginger and brown sugar to the skillet and whisk until bubbling and the sugar dissolves. | 5. Stir 1 Tbsp cornstarch into 1 1/2 Tbsp water, then drizzle it into the simmering sauce while whisking until thickened (you may not need all of it). | 6. Return the chicken to the pan and simmer 2 to 3 minutes until cooked through. | 7. Put about 3/4 cup rice in each bowl, top with chicken and broccoli, and spoon the sauce over.', NULL);
