INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (141, 'Bean Burritos', 'Taste of Home', 'https://www.tasteofhome.com/recipes/bean-burritos/', 30, 10, 0, 6, 6, 0, 6.0, 'serving', '1. Preheat the oven to 375 degrees F. In a large bowl, mix the refried beans, salsa, cooked rice and 1 cup of the cheese. | 2. Spoon about 1/3 cup of the filling off-center onto each tortilla, fold in the sides and ends, and roll up. | 3. Place the burritos seam side down in a greased 13x9-inch baking dish and sprinkle the remaining 1 cup cheese on top. | 4. Cover and bake 20 to 25 minutes, until heated through, then add toppings as you like.', NULL);
