INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (146, 'Easy Chicken Tacos', 'Damn Delicious', 'https://damndelicious.net/2019/08/06/easy-chicken-tacos/', 30, 30, 1, 4, 4, 1, NULL, NULL, '1. Mix the spice rub: 2 tsp chili powder, 1 tsp cumin, 1 tsp smoked paprika, 1 tsp dried oregano, 1/2 tsp garlic powder, 1 tsp kosher salt and 1/2 tsp black pepper. | 2. Pat the chicken dry with paper towels and coat it with the spice rub. | 3. Heat 1 Tbsp canola oil in a large cast iron skillet over medium-high heat. | 4. Cook the chicken in batches in a single layer, 4 to 5 minutes per side, until golden brown and 165 degrees F inside. | 5. Let the chicken cool a few minutes, then dice it into bite-size pieces. | 6. Fill the warm tortillas with chicken and top with the pico de gallo, diced avocado, cilantro and a squeeze of lime.', NULL);
