INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (148, 'Fajita Meal Prep Bowls', 'Spend With Pennies', 'https://www.spendwithpennies.com/fajita-meal-prep-bowls/', 35, 15, 0, 6, 6, 0, 6.0, 'serving', '1. Preheat the oven to 425 degrees F. Stir the olive oil together with all the seasonings in a small bowl. | 2. Cut the chicken into 1-inch pieces and toss it with half of the seasoned oil. | 3. Cut the bell peppers into strips and slice the onion thin, then toss them with the rest of the seasoned oil. | 4. Spread the chicken and vegetables on a parchment-lined pan and bake 20 to 22 minutes, stirring after 10 minutes, until the chicken is cooked through. | 5. Set out 6 containers and put 1/2 cup cooked rice in each, then divide the chicken, vegetables and salsa among them. | 6. Seal and refrigerate up to 4 days, or freeze. Reheat in the microwave about 2 1/2 minutes (3 1/2 minutes from frozen).', NULL);
