INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (149, '1-Pot Lentil Green Curry', 'Minimalist Baker', 'https://minimalistbaker.com/1-pot-lentil-dal/', 40, 22, 0, 4, 4, 0, 4.0, 'serving', '1. Heat a large pot over medium heat, then saute the coconut oil, optional chili, ginger, shallot and garlic for 3 to 4 minutes, stirring occasionally and lowering the heat if they brown too fast. | 2. Add 4 Tbsp green curry paste and cook 2 to 3 minutes, then stir in the coconut milk, turmeric, curry powder and a pinch each of salt and pepper. | 3. Bring to a simmer, then add the lentils, soy sauce, 1 to 2 Tbsp sweetener and the optional cayenne. | 4. Return to a simmer, lower the heat, and cook gently 15 to 20 minutes, until the lentils are tender, then stir in 2 Tbsp lemon juice. | 5. Taste and adjust the lemon, heat, salt or sweetness, and serve plain or over rice with cilantro and lemon or lime wedges.', NULL);
