INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (150, '1-Pot Red Lentil Chili', 'Minimalist Baker', 'https://minimalistbaker.com/1-pot-red-lentil-chili/', 55, 25, 0, 6, 6, 0, 6.0, 'serving', '1. Heat a large pot over medium heat, add the oil, diced onion and red pepper with a pinch each of salt and pepper, and saute 3 to 4 minutes, stirring often. | 2. Crush the jalapeno and garlic into a rough paste (a mortar and pestle works, or mince very finely), then add to the pot with another pinch of salt and pepper. | 3. Stir in 2 Tbsp of the chili powder, 1 Tbsp of the cumin, the paprika, diced tomatoes, tomato paste and 1 3/4 cups water, and bring to a low boil over medium-high heat. | 4. Add the red lentils, drop to a gentle simmer, and cook about 15 minutes until mostly tender, adding water if the lentils are no longer covered. | 5. Stir in the kidney beans, black beans, 1/4 tsp each salt and pepper, and the remaining 1 Tbsp each chili powder and cumin. | 6. Return to a simmer, add the corn if using, cover, and cook gently 20 minutes, stirring occasionally. | 7. Taste and adjust with more chili powder or cumin, salt, or a little sweetener to balance the heat, then serve.', NULL);
