INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (151, 'Spinach and Mushroom Quesadillas', 'Budget Bytes', 'https://www.budgetbytes.com/spinach-and-mushroom-quesadillas/', 30, 30, 0, 3, 5, 1, 5.0, 'quesadilla', '1. Slice the mushrooms and cook them in a skillet over medium heat with 1 Tbsp oil, the garlic powder, crushed red pepper, 1/8 tsp salt and 1/8 tsp pepper until the moisture has cooked off, then set them aside. | 2. Thaw the spinach and squeeze out as much water as you can; you should end up with about 1 loosely packed cup. | 3. Stir the spinach, mushrooms, shredded mozzarella, sour cream and the remaining 1/8 tsp each of salt and pepper together in a bowl. | 4. Spread about 1/2 cup of filling over half of each tortilla and fold it closed. | 5. Cook the quesadillas in a skillet over medium heat until golden and crisp outside and melty inside (no oil needed), then slice and serve.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (151, 1, NULL, 'mushroom', 8.0, 8.0, 'oz', 'sliced', NULL, 0, '8 oz. mushrooms');
