INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (152, 'Roasted Corn Quesadillas', 'Budget Bytes', 'https://www.budgetbytes.com/roasted-corn-quesadillas/', 25, 25, 0, 4, 7, 1, 7.0, 'quesadilla', '1. Mix the chicken, frozen corn (no need to thaw), green onions, green chiles, cheese, cumin and salt in a bowl until evenly combined. | 2. Spoon about 1/2 cup of filling onto half of each tortilla and fold closed; the filling makes 7. | 3. Cook the quesadillas in a dry skillet over medium-low heat, flipping once, until both sides are browned and crisp and the cheese has melted. | 4. Cut each quesadilla into thirds and serve. To freeze, fill and fold without cooking, stack with parchment between layers in a freezer bag, thaw about 15 minutes, then cook over low heat.', NULL);
