INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (153, 'Creamy White Bean and Spinach Quesadillas', 'Budget Bytes', 'https://www.budgetbytes.com/creamy-white-bean-and-spinach-quesadillas/', 20, 20, 0, 2, 4, 1, 4.0, 'quesadilla', '1. Rinse and drain the cannellini beans, then stir in the chili powder, cumin, garlic powder and salt to coat. | 2. Roughly chop the spinach and mix it into the beans with the shredded cheese and sour cream. | 3. Spread the filling over half of each of the four tortillas and fold them in half. | 4. Cook one or two at a time in a skillet over medium heat 3 to 5 minutes per side, until browned, crisp and melted inside. | 5. Cut each quesadilla in half and serve.', NULL);
