INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (154, 'Spinach Artichoke Quesadillas', 'Budget Bytes', 'https://www.budgetbytes.com/spinach-artichoke-quesadillas/', 10, 10, 0, 1, 1, 0, 1.0, 'serving', '1. Spread 1/3 cup spinach artichoke dip over half of the tortilla, then top with the shredded chicken and a couple dashes of hot sauce. | 2. Fold the tortilla in half and cook it in a dry skillet over medium heat until browned and crisp, then flip and brown the other side. | 3. Cut into two or three pieces and serve.', NULL);
