INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (155, 'Cheesy Kidney Bean Quesadillas', 'Budget Bytes', 'https://www.budgetbytes.com/cheesy-kidney-bean-quesadillas/', 25, 25, 0, 5, 5, 0, 5.0, 'serving', '1. Drain and rinse the beans and shred the cheddar. | 2. Saute the olive oil, taco seasoning and frozen vegetables in a skillet over medium heat for 4 to 5 minutes. | 3. Add the beans, turn the heat to low, and cook until warmed through, then mash with a fork, leaving some beans whole. | 4. Move the filling to a covered bowl and wipe out the pan. | 5. Sprinkle cheese over half of each tortilla, top with the bean mixture and a bit more cheese, and fold in half. | 6. Toast the quesadillas in the pan 2 to 3 minutes per side until crisp and golden, then cut in half and serve hot.', NULL);
