INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (156, 'Ultimate BBQ Chicken Quesadillas', 'Budget Bytes', 'https://www.budgetbytes.com/ultimate-bbq-chicken-quesadillas/', 25, 25, 0, 5, 5, 0, 5.0, 'serving', '1. Chop the cooked chicken small and put it in a large bowl with the drained black beans. | 2. Finely dice the red onion and the seeded jalapeno, chop the cilantro leaves, and shred the cheddar if needed. | 3. Add the onion, jalapeno, cilantro, cheddar, chili powder, smoked paprika, salt and BBQ sauce to the bowl and stir until coated. | 4. Spoon about 1/3 cup of filling onto half of each tortilla and fold closed. | 5. Cook in a dry skillet over medium-low heat until browned and crisp, hot inside, and the cheese has melted. | 6. Cut each quesadilla in half and serve. Leftovers keep about 3 days in the fridge; uncooked assembled quesadillas freeze 2 to 3 months between parchment.', NULL);
