INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (157, 'Creamy Chicken and Spinach Quesadillas', 'Budget Bytes', 'https://www.budgetbytes.com/creamy-chicken-and-spinach-quesadillas/', 35, 30, 0, 2, 4, 1, 4.0, 'quesadilla', '1. Cover the chicken breast with plastic wrap and pound it to an even thickness. | 2. Mix the chili powder, cumin, garlic powder and salt and rub it over both sides of the chicken. | 3. Cook the chicken in 1 Tbsp oil in a skillet over medium heat about 5 minutes per side, until it reaches 165 degrees F inside, then rest it 5 minutes and chop it small. | 4. Roughly chop the spinach and stir it together with the chicken, shredded cheese and sour cream. | 5. Spread the filling over half of each tortilla and fold closed. | 6. Cook one or two at a time in a skillet over medium heat 3 to 5 minutes per side until crisp, browned and melted inside, then cut in half.', NULL);
