INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (158, 'Hawaiian Ham Quesadillas', 'Budget Bytes', 'https://www.budgetbytes.com/hawaiian-ham-quesadillas/', 25, 25, 0, 9, 9, 0, 9.0, 'serving', '1. Let the cream cheese soften to room temperature, then stir it with the shredded mozzarella, sliced green onions and red pepper flakes until combined. | 2. Drain the pineapple as thoroughly as you can and chop it small, chop the ham small, and stir both into the cheese mixture. | 3. Spread 1/4 to 1/3 cup of filling over half of each tortilla and fold in half. | 4. Cook each quesadilla in a skillet over medium heat until browned and crisp on both sides.', NULL);
