INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (159, 'Kimchi Quesadillas', 'Budget Bytes', 'https://www.budgetbytes.com/kimchi-quesadillas/', 20, 20, 0, 2, 2, 0, 2.0, 'serving', '1. Roughly chop the kimchi, then cover half of each tortilla with cheese and top with the kimchi. | 2. Melt the butter in a large skillet over medium heat and fry or scramble the eggs the way you like them. | 3. Lay the cooked eggs on the kimchi and fold the empty half of each tortilla over the filling. | 4. Return the quesadillas to the skillet and cook over medium heat until the cheese melts and both sides are browned and crisp. | 5. Slice in half and serve.', NULL);
