INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (160, 'Mediterranean Quesadillas', 'Budget Bytes', 'https://www.budgetbytes.com/mediterranean-quesadillas/', 30, 30, 0, 10, 10, 0, 10.0, 'serving', '1. Thaw the spinach completely, press out as much moisture as possible in a colander, and put it in a large bowl. | 2. Thinly slice the red onion, cut the roasted red peppers into small strips, roughly chop the olives and parsley, and add everything to the spinach. | 3. Stir in the oregano, feta and mozzarella until evenly mixed. | 4. Spoon about 3/4 cup of filling onto half of each tortilla and fold the empty half over. | 5. Cook each quesadilla in a non-stick skillet over medium to medium-low heat until golden and crisp on both sides and the cheese has melted. To freeze, assemble without cooking and cook from frozen over lower heat.', NULL);
