INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (161, 'Chili Garlic Breakfast Quesadilla', 'Budget Bytes', 'https://www.budgetbytes.com/chili-garlic-breakfast-quesadilla/', 10, 10, 0, 1, 1, 0, 1.0, 'serving', '1. Melt the butter in a skillet over medium heat and fry the egg over-easy, or however you like it. | 2. Meanwhile, spread about 1 tsp chili garlic sauce over half of the tortilla and sprinkle 1/4 cup shredded cheddar on top. | 3. Slide the egg onto the cheese, add the spinach, and fold the tortilla closed. | 4. Return the quesadilla to the skillet over medium heat and cook both sides until golden and crisp and the cheese has melted, then cut in half.', NULL);
