INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (162, 'Green Chile Breakfast Quesadillas', 'Budget Bytes', 'https://www.budgetbytes.com/green-chile-breakfast-quesadillas/', 20, 20, 0, 2, 4, 1, 4.0, 'quesadilla', '1. Drain the green chiles well and mix them with the shredded cheese and chopped cilantro. | 2. Cook the four eggs in a large skillet, over easy or any way you like. | 3. Spread 1/4 of the filling over half of each tortilla, top with an egg, and fold in half. | 4. Cook two quesadillas at a time in the skillet over medium heat until golden and crisp on both sides and the cheese has melted, then cut in half or thirds and serve hot.', NULL);
