INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (163, 'Chicken Club Sandwich', 'Budget Bytes', 'https://www.budgetbytes.com/chicken-club-sandwich/', 35, 25, 0, 4, 4, 0, 4.0, 'sandwich', '1. Preheat the oven to 400 degrees F and set a wire rack on a foil-lined baking sheet. | 2. Bake the bacon on the rack about 25 minutes, until crisp, then drain it on paper towels. | 3. Meanwhile, slice each chicken breast into two thinner cutlets, pound them to an even thickness under plastic wrap, and season with 3/4 tsp salt, 1/2 tsp pepper and 1/2 tsp garlic powder. | 4. Cook the chicken in 2 Tbsp olive oil in a large skillet over medium heat about 4 minutes per side, until golden and cooked through, then keep it covered and warm. | 5. Toast the bread, slice the tomatoes, dry the lettuce, and slice the chicken into strips. | 6. Spread mayo thinly on two bread slices per sandwich and layer lettuce, tomato, chicken, cheese and bacon on one, add the second slice and repeat, then top with a third toasted slice. Cut in half and serve.', NULL);
