INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (164, 'Chicken Caesar Wraps', 'Budget Bytes', 'https://www.budgetbytes.com/chicken-caesar-wrap/', 25, 25, 0, 4, 4, 0, 4.0, 'serving', '1. Cut the chicken into 1/2-inch pieces and toss with 1 Tbsp olive oil, 1 Tbsp Parmesan, the Italian seasoning, garlic powder, salt and pepper. | 2. Cook the chicken in 1 Tbsp olive oil in a large skillet over medium heat about 5 minutes until browned and cooked through, then let it cool. | 3. Cook the butter, panko and seasonings in a small skillet over medium heat about 3 minutes until golden, then cool. | 4. Toss the chopped romaine, halved tomatoes, 1/2 cup Parmesan, cooled chicken, breadcrumbs and 1/3 cup Caesar dressing in a bowl. | 5. Warm the tortillas in the microwave about 15 seconds, divide the filling among them, fold in the bottom and sides, and roll up. Slice in half and serve.', NULL);
