INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (165, 'Greek Chicken Wraps', 'Budget Bytes', 'https://www.budgetbytes.com/greek-chicken-wraps/', 70, 40, 0, 6, 6, 0, 6.0, 'wrap', '1. Combine 1/4 cup olive oil, 1/4 cup lemon juice, the garlic, oregano, 1/2 tsp salt and cracked pepper in a zip-top bag or shallow dish, add the chicken thighs, coat well, and marinate 30 minutes or up to overnight. | 2. Stir together the Greek yogurt, dill, 1 Tbsp lemon juice and 1/4 tsp salt for the sauce and set it aside. | 3. Halve the tomatoes, dice the cucumber, and thinly slice the red onion, soaking the onion in ice water 5 to 10 minutes to mellow it. | 4. Cook the chicken in a skillet over medium heat 5 to 7 minutes per side in two batches until well browned and cooked through, rest it 5 minutes, then slice. | 5. Spread a couple of tablespoons of hummus on each flatbread, top with chicken, tomatoes, cucumber, onion and a few dollops of yogurt sauce, and wrap.', NULL);
