INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (166, 'Classic BLT Sandwich', 'Budget Bytes', 'https://www.budgetbytes.com/classic-blt-sandwich/', 30, 15, 0, 2, 2, 0, 2.0, 'sandwich', '1. Bake the bacon in a 400 degrees F oven for 20 to 25 minutes, until crisp. | 2. While it bakes, spread a thin layer of mayo (about 1 Tbsp per 2 slices) on both sides of the 4 bread slices. | 3. Tear the lettuce to fit the bread and slice the tomato. | 4. Toast the bread in a pan over medium heat about 3 minutes per side. | 5. Spread the rest of the mayo on one side of each toasted slice. | 6. Layer lettuce, then 3 to 4 crumbled bacon slices, then 2 tomato slices seasoned with salt and pepper per sandwich, and close with the second slice, mayo side down.', NULL);
