INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (167, 'Sriracha Chickpea Salad Wraps', 'Budget Bytes', 'https://www.budgetbytes.com/sriracha-chickpea-salad-wraps/', 15, 15, 0, 2, 2, 0, 2.0, 'serving', '1. Drain the chickpeas into a bowl and add the mayo, sriracha, cilantro, lemon juice and salt, starting with less sriracha if you are sensitive to heat. | 2. Mash the chickpeas until fairly broken down and well mixed with the dressing. | 3. Lay out the tortillas and divide the spinach, carrot, bell pepper and half of the chickpea salad between them. | 4. Fold the sides in and roll up from the bottom like a burrito, then serve right away or chill until ready to eat.', NULL);
