INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (169, 'The Best Veggie Sandwich', 'Budget Bytes', 'https://www.budgetbytes.com/how-to-make-the-ultimate-veggie-sandwich/', 10, 10, 0, 1, 1, 0, 1.0, 'sandwich', '1. Stir the cream cheese, sliced green onion, lemon juice, garlic powder, dill and a pinch of salt together in a small bowl with a fork. | 2. Lightly toast the bread and spread the scallion cream cheese on one side of each slice. | 3. Layer on the cucumber, tomato, spinach, carrot, bell pepper and alfalfa sprouts, season with a pinch each of salt and pepper, close the sandwich, and slice in half.', NULL);
