INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (170, 'BBQ Bean Sliders', 'Budget Bytes', 'https://www.budgetbytes.com/bbq-bean-sliders/', 30, 30, 0, 4, 6, 0, 4.0, 'serving', '1. Dice the onion and mince the garlic, then cook them in the olive oil in a large skillet over medium heat for about 5 minutes, until the onion is soft and translucent. | 2. Rinse and drain the black and pinto beans, add them to the skillet with the BBQ sauce and smoked paprika, and warm over medium-low heat, stirring now and then. | 3. Put the coleslaw mix in a large bowl and slice the green onions into it. | 4. Whisk the mayonnaise, honey, Dijon, vinegar, salt and pepper until smooth, pour it over the slaw, and toss. | 5. Fill each bun with a heaping 1/2 cup of beans and top with 1/2 cup of slaw. Keep leftover beans 4 to 5 days in the fridge and dress the slaw just before serving.', NULL);
