INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (171, 'Vegetarian French Dip Sandwiches', 'Budget Bytes', 'https://www.budgetbytes.com/vegetarian-french-dip-sandwiches/', 35, 35, 0, 4, 4, 0, 4.0, 'serving', '1. Thinly slice the onion, and cut the portobello caps in half and then crosswise into 1/4-inch strips. | 2. Saute the onion with the butter in a deep skillet over medium heat for a few minutes until it starts to soften. | 3. Add the mushrooms, salt, pepper, thyme and oregano and saute about 10 minutes, until the liquid cooks off and browned bits form on the bottom. | 4. Pour in the broth, soy sauce, brown sugar and garlic powder, scraping up the browned bits, bring to a simmer, then cook on low about 5 minutes. | 5. Meanwhile, broil the open rolls on the middle rack about 5 minutes until lightly browned at the edges. | 6. Lift the mushrooms and onions out of the broth with a slotted spoon, divide among the rolls, top each with a slice of provolone, and broil a few more minutes until the cheese melts. Serve with the broth for dipping.', NULL);
