INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (172, 'Cottage Cheese Wraps', 'Budget Bytes', 'https://www.budgetbytes.com/cottage-cheese-wraps/', 30, 15, 0, 2, 2, 0, 2.0, 'serving', '1. Preheat the oven to 350 degrees F. | 2. Blend the cottage cheese, Italian herb mix, garlic powder, onion powder and eggs until smooth. | 3. Spread the mixture into a thin rectangle on a parchment-lined baking sheet. | 4. Bake 20 to 30 minutes, until the top is toasty but not burnt, then let it cool on the pan. | 5. Flip it onto a clean surface, peel off the parchment, and cut the rectangle in half to make two wraps. | 6. Roll each wrap around your favorite savory sandwich fillings. Wraps keep up to 3 days in the fridge with parchment between them, without fillings.', NULL);
