INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (173, 'Avocado Toast', 'Budget Bytes', 'https://www.budgetbytes.com/avocado-toast/', 10, 10, 0, 1, 2, 1, 2.0, 'slice', '1. Toast the bread until golden brown. | 2. While the toast is still warm, rub the cut garlic clove across the surface of each slice. | 3. Scoop the avocado flesh into a bowl, add the lemon juice, salt and pepper, and mash with a fork, leaving it a bit chunky if you like. | 4. Divide the mashed avocado between the toast slices and finish with crushed red pepper and, if you like, a pinch of sea salt.', NULL);
