INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (174, 'Ham and Cheese Sliders', 'Budget Bytes', 'https://www.budgetbytes.com/ham-and-cheese-sliders/', 30, 30, 0, 6, 6, 0, 12.0, 'slider', '1. Heat the oven to 350 degrees F and slice the rolls in half horizontally. | 2. Set the bottom halves in a 9x13-inch baking dish and top each with a slice of ham. | 3. Lay the Swiss slices over the ham in one slightly overlapping layer. | 4. Melt the butter in the microwave, then whisk in the Dijon, Worcestershire and everything bagel seasoning. | 5. Put the roll tops on, brush the butter mixture over the tops and sides in several coats, or pour it over if you have no brush. | 6. Cover loosely with foil and bake 15 minutes, then uncover and bake 5 to 7 minutes more until lightly golden. Leftovers keep up to 4 days in the fridge.', NULL);
