INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (175, 'Black Bean Burgers', 'Budget Bytes', 'https://www.budgetbytes.com/black-bean-burgers/', 45, 45, 0, 6, 6, 0, 6.0, 'burger', '1. Roughly chop the onion, garlic and cilantro. | 2. Rinse and drain the beans well, then pulse them in a food processor with the chopped aromatics, sriracha, mayonnaise, cumin, soy sauce and pepper until mixed but still a little chunky. | 3. Move the mixture to a bowl, stir in the egg and breadcrumbs, and let it rest about 5 minutes so the crumbs absorb moisture. | 4. Divide into six portions and shape each into a patty about 3.5 inches wide and 1/2 inch thick. | 5. Cook the patties in a skillet with 1 Tbsp oil over medium heat 4 to 5 minutes per side until well browned and 160 degrees F in the center, adding the remaining oil for the second batch. | 6. Serve on buns with your favorite toppings. Cooked patties keep 3 to 4 days in the fridge, and uncooked patties freeze up to 3 months.', NULL);
