INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (176, 'Lentil Burgers', 'Budget Bytes', 'https://www.budgetbytes.com/lentil-burgers/', 70, 35, 0, 4, 4, 0, 4.0, 'patty', '1. Heat the oven to 400 degrees F. Bring the water to a simmer, add the lentils, and cook with the lid tilted open about 20 minutes until tender but not mushy, then drain and rinse with cold water. | 2. Put about 1 1/4 cups of the cooked lentils in a food processor with the garlic, tomato paste, salt, pepper, paprika and cumin and pulse into a thick paste. | 3. Scrape the paste into a bowl and fold in the remaining lentils, grated carrot, grated onion and flour. | 4. Divide into four portions and press each into a patty about 1/2 inch thick. | 5. Set the patties on a parchment-lined sheet pan sprayed with nonstick spray and spray the tops too. | 6. Bake about 15 minutes, flip, spray again, and bake about 15 minutes more. | 7. Serve on buns with your toppings. Cooled patties keep 3 to 4 days in the fridge and freeze 2 to 3 months.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (176, 1, NULL, 'lentil', 1.5, 1.5, 'cup', 'dry brown', NULL, 0, '1½ cups dry brown lentils (250g)');
