INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (177, 'Easy BBQ Chicken Sandwiches', 'Budget Bytes', 'https://www.budgetbytes.com/easy-bbq-chicken-sandwiches/', 25, 25, 0, 4, 4, 0, 4.0, 'sandwich', '1. Mix the smoked paprika, garlic powder, salt and pepper in a small bowl. Halve any large chicken thighs to get four sandwich-sized pieces and season both sides with the spice mix. | 2. Heat the oil in a large skillet over medium heat and cook the chicken 5 to 7 minutes per side until well browned and cooked through. | 3. Take the pan off the heat and brush BBQ sauce on both sides of each piece. | 4. Stir the coleslaw mix, sliced green onions and ranch dressing together until the slaw is coated. | 5. Put a piece of chicken on each bun and top with a generous scoop of the ranch slaw. Keep leftover chicken in its own container up to 4 days.', NULL);
