INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (180, 'Ramen Noodle Salad', 'Budget Bytes', 'https://www.budgetbytes.com/ramen-noodle-salad/', 30, 30, 0, 6, 6, 0, 6.0, 'serving', '1. Whisk all the vinaigrette ingredients together and set the dressing aside. | 2. Shred the cabbage very finely, shred the carrot, and slice the green onions. Crush the dry ramen noodles and discard the seasoning packet or save it for another use. | 3. Combine the cabbage, carrot, green onions, almonds, crushed ramen and shredded chicken in a large bowl. | 4. Pour the dressing over and toss until everything is coated. Serve right away or refrigerate; it keeps 3 to 4 days, and the noodles stay crunchier if added at serving time.', NULL);
