INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (181, 'Smoky Quinoa and Black Bean Salad', 'Budget Bytes', 'https://www.budgetbytes.com/smoky-quinoa-black-bean-salad/', 40, 20, 1, 4, 6, 1, NULL, NULL, '1. Rinse the quinoa in a fine-mesh sieve, drain it, and put it in a saucepan with 1 3/4 cups water. | 2. Cover, bring to a boil over high heat, then reduce to low and simmer 15 minutes. Turn off the heat, leave it covered 5 minutes, fluff with a fork and let it cool. | 3. Whisk the olive oil, vinegar, smoked paprika, cumin, garlic powder, salt and pepper together for the dressing. | 4. Rinse and drain the beans, dice the bell peppers, and slice the green onions. | 5. Toss the beans, peppers, green onions and cooled quinoa with the dressing, taste, and add salt if needed. It keeps well in the fridge through the week.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (181, 1, NULL, 'quinoa', 1.0, 1.0, 'cup', 'uncooked', NULL, 0, '1 cup uncooked quinoa');
