INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (182, 'Sesame Ground Turkey Bowls', 'Spend With Pennies', 'https://www.spendwithpennies.com/sesame-ground-turkey-bowls/', 30, 30, 0, 4, 4, 0, 4.0, 'serving', '1. Brown the turkey with the ginger and garlic until no pink remains, then drain the fat. | 2. While it browns, stir together the water, broth, soy sauce, brown sugar, sriracha and sesame oil and set it aside. | 3. Add the coleslaw mix to the turkey and cook 2 to 3 minutes until slightly softened. | 4. Push the turkey and slaw to the edges of the pan, stir the sauce, pour it into the center, and heat until bubbling. | 5. Stir 1 Tbsp each of cornstarch and water into a slurry, whisk it into the sauce until thickened, and simmer 2 minutes. | 6. Spoon over rice or noodles and top with hoisin, green onions and sesame seeds. Leftovers keep 3 to 4 days in the fridge or freeze up to 4 weeks.', NULL);
