INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (183, 'Taco Quinoa Bowls', 'Spend With Pennies', 'https://www.spendwithpennies.com/taco-quinoa-bowl/', 45, 35, 0, 4, 4, 0, 4.0, 'bowl', '1. Rinse the quinoa until the water runs clear, then combine it with the broth and one whole green onion in a saucepan. Bring to a boil, reduce the heat, cover, and simmer about 25 minutes. | 2. While the quinoa cooks, brown the ground meat and diced onion in a frying pan until no pink remains. | 3. Stir in the taco seasoning and water and simmer until the mixture thickens. | 4. Divide the quinoa among four bowls, removing the whole green onion, and top with the seasoned meat, the drained corn, the sliced green onion and any other toppings. Assembled bowls keep about 4 days in the fridge.', NULL);
