INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (184, 'Classic Chicken Salad', 'Spend With Pennies', 'https://www.spendwithpennies.com/classic-chicken-salad-recipe/', 15, 15, 0, 6, 6, 0, 6.0, 'serving', '1. Chop the cooked, cooled chicken and put it in a large bowl with the celery and green onion. | 2. Mix the mayonnaise, Dijon, seasoned salt, pepper and dill in a separate bowl and toss it with the chicken. | 3. Taste and add more salt and pepper if you like. | 4. Serve on rolls or bread or over lettuce. It keeps up to 5 days in the fridge.', NULL);
