INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (187, 'Ham and Cheese Pockets', 'Taste of Home', 'https://www.tasteofhome.com/recipes/ham-and-cheese-pockets/', 90, 30, 1, 10, 10, 0, 10.0, 'pocket', '1. Let the dough rise following the package directions, then punch it down and cut it into 10 pieces. Roll each piece on a lightly floured surface into a 5-inch circle. | 2. Heat the oven to 375 degrees F. Set a circle on a greased baking sheet, top it with about 1/4 cup ham and 2 Tbsp Swiss, keeping the filling 1/2 inch from the edge, and press the filling flat. | 3. Whisk the egg yolk and water, brush it on the edges, fold the dough over the filling, and pinch the edges shut. Repeat with the rest, then brush the tops with the leftover egg mixture. | 4. Bake 15 to 20 minutes until golden brown and serve warm or cold.', NULL);
