INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (188, 'Sheet Pan Honey Mustard Chicken Thighs and Broccoli', 'Cheap Recipe Blog', 'https://www.cheaprecipeblog.com/2026/03/sheet-pan-honey-mustard-chicken-thighs-with-broccoli/', 40, 20, 0, 4, 4, 0, 4.0, 'serving', '1. Put the chicken thighs in a large bowl. In another bowl whisk the honey, mustard, garlic powder, red pepper flakes, salt, pepper, bouillon paste dissolved in the hot water, and vinegar, then pour it over the chicken, cover, and marinate (overnight is best; even 30 minutes helps). | 2. Heat the oven to 415 degrees F and lightly oil a sheet pan. Lay the chicken on one half of the pan and drizzle with the marinade. | 3. Toss the broccoli with the oil, salt and garlic powder and spread it on the other half of the pan. | 4. Bake 30 to 35 minutes until the chicken is browned and at least 165 degrees F. Leftovers keep 3 to 4 days in the fridge.', NULL);
