INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (189, 'French Toast', 'Budget Bytes', 'https://www.budgetbytes.com/french-toast/', 15, 15, 0, 4, 4, 0, 8.0, 'slice', '1. Whisk the eggs, milk, vanilla, cinnamon and salt until the mixture runs smoothly off a fork. | 2. Warm a nonstick pan over medium-low heat, add 3 Tbsp butter and 1/2 Tbsp oil, and heat until the butter foams. | 3. Dip each bread slice in the custard to coat both sides and let it soak until heavy and spongy but not dripping. | 4. Lay the slices in the pan, sprinkle the tops with a pinch of sugar, and cook until the bottoms are browned, then flip and sprinkle the browned side with sugar. | 5. Flip once more when the center springs back, caramelize the sugar briefly, and repeat with the remaining slices, adding butter and oil as needed. Serve warm.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (189, 1, NULL, 'egg', 3.0, 3.0, 'each', 'large', NULL, 0, '3 large eggs*');
