INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (190, 'Tortilla Baked Eggs', 'Budget Bytes', 'https://www.budgetbytes.com/tortilla-baked-eggs/', 30, 15, 0, 2, 2, 0, 2.0, 'serving', '1. Heat the oven to 350 degrees F, brush a 7-inch oven-safe dish with olive oil, and press the tortilla into it so the edges fold up the sides. | 2. Roughly chop the spinach and put it in the tortilla, then crack the eggs over it and season with salt and pepper. | 3. Halve the grape tomatoes, scatter them over the eggs, and top with the cheddar. | 4. Bake 20 to 25 minutes, until the whites are set and the yolks are still jammy. | 5. Slide the tortilla out of the dish, cut it into four pieces, and finish with crushed red pepper if you like.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (190, 1, NULL, 'olive oil', 0.5, 0.5, 'tbsp', NULL, NULL, 0, '1/2 Tbsp olive oil');
