INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (191, 'Sausage and Egg Breakfast Quesadillas', 'Budget Bytes', 'https://www.budgetbytes.com/sausage-and-egg-breakfast-quesadillas/', 25, 25, 0, 3, 6, 1, 6.0, 'quesadilla', '1. Brown the sausage in a skillet over medium heat until the edges crisp, then lift it out with a slotted spoon and leave the grease in the pan. | 2. Whisk the eggs with the salt and pepper and shred the cheddar. | 3. Scramble the eggs in the sausage grease over medium heat, folding gently, and take the pan off the heat while they are still moist. | 4. Fold the sausage and cheese into the eggs, then spread about 1/2 cup of filling over half of each tortilla and fold closed. They can be cooked now or frozen. | 5. Cook the quesadillas in a dry skillet over medium heat until browned, crisp and melty, then cut each into three pieces.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (191, 1, NULL, 'breakfast sausage', 8.0, 8.0, 'oz', NULL, NULL, 0, '8 oz country sausage');
