INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (192, 'Cheese Grits', 'Budget Bytes', 'https://www.budgetbytes.com/cheese-grits/', 15, 15, 0, 4, 4, 0, 4.0, 'serving', '1. Combine the broth, milk and garlic powder in a medium saucepan, cover, and bring to a boil over medium-high heat, stirring now and then so the milk does not scorch. | 2. Stir in the grits and salt, drop the heat to medium-low, and simmer about 5 minutes until thickened. | 3. Take the pan off the heat and stir in the butter and pepper. | 4. Stir in the cheddar a handful at a time until melted and serve warm.', NULL);
