INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (193, 'Garlic Noodles', 'Budget Bytes', 'https://www.budgetbytes.com/garlic-noodles/', 25, 25, 0, 4, 4, 0, 4.0, 'serving', '1. Whisk the oyster sauce, brown sugar, soy sauce and sesame oil together in a bowl. | 2. Cook the pasta in boiling water per the package directions, then drain. | 3. Mince the garlic and slice the green onions, saving some of the onion for garnish. | 4. Melt the butter in a large skillet over medium-low heat and saute the garlic and most of the onions 1 to 2 minutes until soft and fragrant, without browning the garlic. | 5. Take the pan off the heat, add the pasta and sauce, and toss until coated, adding a little hot or pasta water if the noodles are sticky. | 6. Top with the reserved green onions. Leftovers keep 3 to 4 days in the fridge; do not freeze.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (193, 1, NULL, 'oyster sauce', 2.0, 2.0, 'tbsp', NULL, NULL, 0, '2 tablespoons oyster sauce');
