INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (194, 'Spaghetti Aglio e Olio', 'Budget Bytes', 'https://www.budgetbytes.com/spaghetti-aglio-e-olio/', 20, 20, 0, 8, 8, 0, 8.0, 'serving', '1. Bring a large pot of water to a boil, season it with 1/2 tsp salt, and cook the spaghetti until al dente, about 10 minutes. Drain, keeping 1/4 cup of the pasta water. | 2. In a large saucepan over medium-low heat, cook the sliced garlic with the black pepper, 1/2 tsp salt and red pepper in the olive oil for about 2 minutes until fragrant, without burning it. | 3. Add the spaghetti to the garlic oil and toss to coat every strand. | 4. Add the Parmesan, parsley, lemon juice and 2 Tbsp of the pasta water and toss until the cheese melts into a sauce, adding more pasta water if you want it looser. Leftovers keep up to 3 days; add a splash of water when reheating.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (194, 1, NULL, 'spaghetti', 1.0, 1.0, 'lb', NULL, NULL, 0, '1 lb spaghetti');
