INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (195, 'Quick Veggie Pasta', 'Budget Bytes', 'https://www.budgetbytes.com/quick-veggie-pasta/', 25, 25, 0, 4, 4, 0, 4.0, 'serving', '1. Boil the pasta until tender, about 7 minutes, keep 1/2 cup of the pasta water, and drain. | 2. While the water heats, slice the mushrooms and halve the tomatoes. | 3. Saute the mushrooms with a pinch of salt in the oil over medium heat 5 to 7 minutes, until they release their liquid and the pan is dry. | 4. Add the tomatoes and cook about 2 minutes, then add the spinach and cook until wilted. | 5. Add the pasta and butter, toss to coat, and turn off the heat. | 6. Season with garlic powder, nutritional yeast, salt and pepper, toss, taste, and add a splash of the pasta water if it seems dry.', NULL);
