INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (197, 'Classic Three Bean Salad', 'Budget Bytes', 'https://www.budgetbytes.com/classic-three-bean-salad/', 45, 15, 0, 5, 5, 0, 5.0, 'serving', '1. Rinse and drain the kidney and cannellini beans and combine them in a bowl with the thawed green beans. | 2. Soak the sliced red onion in ice water about 5 minutes, drain and finely dice it, chop the parsley, and add both to the beans. | 3. Whisk the vinegar, sugar, olive oil, salt, pepper and Dijon in a separate bowl. | 4. Pour the dressing over the beans and stir to combine. | 5. Refrigerate about 30 minutes, then stir before serving. It keeps about 4 days in the fridge and tastes better the longer it chills.', NULL);
