INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (198, 'Tuscan White Bean Pasta', 'Budget Bytes', 'https://www.budgetbytes.com/tuscan-white-bean-pasta/', 30, 30, 0, 4, 4, 0, 4.0, 'serving', '1. Boil the pasta per the package directions and drain it. | 2. While the water heats, mince the garlic, then saute it in the olive oil and butter over medium-low heat about a minute until soft and fragrant. | 3. Add the tomatoes, salt, pepper and basil and cook until the tomatoes burst and release their juices, keeping the heat moderate so the garlic caramelizes without burning. | 4. Stir in the spinach and cook until about half wilted. | 5. Rinse and drain the beans, add them, and heat through so the tomato juices form a thick sauce; taste and add salt if needed. | 6. Toss in the drained pasta, then top with the Parmesan and a little more at the table.', NULL);
