INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (199, 'One Pot Creamy Mushroom Pasta', 'Budget Bytes', 'https://www.budgetbytes.com/one-pot-creamy-mushroom-pasta/', 30, 30, 0, 4, 4, 0, 4.0, 'serving', '1. Mince the garlic and slice the mushrooms. | 2. Melt the butter in a deep skillet over medium heat and cook the garlic about a minute. | 3. Add the mushrooms, salt and pepper and saute until they soften, their liquid cooks off and the edges brown. | 4. Add the fettuccine and vegetable broth, cover, raise the heat to medium-high, and bring to a boil. | 5. Stir, replace the lid, lower the heat to medium-low, and simmer about 10 minutes, stirring now and then, until the pasta is tender with a little saucy liquid left. | 6. Stir in the cream, turn off the heat, stir in the Parmesan until it melts, and adjust the seasoning. Leftovers keep up to 3 days; loosen with a splash of water or broth when reheating.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (199, 1, NULL, 'garlic', 4.0, 4.0, 'clove', 'minced', NULL, 0, '4 cloves garlic, minced');
