INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (200, 'Buffalo Chicken Grilled Cheese', 'Budget Bytes', 'https://www.budgetbytes.com/buffalo-chicken-grilled-cheese/', 14, 14, 0, 1, 1, 0, 1.0, 'sandwich', '1. Preheat a skillet over medium heat for 2 to 3 minutes. | 2. Whisk the melted butter, hot sauce, Worcestershire and garlic powder together. | 3. Warm the chicken in the microwave in 30-second bursts, adding a splash of water or broth if it is cold, then fold the sauce into it until coated. | 4. Spread the mayo thinly over both sides of the bread out to the edges and lay two slices of American cheese on each slice. | 5. Spoon the chicken onto one slice, close the sandwich with the second slice cheese side in, and cook in the dry skillet about 2 minutes per side until golden and crisp and the cheese has melted. | 6. Cut in half and serve with blue cheese dressing for dipping.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (200, 1, 'sandwich', 'American cheese', 4.0, 4.0, 'slice', NULL, NULL, 0, '4 slices American cheese');
