INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (201, 'Pizza Burgers', 'Budget Bytes', 'https://www.budgetbytes.com/pizza-burgers/', 30, 30, 0, 6, 6, 0, 12.0, 'half', '1. Heat the oven to 350 degrees F, split the English muffins, and toast the halves cut side up on a baking sheet about 5 minutes. | 2. Heat the olive oil in a saute pan and cook the frozen peppers and onions until soft and the liquid has cooked off. | 3. Add the ground meat, breaking it up as it browns, until no pink remains (160 degrees F), then blot or spoon off the excess fat. | 4. Stir in the marinara and Italian seasoning and simmer over medium-low heat until hot and thick enough to mound. | 5. Spoon the meat sauce onto the 12 muffin halves, top each with mozzarella and, if you like, quartered pepperoni. | 6. Bake 8 to 10 minutes until the cheese melts and browns at the edges. The cooled meat mixture keeps 3 to 4 days in the fridge or 3 months in the freezer.', NULL);
