INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (202, 'Baked Chicken Drumsticks', 'Budget Bytes', 'https://www.budgetbytes.com/baked-chicken-drumsticks/', 45, 10, 0, 3, 6, 1, 6.0, 'drumstick', '1. Heat the oven to 425 degrees F and mix the smoked paprika, garlic powder, onion powder, cayenne, oregano, salt and pepper in a bowl. | 2. Toss the drumsticks with the oil in a large bowl, then sprinkle on the spice mix and toss until coated. | 3. Space the drumsticks out on a baking sheet so they do not touch. | 4. Bake about 40 minutes, flipping once halfway, until the thickest part reaches 175 degrees F, then serve hot. Leftovers keep 3 to 4 days in the fridge or 2 to 3 months in the freezer.', NULL);
