INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (203, 'Ground Beef Fajitas', 'Budget Bytes', 'https://www.budgetbytes.com/ground-beef-fajitas/', 30, 30, 0, 4, 4, 0, 8.0, 'fajita', '1. Mix the chili powder, cumin, smoked paprika, garlic powder, salt and pepper in a small bowl, and slice the bell peppers and onion into thin strips. | 2. Brown the ground beef in a large skillet over medium heat and drain the excess fat. | 3. Stir in the seasoning mix and water, cook 2 to 3 minutes, and move the beef to a plate. | 4. Add the oil, peppers and onion to the same skillet and saute 3 to 4 minutes so they stay slightly crisp. | 5. Return the beef to the skillet, heat through, and finish with the cilantro and a squeeze of lime. | 6. Serve in warmed fajita-size tortillas. The filling keeps 3 to 4 days in the fridge and freezes up to 3 months.', NULL);
