INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (204, 'Spicy Peanut Butter Ramen Noodles', 'Budget Bytes', 'https://www.budgetbytes.com/spicy-peanut-butter-ramen/', 10, 10, 0, 1, 1, 0, 1.0, 'serving', '1. Stir the peanut butter, chili garlic sauce, soy sauce and brown sugar together in a bowl until smooth. | 2. Bring a small pot of water to a boil and stir 1/4 cup of the boiling water into the peanut mixture to make a smooth, pourable sauce. | 3. Cook the ramen noodles (without the seasoning packet) in the boiling water 2 to 3 minutes until tender. | 4. Drain the noodles, return them to the pot off the heat, pour the sauce over, and stir to coat. | 5. Top with sliced green onion and eat right away.', NULL);
