INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (205, 'Tuscan Orzo', 'Budget Bytes', 'https://www.budgetbytes.com/tuscan-orzo/', 30, 30, 0, 4, 4, 0, 4.0, 'serving', '1. Heat the olive oil and butter in a pot over medium-high heat and cook the chopped onion 3 to 4 minutes. | 2. Add the garlic, Italian seasoning, tomatoes, lemon juice, Dijon and orzo and cook 3 minutes, stirring often. | 3. Stir in the broth and room-temperature cream, and when it bubbles lower the heat to medium-low and simmer uncovered 10 minutes, stirring now and then, so it simmers gently without boiling dry. | 4. Take the pot off the heat, stir in the Parmesan, spinach and parsley, cover, and let it rest a few minutes to thicken; simmer a bit longer if it is still watery. | 5. Season with salt and pepper to taste.', NULL);
