INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (206, 'Dan Dan Noodles', 'Budget Bytes', 'https://www.budgetbytes.com/dan-dan-noodles/', 30, 30, 0, 4, 4, 0, 4.0, 'serving', '1. Cook the spaghetti in boiling salted water until al dente, about 2 minutes under the package time, keep 1 cup of the pasta water, and drain. | 2. Heat the oil in a large skillet over medium-high heat, add the pork, and press it flat without stirring for a few minutes to brown a crisp base. | 3. Add the garlic, ginger, soy sauce, brown sugar and spinach and stir-fry until combined and hot, then take the pan off the heat. | 4. Whisk the sauce soy sauce, rice vinegar, peanut butter, chili crisp, brown sugar and about half the reserved pasta water until smooth. | 5. Toss the noodles in the sauce, adding more pasta water as needed so it coats without clumping, and crush the peanuts in a sealed bag with a rolling pin. | 6. Divide the noodles among bowls and top with the pork, green onions and peanuts. Store the noodles and pork separately; they keep 3 to 4 days.', NULL);
