INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (207, 'Vegetable Barley Soup', 'Budget Bytes', 'https://www.budgetbytes.com/vegetable-barley-soup/', 55, 30, 0, 6, 6, 0, 6.0, 'serving', '1. Saute the onion and garlic in the olive oil over medium heat about 5 minutes until soft and translucent. | 2. Add the carrots, tomatoes, barley, basil, oregano, pepper and broth and stir. | 3. Cover, bring to a boil over medium-high heat, then lower to medium-low and simmer 30 minutes, stirring now and then. | 4. Add the diced potato and simmer 10 minutes more until tender. | 5. Stir in the green beans, corn and peas and heat through about 5 minutes. | 6. Stir in the lemon juice, adjust the seasoning, and serve hot, topped with parsley if you like. It freezes well.', NULL);
