INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (209, 'Navy Bean Soup', 'Budget Bytes', 'https://www.budgetbytes.com/navy-bean-soup/', 145, 30, 0, 6, 6, 0, 6.0, 'serving', '1. Soak the dry beans overnight in cold water in the fridge, then drain and rinse. For a quick soak, boil the rinsed beans 2 minutes, cover, leave off the heat 1 hour, then drain and rinse. | 2. Dice the onion, carrot and celery and mince the garlic. | 3. Saute the vegetables and garlic in the olive oil in a large pot over medium heat until the onion is soft and translucent. | 4. Add the beans, ham hock, thyme, oregano, rosemary, paprika, pepper and broth and stir. | 5. Cover, bring to a boil, then simmer on medium-low about 1.5 hours, stirring now and then and turning the ham hock once or twice, until the beans are tender and starting to break down. | 6. Lift out the ham hock, pull the meat off the bone, and return the meat to the pot. | 7. Mash some of the beans against the side of the pot, stir them in, and simmer uncovered about 30 minutes to thicken. Taste, add salt as needed, and serve hot. It keeps 4 to 5 days in the fridge or 3 months frozen.', NULL);
