INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (210, '1-Pot Chickpea Shakshuka', 'Minimalist Baker', 'https://minimalistbaker.com/1-pot-chickpea-shakshuka/', 30, 30, 0, 6, 6, 0, 4.0, 'cup', '1. Heat the oil in a large skillet over medium heat and saute the onion, bell pepper and garlic 4 to 5 minutes until soft and fragrant. | 2. Stir in the crushed tomatoes, tomato paste, sweetener, salt, paprika, cumin, chili powder, cinnamon and any optional spices and bring to a simmer, cooking 2 to 3 minutes. | 3. Add the chickpeas and olives, lower the heat to medium-low, and simmer 15 to 20 minutes so the flavors meld. | 4. Taste and adjust the paprika, cumin, cayenne, sweetener or olives, cooking longer if needed, and serve as is or over bread, rice or pasta. Leftovers keep 4 days in the fridge or 1 month frozen.', NULL);
