INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (211, '1-Pot Vegan Pasta', 'Minimalist Baker', 'https://minimalistbaker.com/one-pot-vegan-pasta/', 52, 30, 0, 4, 4, 0, 4.0, 'serving', '1. Dice the eggplant, salt it generously in a colander, and let it drain 20 to 30 minutes, then rinse and pat dry. If short on time, skip it and double the mushrooms. | 2. In a large saucepan over medium-high heat, cook the eggplant with the olive oil, one-third of the garlic and 1/2 tsp salt 3 to 5 minutes until golden, add the mushrooms for 2 minutes more, and set the vegetables aside covered. | 3. In the same pan combine the pasta, water, marinara, the rest of the garlic, 1 1/2 tsp salt and the pepper. | 4. Bring to a boil, cover, and simmer about 10 minutes, stirring once or twice, until the pasta is al dente. | 5. Taste and adjust the seasoning, then top with the reserved vegetables and fresh parsley or basil and serve right away. Leftovers keep 3 to 4 days.', NULL);
