INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (214, 'Crunchy Tuna Salad Wraps', 'Budget Bytes', 'https://www.budgetbytes.com/tuna-wrap/', 10, 10, 0, 3, 3, 0, 3.0, 'wrap', '1. Drain the tuna thoroughly, dice the celery, chop the walnuts, and slice the green onion. | 2. Stir the tuna, celery, walnuts, green onion, mayonnaise, lemon juice, pepper and salt together in a bowl. | 3. Tear the romaine and slice the tomato thin so the wrap holds together. | 4. Warm one tortilla at a time in the microwave 5 to 10 seconds until pliable. | 5. Layer romaine and one-third of the tomato on the tortilla, add one-third of the tuna salad, fold in the sides, and roll up tightly. | 6. Rest the wrap seam side down for a minute to seal and repeat with the other two. The tuna salad keeps up to 4 days; assembled wraps are best within 3.', NULL);
