INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (215, 'Mushroom Patty Melt', 'Budget Bytes', 'https://www.budgetbytes.com/mushroom-patty-melt/', 75, 45, 0, 4, 4, 0, 4.0, 'sandwich', '1. Heat the oven to 400 degrees F. Caramelize the thinly sliced onion in 1/4 cup of the oil over medium heat about 45 minutes, stirring now and then, then set it aside and wipe out the pan. | 2. Meanwhile, remove the stems and gills from the portobello caps and set them cap side down on a parchment-lined sheet. | 3. Whisk the garlic, balsamic vinegar, remaining oil, soy sauce and thyme, spoon it over the caps, and roast 20 minutes. Cool and slice. | 4. Spread mayo on all 8 bread slices, top each with Swiss and caramelized onions, put the mushrooms and salt on 4 of them, and close with the other slices. | 5. Melt 1 Tbsp butter in the skillet, toast two sandwiches 3 to 4 minutes, add another Tbsp butter, flip, and toast 3 to 4 minutes more; repeat with the rest. They keep up to 5 days in the fridge.', NULL);
