INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (216, 'Easy Egg Salad', 'Budget Bytes', 'https://www.budgetbytes.com/easy-egg-salad/', 25, 25, 0, 2, 2, 0, 2.0, 'serving', '1. Put the eggs in a saucepan, cover with water, cover the pan, and heat on high to a full boil, then turn off the heat and leave the eggs covered for 12 minutes. | 2. Cool the eggs in an ice bath or under cold water, peel them, and chop into 1/2-inch pieces. | 3. Stir the chopped eggs with the mayonnaise, relish, Dijon, lemon juice, salt and pepper, mashing some of the yolk into the dressing. | 4. Taste and adjust the seasoning, then serve right away or chill. It keeps 4 to 5 days in the fridge.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (216, 1, NULL, 'egg', 4.0, 4.0, 'each', 'large', NULL, 0, '4 large eggs');
