INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (217, 'Reuben Sandwiches', 'Budget Bytes', 'https://www.budgetbytes.com/reuben-sandwiches/', 22, 22, 0, 4, 4, 0, 4.0, 'sandwich', '1. Butter one side of each of the 8 bread slices. | 2. Turn the slices buttered side down and spread 1 to 2 Tbsp dressing on one slice of each pair, and about 1/4 cup well-drained sauerkraut on the other. | 3. Layer about 3 oz corned beef over the sauerkraut and top with 2 slices of Swiss, then close each sandwich with the other slice, buttered side out. | 4. Toast 1 to 2 sandwiches at a time in a large skillet over medium heat 2 to 3 minutes per side until the bread is golden, and serve hot.', NULL);
