INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (218, 'Easy French Bread Pizza', 'Budget Bytes', 'https://www.budgetbytes.com/french-bread-pizza/', 20, 20, 0, 4, 4, 0, 4.0, 'pizza', '1. Heat the oven to 400 degrees F, cut the loaf in half lengthwise, and open each half to make four pieces, set cut side up on a baking sheet. For a crisper base, bake them bare for 3 to 5 minutes first. | 2. Spread about 2 Tbsp of sauce and about 1/4 cup of mozzarella over each piece and add any toppings you like. | 3. Bake 10 to 15 minutes until the cheese is bubbly and the bread edges are golden and crisp. Leftovers keep 3 to 4 days in the fridge; the topped pizzas can be frozen before baking for up to 3 months.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (218, 1, NULL, 'French bread', 1.0, 1.0, 'loaf', '12 to 16 inches long', NULL, 0, 'One French loaf, about 12 to 16 inches long');
