INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (219, 'Angel Hair Pasta Pomodoro', 'Budget Bytes', 'https://www.budgetbytes.com/angel-hair-pasta-pomodoro/', 20, 20, 0, 8, 8, 0, 8.0, 'serving', '1. Boil a large pot of water with 1 Tbsp salt, dice the Roma tomatoes with their seeds and juice, and mince the garlic. | 2. Cook the angel hair about 2 minutes until just tender, reserve 1/2 cup of the pasta water, drain, and cover the pasta with a damp towel (toss with 1 Tbsp olive oil if you like). | 3. In a large saute pan over medium-low heat, cook the garlic and oregano in 1/4 cup olive oil about 2 minutes without browning. | 4. Add the tomatoes, stir, raise the heat to medium, and after about 5 minutes add the bouillon dissolved in 1 cup hot water along with the reserved pasta water, then bring to a low simmer. | 5. Stir in the salt, pepper, basil and parsley, take the pan off the heat, add the pasta, and toss well. Leftovers keep 3 to 4 days in the fridge; do not freeze.', NULL);
