INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (220, 'Taco Pasta', 'Budget Bytes', 'https://www.budgetbytes.com/beef-taco-pasta/', 30, 30, 0, 6, 6, 0, 6.0, 'serving', '1. Saute the diced onion and garlic in the olive oil over medium heat until soft. | 2. Add the ground beef and taco seasoning and cook until the beef is no longer pink. | 3. Stir in the diced tomatoes and green chiles with their juices. | 4. Add the uncooked pasta and beef broth, cover, bring to a full boil over medium-high heat, then stir, re-cover, and reduce to medium-low. | 5. Simmer about 10 minutes, stirring every few minutes with the lid on, until the pasta is tender and a thick sauce remains. | 6. Stir in the cheddar until melted and top with green onions. Leftovers keep 3 to 4 days in the fridge and freeze up to 3 months.', NULL);
