INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (221, 'Marry Me White Bean Skillet', 'Budget Bytes', 'https://www.budgetbytes.com/marry-me-white-bean-skillet/', 25, 25, 0, 4, 4, 0, 4.0, 'serving', '1. Warm the sun-dried tomato oil in a medium skillet over medium heat and cook the onion, garlic and red pepper flakes 2 to 3 minutes until soft and fragrant. | 2. Add the beans with their liquid, the broth, sun-dried tomatoes, salt and Italian seasoning and simmer about 15 minutes, mashing some of the beans with a spoon, until the liquid reduces a little. | 3. Stir in the spinach, cream, Parmesan and basil and simmer gently about 5 minutes until creamy and hot. | 4. Serve warm with crusty bread or over rice. Leftovers keep 3 to 4 days in the fridge or 3 months in the freezer.', NULL);
