INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (222, 'Easy Egg Drop Soup', 'Budget Bytes', 'https://www.budgetbytes.com/easy-egg-drop-soup/', 30, 30, 0, 6, 6, 0, 6.0, 'serving', '1. Slice the mushrooms and green onions and grate the ginger. | 2. Saute the mushrooms, green onions, ginger and oil in a large pot over medium heat until the mushrooms start to soften. | 3. Add the broth, water and soy sauce, and stir in the cornstarch dissolved in 1 Tbsp water. | 4. Bring to a boil while whisking the eggs in a bowl. | 5. Lower the heat until the boiling stops, stir the broth in one direction to make a gentle swirl, pour in the eggs in a thin stream, and leave undisturbed 1 to 2 minutes to set. | 6. Stir in the spinach until it wilts, taste for soy sauce, and serve hot. It keeps 3 to 4 days in the fridge; do not freeze.', NULL);
