INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (223, '30 Minute Posole', 'Budget Bytes', 'https://www.budgetbytes.com/30-minute-posole/', 30, 30, 0, 6, 6, 0, 6.0, 'serving', '1. Saute the diced onion in the oil over medium heat until soft and translucent. | 2. Stir in the flour and chili powder and cook about 2 minutes, stirring constantly, to make a roux. | 3. Whisk in the water, tomato paste, cumin, garlic powder, cayenne and salt until the paste dissolves, and bring to a simmer so it thickens. | 4. Add the broth, shredded meat, green chiles and drained hominy and heat through about 10 minutes, then taste and adjust the seasoning. | 5. Serve each bowl topped with chopped cilantro and a squeeze of lime. Leftovers keep 3 to 4 days in the fridge or 2 to 3 months in the freezer.', NULL);
