INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (225, 'Denver Omelet', 'Spend With Pennies', 'https://www.spendwithpennies.com/denver-omelet/', 25, 25, 0, 1, 1, 0, 1.0, 'omelet', '1. Whisk the eggs, milk, salt and pepper with a fork and set aside. | 2. Melt the butter in a 6-inch skillet over medium heat and cook the onion about 3 minutes until slightly soft. | 3. Add the ham and peppers and cook 3 to 5 minutes until the peppers are tender. | 4. Lower the heat to medium-low, pour in the eggs, and cook about 2 minutes, running a spatula around the edges and tilting the pan so raw egg flows underneath. | 5. When the eggs are nearly set, sprinkle on the cheese, cover the pan, and cook 5 to 6 minutes until the top is set and the cheese has melted. | 6. Fold the omelet in half and serve.', NULL);
