INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (226, 'Corned Beef Hash', 'Spend With Pennies', 'https://www.spendwithpennies.com/corned-beef-hash/', 22, 22, 0, 4, 4, 0, 4.0, 'serving', '1. Heat the oven to 375 degrees F. Boil the diced potatoes in salted water 11 to 14 minutes until fork tender, then drain. | 2. Melt 2 Tbsp butter in an ovenproof skillet over medium heat and cook the corned beef and onion about 5 minutes until the onion softens. | 3. Add the last 1 Tbsp butter, the potatoes and the green pepper and cook 5 to 7 minutes, stirring rarely, until the potatoes start to brown. | 4. Make four wells in the hash, crack an egg into each, and season with salt and pepper. | 5. Bake 12 to 15 minutes until the eggs are done the way you like them, remembering they keep cooking out of the oven. | 6. Garnish with parsley and serve right away. Leftover hash without the eggs keeps up to 4 days in the fridge or 3 months frozen.', NULL);
