INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (227, 'Easy Quiche', 'Spend With Pennies', 'https://www.spendwithpennies.com/easy-quiche-recipe/', 50, 25, 0, 6, 6, 0, 6.0, 'slice', '1. Heat the oven to 375 degrees F and press the pie crust into a 9-inch pie plate. | 2. Whisk the eggs, milk, salt and pepper in a large bowl. | 3. Scatter the ham, 1 cup of the cheese and the green onions over the crust, pour the egg mixture over, and sprinkle on the remaining 1/2 cup cheese. | 4. Bake 35 to 40 minutes until the center is completely set, then cool 5 to 10 minutes before slicing. Leftovers keep in the fridge and the quiche freezes up to 2 months.', NULL);
