INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (229, 'Air Fryer Egg Bites', 'Spend With Pennies', 'https://www.spendwithpennies.com/air-fryer-egg-bites/', 25, 25, 0, 3, 7, 1, 7.0, 'bite', '1. Heat the air fryer to 340 degrees F. | 2. Whisk the eggs, cream, milk, mustard powder, salt and pepper in a medium bowl until fluffy and pale yellow. | 3. Divide the crumbled bacon, cheese and green onions among the cups of your egg bite molds. | 4. Set the molds in the air fryer basket and pour the egg mixture over the top. | 5. Cook 11 to 13 minutes, stirring after 7 to 8 minutes, until just set, then rest 5 minutes. Leftovers keep up to 4 days in the fridge or 2 months frozen.', NULL);
