INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (230, 'Make Ahead Egg Muffins', 'Spend With Pennies', 'https://www.spendwithpennies.com/make-ahead-egg-muffins/', 32, 32, 0, 4, 12, 1, 12.0, 'muffin', '1. Heat the oven to 350 degrees F and whisk the eggs, salt and pepper until well combined. | 2. Grease a muffin pan well or line it with liners and divide the red pepper, onion, meat and cheeses among the 12 wells. | 3. Pour the egg mixture over the add-ins and bake 22 to 25 minutes until set. | 4. Rest 3 minutes, run a knife around the edges to release the muffins, and serve warm or cool completely and refrigerate up to 5 days or freeze up to 3 months.', NULL);
