INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (238, 'Hungry Man''s Baked Potatoes', 'Taste of Home', 'https://www.tasteofhome.com/recipes/hungry-man-s-baked-potatoes/', 30, 30, 0, 4, 4, 0, 4.0, 'potato', '1. Scrub and pierce the potatoes, set them on a microwave-safe plate, and microwave uncovered on high 12 to 15 minutes, turning once, until tender. | 2. Cook the bacon in a large skillet over medium heat until crisp, move it to paper towels, and keep 1 Tbsp of the drippings in the pan. | 3. Saute the corn and red onion in the drippings until soft. | 4. Cut an X in each potato and fluff the insides with a fork, and microwave the pork uncovered 1 to 2 minutes until hot. | 5. Top each potato with the pork, the corn and onion, the bacon, goat cheese and cilantro.', NULL);
