INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (239, 'Sausage Sweet Potato Sheet-Pan Dinner', 'Taste of Home', 'https://www.tasteofhome.com/recipes/sausage-sweet-potato-sheet-pan-dinner/', 60, 20, 1, 5, 5, 0, 5.0, 'serving', '1. Heat the oven to 425 degrees F, put the sweet potatoes and onion in a 15x10x1-inch baking pan, drizzle with the oil, add the brown sugar and seasonings, and toss to coat. Bake 15 minutes. | 2. Gently stir in the pears and lay the sausages on top, then bake 20 minutes more, stirring once. | 3. Raise the oven to 450 degrees F and bake 8 to 10 minutes more, turning the sausages once, until golden and at least 160 degrees F inside. Leftovers keep 3 to 4 days in the fridge.', NULL);
