INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (242, 'Sheet-Pan Pork Supper', 'Taste of Home', 'https://www.tasteofhome.com/recipes/sheet-pan-pork-supper/', 45, 25, 1, 8, 8, 0, 8.0, 'serving', '1. Heat the oven to 450 degrees F and stir the butter, chives and garlic together in a small bowl. | 2. Toss the green beans with 1 Tbsp oil, 1/4 tsp salt and 1/4 tsp pepper and spread them in a 15x10x1-inch pan, then toss the potatoes with the remaining oil, 1/2 tsp salt and 1/4 tsp pepper and add them to the pan. | 3. Pat the pork dry, brush it with the teriyaki glaze, and set it on top of the vegetables. | 4. Bake until the pork reads 145 degrees F, about 25 to 30 minutes, then move the pork to a board, spread 2 Tbsp of the seasoned butter over it, cover loosely with foil, and rest it. | 5. Stir the vegetables and bake about 10 minutes more until tender and lightly browned, then stir in the rest of the seasoned butter. | 6. Slice the pork and serve it with the vegetables and pan drippings, topped with sesame seeds and more chives if you like.', NULL);
