INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (243, 'Southwestern Casserole', 'Taste of Home', 'https://www.tasteofhome.com/recipes/southwestern-casserole/', 65, 40, 1, 6, 12, 0, 2.0, 'casserole', '1. Cook the macaroni per the package directions while you brown the beef and onion in a large saucepan over medium heat, crumbling the meat, then add the garlic for 1 minute and drain the fat. | 2. Stir in the tomatoes, beans, tomato paste, chiles, salt, chili powder, cumin and pepper, bring to a boil, and simmer uncovered 10 minutes, then stir in the drained macaroni. | 3. Heat the oven to 375 degrees F and divide the mixture between two greased 2-quart baking dishes, topping each with the cheese and sliced jalapenos. | 4. Cover and bake 30 minutes, then uncover and bake about 10 minutes more until bubbly. Serve one casserole and cool, cover and freeze the other for up to 3 months; leftovers keep up to 4 days in the fridge.', NULL);
