INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (244, 'Carolina-Style Vinegar BBQ Chicken', 'Taste of Home', 'https://www.tasteofhome.com/recipes/carolina-style-vinegar-bbq-chicken/', 250, 15, 1, 6, 6, 0, 6.0, 'serving', '1. Stir the water, vinegar, sugar, chicken base, red pepper flakes and salt together in a small bowl. | 2. Put the chicken in a 3-quart slow cooker, pour the vinegar mixture over it, cover, and cook on low 4 to 5 hours until tender. | 3. Lift out the chicken, cool it slightly, and keep 1 cup of the cooking juices, discarding the rest. | 4. Shred the chicken with two forks, return it and the reserved juices to the slow cooker, and heat through, serving on buns if you like.', NULL);
