INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (246, 'Fluffy Microwave Egg in a Cup', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/microwave-egg-bowl/', 7, 7, 0, 1, 1, 0, NULL, NULL, '1. Crack the eggs into a microwave-safe cup, add the milk, and beat with a fork, filling the cup no more than half full because the eggs rise. | 2. Microwave on high for 1 1/2 to 2 minutes, then stir. | 3. If the eggs are still very runny, cook another 30 to 45 seconds; if mostly set, take them out since they keep cooking briefly. | 4. Season with salt and pepper and serve right away.', NULL);
