INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (248, 'Chicken Bacon Ranch Sandwich', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/chicken-bacon-ranch-sandwich/', 15, 15, 1, 1, 1, 0, 1.0, 'sandwich', '1. Cook the bacon to your preferred doneness and set it aside. | 2. Spread about two-thirds of the cheese on one slice of bread, then layer the chicken over it and drizzle with about 1 tablespoon of ranch. | 3. Lay the bacon on the chicken and sprinkle the remaining cheese on top. | 4. Butter the outside of both slices of bread and close the sandwich. | 5. Cook in a skillet over medium-low heat about 5 minutes until golden brown, then flip and cook the other side until the cheese melts. | 6. Open the sandwich, add lettuce, tomato or onion if you like, then slice and serve.', NULL);
