INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (249, 'Baked Panko Chicken for One', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/panko-chicken/', 30, 30, 0, 1, 1, 0, NULL, NULL, '1. Preheat the oven to 425°F. | 2. Mix the mayonnaise and Dijon mustard in a shallow bowl. | 3. In a second shallow bowl, combine the panko, smoked paprika and garlic salt, crushing the panko lightly. | 4. Set a rack on a baking sheet and spray it with cooking spray. | 5. Pound the chicken breast to about 1 inch thick and pat it dry. | 6. Coat the chicken on all sides with the mayonnaise mixture, then press it into the panko mixture to coat both sides. | 7. Place the chicken on the rack, spray the top with cooking spray, and bake about 20 to 25 minutes until it reaches 165°F in the thickest part. | 8. Rest about 5 minutes before serving.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (249, 1, NULL, 'chicken breast', 1.0, 1.0, 'each', 'about 6 ounces', NULL, 0, '1 whole chicken breast about 6 ounces');
