INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (250, 'Creamy Mushroom Chicken and Rice for One', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/mushroom-chicken-and-rice/', 25, 25, 1, 1, 1, 0, NULL, NULL, '1. Melt the butter in a saucepan over medium-high heat and cook the mushrooms and thyme until golden brown on both sides; set the mushrooms aside. | 2. Add the rinsed rice, chicken tender, garlic, water, bouillon paste and milk to the pan and bring to a boil. | 3. Reduce to a simmer and cook about 15 minutes, adding a splash more water if needed, until the rice is tender. | 4. Turn off the heat and stir in the cream cheese, then fold the mushrooms back in. | 5. Top with grated Parmesan and serve.', NULL);
