INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (251, 'One Pot Chicken Parmesan Pasta for One', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/chicken-parmesan-pasta/', 20, 20, 0, 1, 1, 0, NULL, NULL, '1. Heat a large sauté pan over medium-low heat, add 1/4 teaspoon olive oil and the bread crumbs, and cook 1 to 3 minutes until golden; remove and set aside. | 2. Raise the heat to medium-high and add the chicken, pasta, diced tomatoes, vegetables, water, bouillon paste, Italian seasoning, garlic and salt. | 3. Stir and cook, adding more water if needed, until the pasta is almost al dente and most of the liquid is absorbed. | 4. Sprinkle the mozzarella over the pasta and cook until melted. | 5. Transfer to a bowl and top with Parmesan, the toasted bread crumbs and parsley.', NULL);
