INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (252, 'Buffalo Chicken Flatbread', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/buffalo-chicken-flatbread/', 15, 15, 0, 1, 1, 1, NULL, NULL, '1. Preheat the oven to 475°F. | 2. If using the onion, cook it in the olive oil in a small saucepan over medium-low heat 5 to 10 minutes until soft and translucent. | 3. Place the flatbread on a baking sheet and spread the ranch dressing over it. | 4. Toss the chopped chicken with the hot sauce and spread it over the flatbread. | 5. Add the sliced vegetables and onions, then top with the mozzarella and cheddar. | 6. Bake 7 to 10 minutes, watching closely, until the cheese is browned and bubbly. | 7. Slice and serve with extra dressing or hot sauce if you like.', NULL);
