INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (253, 'Protein Mac and Cheese for One', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/protein-mac-and-cheese/', 20, 20, 0, 1, 1, 0, NULL, NULL, '1. Bring a medium pot of water and the salt to a boil and cook the macaroni according to package directions. | 2. While the pasta cooks, blend the tofu, milk and garlic salt until smooth. | 3. Drain the pasta when al dente and return it to the pot. | 4. Pour the tofu mixture over the pasta, add the butter and cheese, and stir until the cheese melts and the pasta is coated. Serve right away.', NULL);
