INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (254, 'Sticky Tofu for One', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/sticky-tofu/', 50, 20, 1, 1, 1, 0, NULL, NULL, '1. Drain the tofu, wrap it in a towel, and press under a heavy skillet 30 to 60 minutes. | 2. Heat a skillet over medium to medium-high heat and cook rice or noodles if using. | 3. Cut the pressed tofu into bite-size pieces. | 4. Shake the tofu in a covered container with the cornstarch, salt and pepper until coated. | 5. Add the oil to the hot pan and cook the tofu in a single layer 3 to 5 minutes per side until crisp; cook any vegetables alongside. | 6. Whisk the water, soy sauce, brown sugar, tomato paste, garlic and sesame oil in a small bowl. | 7. Turn off the heat, pour the sauce over the tofu and toss until it thickens and coats the tofu. | 8. Spoon over rice or noodles and top with sesame seeds if you like.', NULL);
