INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (259, 'Chicken Bacon and Mushroom Pasta for One', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/chicken-bacon-mushroom-pasta/', 20, 20, 0, 1, 1, 0, NULL, NULL, '1. Slice the mushrooms into 1/4-inch pieces and roughly chop the onion. | 2. Spray a large frying pan and heat over medium-high. Put the bacon and chicken tender on one side and the oil, mushrooms and onion on the other, then sprinkle the mushrooms with Italian seasoning and salt. | 3. Cook 5 to 8 minutes until the bacon is crisp and the mushrooms have shrunk and browned at the edges; remove everything from the pan. | 4. Add the water, spaghetti, bouillon paste and garlic and cook 5 to 8 minutes until al dente, adding water if needed. | 5. Chop the chicken and bacon. When most of the water has cooked off, lower the heat, whisk the flour into the milk and pour it in, then stir in the butter and Parmesan. | 6. Return the chicken, bacon and mushrooms to the pan, toss until coated, and season to taste. Top with parsley and red pepper flakes if you like.', NULL);
