INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (260, 'Refried Bean Tacos for One', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/the-easiest-black-bean-tacos/', 10, 10, 0, 1, 1, 0, NULL, NULL, '1. Mix the refried beans with the taco seasoning in a microwave-safe bowl. | 2. Top with the shredded cheddar and microwave in 30-second bursts until the cheese melts. | 3. Divide the bean mixture among the tortillas. | 4. Top with salsa, sliced cabbage and cilantro, and serve with lime wedges.', NULL);
