INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (261, 'Egg and Vegetable Chapati Roll', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/chapati-roll/', 15, 15, 0, 1, 1, 0, 1.0, 'roll', '1. Heat the oil in a small non-stick pan over medium heat and cook the garlic, vegetables and 1/4 teaspoon salt 4 to 5 minutes until soft; set aside. | 2. Whisk the eggs, milk and remaining salt in a small bowl. | 3. Cook the uncooked tortilla in the pan 1 to 2 minutes until the first side turns opaque, flip, and cook about 2 minutes more, poking any air bubbles. Move it to a plate. | 4. Pour in the egg mixture and stir in small circles about 3 minutes until mostly set, then press it flat. | 5. Spread the vegetables over the eggs, sprinkle on the cheese and cook until it melts. | 6. Slide the eggs onto the tortilla, roll it up and eat right away.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (261, 1, NULL, 'vegetable oil', 1.0, 1.0, 'tsp', NULL, NULL, 0, '1 teaspoon mild oil I used grapeseed');
