INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (263, 'Chili without Tomatoes for One', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/chili-without-tomatoes/', 30, 30, 0, 1, 1, 0, NULL, NULL, '1. Heat a large skillet over medium heat and add the ground beef, bell pepper, onion, chili powder, oregano and cumin. | 2. Stir and break up the meat for 5 to 7 minutes until the vegetables soften and the beef is cooked through. | 3. Add the drained kidney beans and garlic and cook about 1 minute until fragrant. | 4. Pour in the beef broth, stir, and simmer about 15 minutes until most of the liquid has cooked off and the chili is as thick as you like. | 5. Serve with sour cream, cheddar and green onion if you like.', NULL);
