INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (264, 'One Pan Panko Pork Chop Dinner for One', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/pan-seared-pork-chops/', 20, 20, 0, 1, 1, 0, NULL, NULL, '1. Heat a cast iron skillet over medium heat and add the oil. | 2. Whisk the egg in a shallow bowl and mix the panko and Italian seasoning in another. Dip the pork chop in the egg, then press it into the panko on both sides, saving the leftover panko. | 3. Place the pork chop in the hot skillet, add the cubed potato, and cook 6 minutes, stirring the potato occasionally. | 4. Flip the pork chop, add the green beans and leftover panko, and cook about 6 minutes more until the pork reaches 145°F. | 5. Plate the pork and vegetables, top with lemon juice, Parmesan, salt and pepper, and rest the pork 5 minutes before cutting.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (264, 1, 'protein', 'pork chop', 1.0, 1.0, 'each', NULL, NULL, 0, '1 pork chop, ½ to 1 inch thick, patted dry');
