INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (265, 'Cheesy White Bean Tomato Bake for One', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/cheesy-white-bean-tomato-bake/', 18, 18, 0, 1, 1, 0, NULL, NULL, '1. Preheat the oven to 425°F. | 2. In a small oven-safe skillet over medium-low heat, cook the olive oil, garlic and Italian seasoning until the garlic is golden, then turn off the heat. | 3. Stir in the tomato paste and diced tomatoes, mashing if you want a smoother sauce. | 4. Add the spinach, drained beans and 1 tablespoon water, season with salt, pepper and red pepper flakes, and stir. | 5. Sprinkle the mozzarella on top and bake 5 to 8 minutes until the cheese melts and the sauce bubbles; broil 1 to 2 minutes for a browned top. | 6. Serve with crusty bread.', NULL);
