INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (266, 'Chicken Bacon Ranch Flatbread for One', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/chicken-bacon-ranch-flatbread/', 25, 25, 0, 1, 2, 0, NULL, NULL, '1. Preheat the oven to 400°F and place the flatbread on a baking sheet. | 2. Spoon the ranch over the flatbread, leaving about 1/2 inch bare at the edge. | 3. Sprinkle the mozzarella over the ranch, then add the chicken and bacon. | 4. Bake 8 to 10 minutes until the cheese bubbles and the crust is browned. | 5. Top with sliced green onion, slice and serve.', NULL);
