INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (269, 'Vegetarian Crunchwrap', 'Healthyish Appetite', 'https://healthyishappetite.com/vegetarian-crunchwrap/', 20, 20, 0, 1, 2, 1, 1.0, 'crunchwrap', '1. Mix the refried beans and taco seasoning in a bowl. | 2. Spread the beans over the center of one tortilla, leaving about 2 inches bare around the edge. | 3. Layer the tortilla chips over the beans, then add the avocado, lettuce, cabbage, tomatoes and cheese. | 4. Cut a smaller circle from the center of the second tortilla and set it on top of the filling. | 5. Fold the outer edges of the bottom tortilla up and over to enclose the filling. | 6. Grease a skillet with butter over medium heat and cook the crunchwrap seam-side down until browned and crisp, then flip and brown the other side. | 7. Rest 1 to 2 minutes and slice in half. | 8. Stir the sour cream, lime juice and a pinch of salt together, drizzle over the crunchwrap and serve.', NULL);
