INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (270, 'Mongolian Beef for One', 'One Dish Kitchen', 'https://onedishkitchen.com/mongolian-beef-recipe/', 20, 20, 0, 1, 1, 0, NULL, NULL, '1. Toss the steak strips with the cornstarch until coated. | 2. Whisk the soy sauce, brown sugar and water in a small bowl. | 3. Heat the oil in a 10-inch skillet over medium-high heat and brown the steak 1 to 2 minutes per side. Move it to a plate and cover. | 4. Stir the garlic and ginger in the pan for about 30 seconds. | 5. Pour in the sauce and stir until it boils. | 6. Return the steak and stir 2 to 3 minutes until the sauce thickens. | 7. Stir in the green onions for about 20 seconds and serve over rice if you like.', NULL);
