INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (271, 'Honey Garlic Chicken', 'Budget Bytes', 'https://www.budgetbytes.com/honey-garlic-chicken/', 28, 28, 0, 4, 4, 0, NULL, NULL, '1. Whisk the honey, soy sauce, rice vinegar, sriracha, sesame oil and cornstarch in a small bowl and set aside. | 2. Cut the chicken into 1/2-inch pieces, season with salt, pepper and garlic powder, and toss with the flour. | 3. Heat a large skillet over medium-high heat with 2 tablespoons oil and brown the chicken in two batches, adding the last tablespoon of oil before the second batch. Set all the chicken aside. | 4. Lower the heat to medium-low, add the butter and garlic to the skillet and cook 30 to 60 seconds until fragrant. | 5. Stir the sauce, pour it into the skillet, scrape up the browned bits, and simmer about 2 minutes until thickened. | 6. Return the chicken, toss to coat, and cook 1 to 2 minutes more. | 7. Top with green onions and serve with rice.', NULL);
