INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (272, 'Chicken Stir Fry', 'Budget Bytes', 'https://www.budgetbytes.com/chicken-stir-fry/', 35, 35, 0, 6, 6, 0, NULL, NULL, '1. Whisk the sauce ingredients in a small bowl and set aside. | 2. Cut the broccoli into small florets, slice the bell pepper, onion and carrots into similar-sized pieces, and slice the green onions. | 3. Cut the chicken into 1/2-inch pieces. | 4. Heat a very large skillet or wok over medium-high heat with 2 tablespoons oil and brown the chicken on all sides without overcooking. Move it to a plate. | 5. Add the remaining tablespoon of oil, then the carrots and broccoli, and stir-cook about 1 minute until the broccoli turns bright green. | 6. Add the bell pepper and onion and cook 1 to 2 minutes more. | 7. Return the chicken, stir the sauce and pour it over everything. Simmer until glossy and thick, 1 to 2 minutes more, then top with green onions.', NULL);
