INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (273, 'Swamp Soup', 'Budget Bytes', 'https://www.budgetbytes.com/swamp-soup/', 30, 30, 0, 8, 8, 0, NULL, NULL, '1. Cook the garlic, onion, carrots and celery in the olive oil in a large soup pot over medium heat about 5 minutes until the onion softens. | 2. Stir in the tomato sauce, diced tomatoes with their juices, vegetable broth, basil and oregano and bring to a simmer. | 3. Add the frozen spinach without thawing and stir until it melts and the soup is hot. | 4. Taste and add salt if needed. | 5. Put a small handful of cubed Swiss cheese in each bowl and ladle the hot soup over it.', NULL);
