INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (274, 'Easy Pesto Chicken and Vegetables', 'Budget Bytes', 'https://www.budgetbytes.com/easy-pesto-chicken-and-vegetables/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Chop the bell pepper, yellow squash and zucchini and slice the red onion into similar-sized pieces. | 2. Cut the chicken into 1/2-inch cubes. | 3. Heat the oil in a large skillet over medium-high until very hot, add the chicken and cook until opaque, 3 to 5 minutes. | 4. Add the green beans and sauté 1 to 2 minutes until thawed. | 5. Add the bell pepper and onion and sauté 1 to 2 minutes, raising the heat if water pools. | 6. Add the squash and zucchini and sauté 2 to 3 minutes until just starting to soften. | 7. Turn off the heat, stir in the pesto and adjust the salt, pepper or pesto to taste. | 8. Sprinkle with Parmesan just before serving.', NULL);
