INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (275, 'Chicken Sausage White Bean Skillet', 'Budget Bytes', 'https://www.budgetbytes.com/chicken-sausage-white-bean-skillet/', 25, 25, 0, 4, 4, 0, NULL, NULL, '1. Slice the sausage into 1/4- to 1/2-inch rounds. | 2. Brown the sausage in 1 tablespoon oil in a large skillet over medium heat, 1 to 2 minutes per side, and move it to a plate. | 3. Add the remaining oil, onion and garlic and cook about 3 minutes until the onion is translucent. | 4. Add the undrained-rinsed beans (drained only), salt, oregano, smoked paprika and pepper, then pour in the broth. | 5. Simmer 4 to 5 minutes. | 6. Stir in the spinach until wilted, return the sausage and serve hot.', NULL);
