INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (276, 'BBQ Beans and Greens', 'Budget Bytes', 'https://www.budgetbytes.com/bbq-beans-and-greens/', 35, 35, 0, 6, 6, 0, NULL, NULL, '1. Start cooking the rice (1 cup dry makes about 3 cups cooked). | 2. Cook the olive oil, onion, pepper and salt in a large sauté pan over medium-high heat about 5 minutes until the onion is soft. | 3. Add the canned tomatoes with juice, drained pinto beans and frozen corn and cook 5 minutes. | 4. Add the greens, BBQ sauce and vegetable broth, cover, and simmer on medium-low 20 minutes until the greens are tender. | 5. Taste, adjust the seasoning, and serve over the rice.', NULL);
