INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (277, 'Easy Sesame Chicken', 'Budget Bytes', 'https://www.budgetbytes.com/easy-sesame-chicken/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Combine the sauce ingredients in a small bowl and set aside. | 2. Whisk the egg, 2 tablespoons cornstarch, salt and pepper in a large bowl, trim the thighs, cut them into 1-inch pieces and toss them in the mixture. | 3. Heat the oil in a large skillet over medium until very hot, then spread the chicken in a single layer. | 4. Cook undisturbed until the bottom is golden, flip, breaking the pieces into clumps, and cook until golden and cooked through. | 5. Pour in the sauce and gently stir until it simmers and thickens, then turn off the heat. | 6. Serve over rice topped with green onions.', NULL);
