INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (278, 'Easy Orange Chicken', 'Budget Bytes', 'https://www.budgetbytes.com/easy-orange-chicken/', 25, 25, 0, 4, 4, 0, NULL, NULL, '1. Zest the orange and squeeze out its juice, then whisk the juice and zest with the soy sauce, brown sugar, vinegar, ginger, garlic, red pepper flakes and 1/2 tablespoon cornstarch until dissolved. | 2. Trim the thighs and cut them into 3/4-inch pieces. | 3. Whisk the egg, 2 tablespoons cornstarch, salt and pepper until frothy and toss the chicken in it. | 4. Heat the oil in a large skillet over medium to medium-high, add the chicken in a single layer and cook until golden on the bottom. | 5. Flip, separating the pieces, and cook until golden and cooked through, about 5 to 7 minutes total. Move the chicken to a plate. | 6. Lower the heat, add the sauce to the skillet and simmer 2 to 3 minutes until glossy. | 7. Return the chicken, coat it in the sauce, heat 1 minute, and serve over rice with green onions.', NULL);
