INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (279, 'Quick BBQ Chicken', 'Budget Bytes', 'https://www.budgetbytes.com/quick-bbq-chicken/', 25, 25, 0, 4, 4, 0, NULL, NULL, '1. If using breasts, pound the thicker areas to an even 1/2 to 3/4 inch under plastic wrap. | 2. Mix the smoked paprika, garlic powder, salt and pepper and season both sides of the chicken. | 3. Heat the oil in a large skillet over medium heat and cook the chicken 5 to 7 minutes per side until well browned and 165°F inside. | 4. Turn off the heat, brush both sides with BBQ sauce, and rest about 5 minutes before slicing.', NULL);
