INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (280, 'Easy Lemon Pepper Chicken', 'Budget Bytes', 'https://www.budgetbytes.com/easy-lemon-pepper-chicken/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Slice each chicken breast horizontally into two thinner pieces. | 2. Mix the flour and lemon pepper seasoning and press it onto both sides of the chicken. | 3. Heat the oil in a large skillet over medium until very hot and brown the chicken about 5 minutes per side. Move it to a plate and cover. | 4. Add the butter and garlic to the skillet and sauté about 1 minute. | 5. Pour in the chicken broth, scrape up the browned bits, stir in the lemon juice and simmer 3 to 5 minutes until slightly reduced. | 6. Return the chicken, spoon the sauce over it and heat through. Finish with cracked pepper and parsley.', NULL);
