INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (281, 'Kung Pao Chicken', 'Budget Bytes', 'https://www.budgetbytes.com/kung-pao-chicken/', 60, 30, 0, 6, 6, 0, NULL, NULL, '1. Dissolve 1 tablespoon cornstarch in 1 tablespoon water, then stir in 1 tablespoon oil, 1 tablespoon soy sauce, 1 tablespoon rice wine and the garlic. | 2. Cut the chicken into small pieces, stir it into the marinade, cover and refrigerate at least 30 minutes. | 3. Dissolve the remaining cornstarch in the remaining water and stir in 2 tablespoons each of soy sauce, rice wine, chili sauce and brown sugar plus the sesame oil until the sugar dissolves. | 4. Dice the bell pepper, cut the carrots into thin matchsticks, slice the green onions and measure the peanuts. | 5. Cook the rice: boil with the lid on, reduce to the lowest heat and simmer 20 minutes, then rest covered. | 6. Heat 2 tablespoons oil in a large skillet over medium-high heat and stir-fry the white parts of the green onions 30 to 60 seconds. | 7. Add the marinated chicken and cook about 5 minutes until cooked through. | 8. Stir in the vegetables and peanuts, add the sauce, and cook 2 to 3 minutes until thickened. | 9. Serve over the rice.', NULL);
