INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (282, 'Easy Firecracker Chicken', 'Budget Bytes', 'https://www.budgetbytes.com/firecracker-chicken/', 25, 25, 1, 4, 4, 1, NULL, NULL, '1. Put the chicken, cornstarch, garlic powder, salt and pepper in a sealed bag and shake until every piece is coated. | 2. Heat 2 tablespoons oil in a medium skillet over medium-high heat and cook the chicken in batches, 3 to 4 minutes per side, until golden. Set the first batch aside, add the remaining oil, and cook the rest. | 3. In the same skillet, stir the buffalo sauce, brown sugar, vinegar and red pepper flakes about 2 minutes until the sugar dissolves and the sauce thickens. | 4. Return the chicken to the skillet and toss to coat and heat through.', NULL);
