INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (283, 'Glazed Pork Chops', 'Budget Bytes', 'https://www.budgetbytes.com/glazed-pork-chops/', 25, 25, 0, 4, 4, 0, NULL, NULL, '1. Preheat the oven to 350°F and mix the brown sugar, cayenne, garlic powder, paprika, salt and black pepper in a small bowl. | 2. Rub the seasoning mixture over all sides of the pork chops. | 3. Heat the olive oil in a large oven-safe skillet over medium heat until it shimmers, then cook the chops about 5 minutes per side until browned. | 4. If the chops are thicker than 1 inch, finish them in the oven 5 to 10 minutes until they reach 145°F. | 5. Spoon the glaze from the bottom of the pan over the chops before serving.', NULL);
