INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (284, 'Sweet and Sour Pork Chops with Vegetables', 'Budget Bytes', 'https://www.budgetbytes.com/sweet-and-sour-pork-chops-with-vegetables/', 25, 25, 0, 4, 4, 0, NULL, NULL, '1. Whisk the brown sugar, rice vinegar, ketchup, water, soy sauce and cornstarch in a bowl until dissolved. | 2. Season both sides of the pork chops with salt and pepper. | 3. Heat the oil in a large skillet over medium heat and sear the chops about 5 minutes per side. Move them to a plate and cover. | 4. Add the frozen vegetables and stir about 2 minutes until the ice begins to melt. | 5. Stir the sauce, add it to the skillet, and keep stirring until it simmers and turns glossy. | 6. Return the chops and simmer 2 to 3 minutes until they reach 145°F. Serve over rice or noodles.', NULL);
