INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (285, 'Spanish Chickpeas and Rice', 'Budget Bytes', 'https://www.budgetbytes.com/spanish-chickpeas-and-rice/', 50, 25, 0, 4, 4, 0, NULL, NULL, '1. Sauté the garlic in the olive oil in a large deep skillet over medium-low heat 1 to 2 minutes. | 2. Add the smoked paprika, cumin, oregano, cayenne and black pepper and toast about 1 minute. | 3. Add the onion and cook about 5 minutes until soft. | 4. Stir in the rice and toast about 2 minutes. | 5. Add the chickpeas, artichoke hearts, tomatoes with juices, broth, salt and most of the parsley and stir. | 6. Cover, bring to a boil on medium-high, then reduce to low and simmer 20 minutes. | 7. Turn off the heat and rest covered 5 minutes, then fluff and top with the remaining parsley. Serve with lemon wedges.', NULL);
