INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (286, 'Southwest Chicken Skillet', 'Budget Bytes', 'https://www.budgetbytes.com/southwest-chicken-skillet/', 25, 25, 0, 4, 6, 0, NULL, NULL, '1. Combine the rice, salsa, chicken, drained beans, chili powder and broth in a large heavy skillet and stir until the rice is spread evenly. | 2. Cover tightly, bring to a full boil on high, then reduce to low and simmer 15 minutes. | 3. Turn off the heat and rest covered 5 minutes, then uncover and fluff with a fork. | 4. Sprinkle on the cheese, cover and let the steam melt it. | 5. Scatter the sliced green onions on top and serve hot.', NULL);
