INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (287, 'One Pot Creamy Pesto Chicken Pasta', 'Budget Bytes', 'https://www.budgetbytes.com/one-pot-creamy-pesto-chicken-pasta/', 25, 25, 0, 4, 4, 0, NULL, NULL, '1. Melt the butter in a deep skillet over medium heat and brown the chicken lightly. | 2. Add the garlic and sauté about 1 more minute. | 3. Add the penne and chicken broth, stirring up the browned bits. Cover, raise to medium-high and bring to a full boil. | 4. Stir once, re-cover, lower to medium-low and simmer about 8 minutes, stirring every couple of minutes, until the pasta is tender and most of the broth is absorbed. | 5. Add the milk, cream cheese and pesto and stir until the cream cheese melts, then stir in the Parmesan. | 6. Season with black pepper and crushed red pepper and serve.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (287, 1, NULL, 'chicken breast', 1.0, 1.0, 'lb', 'boneless, skinless, cut into 1-inch pieces', 'chicken thigh', 0, '1 lb (450 g) boneless, skinless chicken breast, cut into 1-inch pieces (boneless thighs also work)');
