INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (289, 'Pasta Primavera', 'Budget Bytes', 'https://www.budgetbytes.com/pasta-primavera/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Cut the vegetables into even pieces: half-moons for the zucchini and squash, thin rounds for the carrot, strips for the onion, halves for the tomatoes. | 2. Cook the penne in salted water until al dente, reserve about 1/2 cup of the pasta water, and drain. | 3. Warm the olive oil in a large deep skillet over medium heat and sauté the carrot and onion about 2 minutes, then add the zucchini and squash and sauté about 2 more minutes. | 4. Add the garlic, tomatoes and peas, season with salt, pepper and oregano, and sauté 1 to 2 minutes. Turn off the heat. | 5. Stir in the butter and lemon juice. | 6. Add the pasta, Parmesan and a splash of pasta water and toss until the sauce lightly coats the pasta.', NULL);
