INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (290, 'Cold Peanut Noodle Salad', 'Budget Bytes', 'https://www.budgetbytes.com/cold-peanut-noodle-salad/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Blend or whisk the peanut butter, brown sugar, garlic, ginger, lime juice, soy sauce and oil until smooth for the dressing. | 2. Boil the spaghetti, broken in half, until tender, then drain, rinse briefly with cold water and drain well. | 3. Finely shred the cabbage, grate the carrots, chop the cilantro and peanuts, and slice the green onions. | 4. Toss the cooled pasta with the cabbage, carrots, cilantro, green onions and peanuts. | 5. Serve with the dressing, or divide the undressed salad and the dressing into four containers each for meal prep.', NULL);
