INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (291, 'Easy Vegetable Beef Soup', 'Budget Bytes', 'https://www.budgetbytes.com/easy-vegetable-beef-soup/', 50, 35, 0, 6, 6, 0, NULL, NULL, '1. Sauté the onion and garlic in the olive oil over medium heat until soft and translucent. | 2. Add the ground beef and cook until no longer pink, draining excess fat if you like. | 3. Peel and dice the potato into 1/2-inch cubes. | 4. Add the potato, tomatoes with juices, Italian seasoning, pepper, broth and Worcestershire sauce to the pot and stir. | 5. Bring to a boil on medium-high, then lower to medium-low and simmer about 10 minutes until the potato is fork-tender. | 6. Stir in the frozen vegetables, bring back to a simmer and cook about 5 more minutes. | 7. Taste and add salt as needed.', NULL);
