INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (293, 'Beef and Cabbage Soup', 'Budget Bytes', 'https://www.budgetbytes.com/beef-and-cabbage-soup/', 60, 25, 0, 6, 6, 0, NULL, NULL, '1. Sauté the onion and garlic in the olive oil in a large pot over medium heat about 5 minutes until soft, then add the ground beef and cook until browned, draining fat if needed. | 2. Stir in the cabbage, stewed tomatoes with juices, oregano, basil, pepper, beef broth and Worcestershire sauce. | 3. Cover, bring to a boil on high, then reduce to low and simmer about 30 minutes until the cabbage is very tender. | 4. Break up large tomato pieces, taste and add salt if needed. | 5. Stir in about 1 tablespoon lemon juice and the parsley and serve.', NULL);
