INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (294, 'Chunky Split Pea Soup', 'Budget Bytes', 'https://www.budgetbytes.com/chunky-split-pea-soup/', 100, 30, 0, 6, 6, 0, NULL, NULL, '1. Heat the olive oil in a large pot over medium-high heat and sauté the onion, celery and carrots about 4 minutes, then add the garlic for 30 seconds. | 2. Add the split peas, ham hock, bay leaf and chicken broth and stir gently. | 3. Cover, bring to a gentle boil, then reduce to medium-low and simmer 1 hour, stirring occasionally and turning the ham hock. | 4. Check the peas; they should be mushy. Simmer 10 minutes more if they still hold their shape. | 5. Remove the ham hock to cool, add the diced potato to the pot and simmer about 12 minutes until tender. | 6. Pull the meat from the ham hock, shred it and return it to the pot. | 7. Season with salt and pepper to taste.', NULL);
