INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (296, 'Chicken Taco Soup', 'Budget Bytes', 'https://www.budgetbytes.com/chicken-taco-soup/', 60, 25, 0, 10, 10, 0, NULL, NULL, '1. Dice the onion and bell pepper, chop the cilantro, and halve the lime; juice one half and slice the other for serving. | 2. Coat the chicken breasts on all sides with the taco seasoning. | 3. Heat the olive oil in a large pot over medium-high heat and cook the onion and pepper about 5 minutes until softened but firm. | 4. Move the vegetables aside and sear the chicken about 5 minutes per side. | 5. Add the broth and tomatoes with juices, scrape up the browned bits, bring to a boil, then simmer on medium 30 minutes. | 6. Stir in the black beans, pinto beans and corn and keep simmering until the chicken reaches 165°F. | 7. Remove and shred the chicken with two forks. | 8. Whisk the cream cheese into the soup until melted and smooth. | 9. Stir in the lime juice, cilantro and shredded chicken and serve with toppings.', NULL);
