INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (297, 'Ham and Lentil Soup', 'Budget Bytes', 'https://www.budgetbytes.com/ham-and-lentil-soup/', 50, 30, 0, 6, 6, 0, NULL, NULL, '1. Heat the oil in a large pot over medium heat and cook the onion, celery, carrot and garlic about 5 minutes until slightly softened. | 2. Add the lentils, broth, water, salt, pepper, paprika and thyme and stir. | 3. Bring to a medium simmer, stir in the ham, and once it returns to a simmer cook 30 minutes. | 4. Check that the lentils are tender with a slight bite, cook a few minutes longer if needed, then serve.', NULL);
