INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (298, 'Greek Chicken Soup (Avgolemono)', 'Budget Bytes', 'https://www.budgetbytes.com/greek-chicken-soup/', 50, 35, 0, 6, 6, 0, NULL, NULL, '1. Dice the onion and celery, slice the carrots and mince the garlic. | 2. Heat the olive oil in a large pot over medium heat and cook the vegetables 5 to 7 minutes until soft. | 3. Add the chicken, broth, rice, dill, salt and pepper, bring to a boil, then cover and simmer on low 20 to 25 minutes until the chicken reaches 165°F and the rice is tender. | 4. Shred the chicken on a cutting board. | 5. Whisk the eggs and lemon juice until smooth, then temper them by slowly whisking in 2 cups of hot broth. | 6. Lower the heat, return the chicken to the pot with the parsley, and slowly pour in the egg mixture while stirring. Cook 2 to 3 minutes without boiling. | 7. Rest a few minutes, adjust the seasoning, and serve.', NULL);
