INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (299, 'Coconut Turmeric Chicken Soup', 'Budget Bytes', 'https://www.budgetbytes.com/coconut-turmeric-chicken-soup/', 50, 25, 0, 6, 6, 0, NULL, NULL, '1. Dice the onion, mince the garlic and grate the ginger, then cook them in the olive oil in a large pot over medium heat until the onion is soft. | 2. Peel and chop the carrots and chop the celery. | 3. Stir in the turmeric, cumin and crushed red pepper and cook about 1 more minute, then add the carrots and celery and cook a few minutes until they begin to soften. | 4. Add the chicken breast and broth, cover, bring to a boil, then simmer on medium-low 30 minutes. | 5. Remove the chicken, shred it and return it to the pot. Stir in the coconut milk and heat through, adding salt to taste. | 6. Serve over rice with cilantro and a lime wedge if you like.', NULL);
