INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (300, 'Paprika Chicken for One', 'One Dish Kitchen', 'https://onedishkitchen.com/paprika-chicken-recipe/', 25, 25, 0, 1, 1, 0, NULL, NULL, '1. Boil the rotini in salted water 5 to 7 minutes until tender, then drain and set aside. | 2. Toss the chicken strips with half the smoked paprika, the salt and the pepper. | 3. Melt half the butter in a 10-inch skillet over medium heat and cook the chicken about 3 minutes per side until browned and cooked through. Move it to a plate and cover. | 4. Melt the remaining butter in the skillet and cook the onion about 2 minutes, then add the garlic for 30 seconds and the remaining paprika for 10 seconds. | 5. Pour in the tomatoes with their juice and cook 1 minute, then add the broth and simmer 5 to 7 minutes, stirring often, until slightly thickened. | 6. Stir in the heavy cream and simmer about 2 minutes. | 7. Return the chicken to the skillet, warm through, and spoon it over the pasta. Top with the Parmesan.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (300, 1, NULL, 'pasta', 2.0, 2.0, 'oz', 'rotini, dry', NULL, 0, '2 oz dry rotini (about ½ cup dry, or 1 cup cooked)');
