INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (300, 3, NULL, 'smoked paprika', 1.0, 1.0, 'tsp', NULL, NULL, 0, '1 tsp smoked paprika, split in two');
