INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (301, 'Sheet Pan Chicken and Vegetables for One', 'One Dish Kitchen', 'https://onedishkitchen.com/easy-single-serving-sheet-pan-chicken-recipe/', 30, 10, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 400°F. | 2. Place the chicken on one side of a quarter sheet pan and spread the sweet potato and tomatoes on the other side. | 3. Drizzle everything with the olive oil and season with the salt, pepper and Italian seasoning. | 4. Toss the vegetables to coat and rub the oil and seasoning over both sides of the chicken. | 5. Bake 20 to 25 minutes until the chicken is cooked through and the vegetables are tender.', NULL);
