INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (302, 'Tuscan Chicken for One', 'One Dish Kitchen', 'https://onedishkitchen.com/tuscan-chicken-recipe/', 30, 30, 0, 1, 1, 0, NULL, NULL, '1. Mix the flour with salt and pepper and coat the chicken strips in it. | 2. Heat the olive oil in a 10-inch skillet over medium heat and cook the chicken 3 minutes undisturbed, flip, and cook 3 minutes more. Move it to a plate. | 3. Cook the onion about 2 minutes until soft, then stir in the garlic and red pepper flakes for 30 seconds. | 4. Pour in the broth and scrape up the browned bits. | 5. Stir in the cream, sun-dried tomatoes, tomato paste and Italian seasoning, bring to a boil, then simmer 3 to 5 minutes until the sauce reduces by half. | 6. Stir in the Parmesan and spinach until wilted, return the chicken and heat through. | 7. Serve in a bowl topped with torn basil.', NULL);
