INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (303, 'Pasta al Limone for One', 'One Dish Kitchen', 'https://onedishkitchen.com/lemon-pasta-recipe/', 15, 15, 0, 1, 1, 0, NULL, NULL, '1. Boil the spaghetti in salted water about 8 minutes until al dente, setting aside 1/4 cup of the pasta water before draining. | 2. Melt the butter in a 10-inch skillet over medium heat, add the lemon zest and garlic and cook 1 minute, then stir in the lemon juice. | 3. Add the spaghetti, 2 tablespoons of the pasta water and 2 tablespoons of the Parmesan and toss until the sauce thickens. | 4. Off the heat, add a pinch of salt if needed and more pasta water if dry. Top with the remaining Parmesan.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (303, 1, NULL, 'spaghetti', 2.0, 2.0, 'oz', NULL, NULL, 0, '2 ounces dry spaghetti');
