INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (305, 'Baked Ziti for One', 'One Dish Kitchen', 'https://onedishkitchen.com/baked-ziti-recipe/', 50, 35, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 350°F and boil the ziti until just short of al dente; drain. | 2. Cook the oil, onions, garlic, ground beef, 1/4 teaspoon salt and red pepper flakes in a skillet over medium heat about 8 minutes, breaking up the meat. | 3. Stir in 1 cup marinara and simmer 1 minute, then fold in the pasta. | 4. Mix the ricotta, 2 tablespoons mozzarella, 2 tablespoons Parmesan and the remaining salt and fold gently into the beef and pasta. | 5. Grease a 5x5-inch baking dish and spread 2 tablespoons marinara on the bottom. Add half the pasta mixture, 2 tablespoons mozzarella, the rest of the pasta, then the remaining mozzarella and Parmesan. | 6. Cover and bake 20 minutes, then cool slightly.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (305, 1, NULL, 'pasta', 2.0, 2.0, 'oz', 'ziti or penne', NULL, 0, '2 ounces dried ziti or penne pasta');
