INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (307, 'Fettuccine Alfredo for One', 'One Dish Kitchen', 'https://onedishkitchen.com/fettuccine-alfredo-recipe/', 15, 15, 0, 1, 1, 0, NULL, NULL, '1. Boil the fettuccine 7 to 8 minutes until al dente, drain, and toss with a little butter or oil. | 2. Combine the cream and lemon juice in a saucepan over medium heat, add the butter and stir until melted. | 3. Lower the heat to medium-low and stir constantly about 3 minutes until the sauce starts to thicken. | 4. Stir in the Parmesan and keep stirring 5 to 8 minutes until creamy, simmering until reduced by about a third. | 5. Add the fettuccine, toss to coat and serve right away.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (307, 1, 'pasta', 'fettuccine', 2.0, 2.0, 'oz', NULL, NULL, 0, '2 ounces uncooked fettuccine = 1 cup cooked');
