INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (308, 'Beef Enchiladas for One', 'One Dish Kitchen', 'https://onedishkitchen.com/beef-enchilada-recipe/', 35, 35, 0, 1, 1, 0, NULL, NULL, '1. Preheat the oven to 350°F. | 2. Heat the oil in a 10-inch skillet over medium heat, cook the onions 2 minutes, then the garlic 1 minute. | 3. Add the ground beef, salt, pepper, chili powder and cumin and cook about 8 minutes until browned, then drain on a paper towel. | 4. Spread 2 tablespoons enchilada sauce on the bottom of a small baking dish. | 5. Warm the tortillas, put 1 tablespoon cheese in the center of each, divide the beef between them, roll tightly and set seam-side down in the dish. | 6. Pour 1/3 cup enchilada sauce over the top and sprinkle with the remaining cheese. | 7. Bake 20 to 25 minutes until the cheese melts.', NULL);
