INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (310, 'Beef and Broccoli for One', 'One Dish Kitchen', 'https://onedishkitchen.com/beef-broccoli-recipe/', 25, 25, 0, 1, 1, 0, NULL, NULL, '1. Freeze the steak about 20 minutes, then slice it into 1/4-inch strips. | 2. Stir the ginger, garlic, soy sauce, water, brown sugar, cornstarch and pepper together in a small bowl. | 3. Heat half the oil in a 10-inch skillet over medium heat, add the broccoli, cover and cook 4 to 5 minutes until crisp-tender. Move it to a plate. | 4. Raise the heat to medium-high, add the remaining oil and cook the beef in a single layer 1 to 2 minutes per side. | 5. Pour in the sauce, lower the heat and simmer 2 to 3 minutes until thick, adding a little water if needed. | 6. Return the broccoli, stir to coat, and serve over rice with the sesame seeds.', NULL);
