INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (311, 'Salisbury Steak for One', 'One Dish Kitchen', 'https://onedishkitchen.com/salisbury-steak-recipe-for-one/', 30, 30, 1, 1, 1, 0, NULL, NULL, '1. Mix the ground beef, Worcestershire sauce, Italian seasoning, mustard powder, garlic powder, salt and pepper and shape into a patty about 1/2 inch thick. | 2. Heat the olive oil in a medium skillet over medium heat and cook the patty about 4 minutes per side. Move it to a plate and cover with foil. | 3. Lower the heat to medium-low, melt the butter in the skillet, cook the onions 3 minutes, then add the mushrooms for 3 more minutes. | 4. Stir in the Worcestershire sauce and beef broth, bring to a gentle boil and simmer 3 minutes. | 5. Stir in the sour cream, return the patty and cook 1 minute, spooning the sauce over it. | 6. Serve with the gravy poured over the patty.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (311, 1, 'beef patty', 'ground beef', 8.0, 8.0, 'oz', NULL, NULL, 0, '8 ounces ground beef');
