INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (313, 'Breakfast Bagel Sandwich', 'One Dish Kitchen', 'https://onedishkitchen.com/breakfast-bagel-recipe/', 10, 10, 0, 1, 1, 0, 1.0, 'sandwich', '1. Slice the bagel and toast both halves until golden. | 2. Whisk the eggs with the salt and pepper. | 3. Melt 1 tablespoon butter in an 8-inch skillet over medium heat, pour in the eggs and lift the edges so uncooked egg runs underneath. | 4. When the bottom is set and the top is still slightly wet, lay the cheese and ham across the center, then fold the egg over them. | 5. Butter the toasted bagel halves with the remaining butter, set the egg on the bottom half, close the sandwich and serve.', NULL);
