INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (315, 'Minestrone Soup for One', 'One Dish Kitchen', 'https://onedishkitchen.com/how-to-make-minestrone-soup-for-one/', 35, 35, 0, 1, 1, 0, NULL, NULL, '1. Cut the bacon into 1/4-inch pieces and cook in a medium pot over medium heat until crisp. Lift out and drain on paper towels. | 2. Cook the onion in the same pot about 1 minute, then the garlic for 30 seconds. | 3. Stir in the Worcestershire sauce, beans, diced tomatoes and mixed vegetables and cook 1 minute. | 4. Add the chicken broth, return the bacon and season with salt and pepper. | 5. Bring to a gentle boil, reduce the heat and simmer 10 minutes. | 6. Add the pasta and simmer 6 to 8 minutes until tender.', NULL);
