INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (316, 'Chicken Fricassee for One', 'One Dish Kitchen', 'https://onedishkitchen.com/chicken-fricassee-for-one/', 30, 30, 0, 1, 1, 0, NULL, NULL, '1. Cut the chicken into 1-inch cubes and season with half the salt and the pepper. | 2. Melt the butter in a 10-inch skillet over medium-high heat and brown the chicken on all sides, about 8 minutes. Move it to a plate and cover. | 3. Add the olive oil and cook the onions about 2 minutes, then the garlic 30 seconds. | 4. Pour in the broth, add the tarragon and bring to a boil. | 5. Return the chicken, reduce to low and simmer 10 minutes, stirring occasionally. | 6. Stir in the cream and peas and simmer 1 to 2 minutes until the sauce thickens. Serve over rice, mashed potatoes or noodles.', NULL);
