INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (320, 'White Bean Soup for One', 'One Dish Kitchen', 'https://onedishkitchen.com/white-bean-soup-recipe/', 30, 30, 0, 1, 1, 0, NULL, NULL, '1. Cook the bacon in a 2-quart saucepan over medium-high heat until crisp, remove it with a slotted spoon and set aside for garnish. | 2. If there is little fat in the pan, add 1 teaspoon olive oil. Cook the onions about 3 minutes, then stir in the garlic, rosemary and pepper for 1 more minute. | 3. Add the drained white beans and chicken broth, bring to a boil, then simmer 15 minutes, stirring occasionally. | 4. Mash some of the beans against the side of the pot to thicken the soup. | 5. Ladle into a bowl and top with the bacon.', NULL);
