INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (327, 'Creamy Mustard Chicken for One', 'One Dish Kitchen', 'https://onedishkitchen.com/chicken-with-mustard-tarragon-sauce-for-one/', 20, 20, 0, 1, 1, 0, NULL, NULL, '1. Melt the butter in a 10-inch skillet over medium heat. | 2. Season the chicken cubes with the salt and pepper. | 3. Cook the chicken about 6 minutes, turning occasionally, until browned on all sides. | 4. Move the chicken to a plate and cover to keep warm, then lower the heat to medium-low. | 5. Pour the cream into the skillet and scrape up the browned bits. | 6. Stir in the mustard and tarragon and simmer about 5 minutes, stirring often, until slightly thickened. | 7. Return the chicken to the pan and turn to coat in the sauce. | 8. Serve as is or over rice or buttered noodles.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (327, 1, NULL, 'butter', 1.0, 1.0, 'tbsp', NULL, NULL, 0, '1 tablespoon salted butter');
