INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (328, 'Baked Chicken Tenders for One', 'One Dish Kitchen', 'https://onedishkitchen.com/baked-chicken-tenders-for-one/', 20, 15, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 400°F. | 2. Stir the bread crumbs, Parmesan, Italian seasoning, garlic powder, salt and pepper together in a medium bowl. | 3. Melt the butter in a second bowl and dip a chicken strip in it. | 4. Press the buttered strip into the crumb mixture to coat it well. | 5. Set it on a parchment- or foil-lined baking sheet and repeat with the remaining strips. | 6. Bake 15 to 20 minutes until golden and cooked through (165°F inside). | 7. Serve with a dipping sauce.', NULL);
