INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (329, 'Lemon Chicken with Buttered Orzo for One', 'One Dish Kitchen', 'https://onedishkitchen.com/lemon-garlic-chicken-for-one/', 50, 20, 0, 1, 1, 0, NULL, NULL, '1. Stir the garlic, lemon juice, olive oil, paprika, Italian seasoning, salt and pepper together in a small bowl. | 2. Put the chicken in a shallow dish or bag, pour the marinade over it and refrigerate at least 20 minutes. | 3. Heat the oven to 350°F. | 4. Lift the chicken from the marinade onto a baking sheet and bake about 25 minutes until it reads 165°F. | 5. Cover loosely with foil and rest the chicken 5 to 10 minutes. | 6. Meanwhile boil the orzo in a pot of water 7 to 8 minutes, then drain. | 7. Stir the butter into the hot orzo until melted. | 8. Slice the chicken and serve over the orzo.', NULL);
