INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (334, 'Spaghetti and Meatballs for One', 'One Dish Kitchen', 'https://onedishkitchen.com/spaghetti-and-meatballs-recipe/', 30, 30, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 400°F. | 2. Pulse the onion, garlic, parsley and Parmesan in a food processor until finely chopped. | 3. Move to a large bowl, mix in the egg yolk and bread crumbs, then the salt, pepper, basil and oregano. | 4. Mix in the ground beef until combined. | 5. Roll into 1½-inch balls on a foil-lined baking sheet and bake about 20 minutes. | 6. Heat the tomato sauce to a simmer in a 2-quart saucepan, add the meatballs, cover loosely and simmer 10 minutes. | 7. Meanwhile boil the spaghetti until al dente and drain. | 8. Toss the spaghetti with the sauce and meatballs and top with fresh basil and extra Parmesan.', NULL);
