INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (335, 'Turkey Chili for One', 'One Dish Kitchen', 'https://onedishkitchen.com/turkey-chili/', 30, 30, 0, 1, 1, 0, NULL, NULL, '1. Heat the oil in a medium skillet over medium heat and cook the onions and bell pepper about 2 minutes. | 2. Add the garlic and cook 1 minute. | 3. Add the turkey, breaking it up, and cook about 8 minutes until no longer pink. | 4. Stir in the Italian seasoning, smoked paprika, salt and pepper. | 5. Add the diced tomatoes and black beans, bring to a boil, then simmer about 10 minutes until thickened. | 6. Taste, adjust the seasoning and serve.', NULL);
