INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (336, 'One Pot Chicken and Rice', 'Budget Bytes', 'https://www.budgetbytes.com/one-pot-chicken-and-rice/', 50, 25, 1, 4, 4, 0, NULL, NULL, '1. Mix the paprika, oregano, thyme, garlic powder, onion powder, salt and pepper and coat both sides of the chicken thighs with it. | 2. Heat 1 Tbsp of the oil in a deep skillet over medium and sear the thighs a few minutes per side until well browned (they will finish cooking in the rice), then move them to a plate. | 3. Lower the heat to medium-low, add the remaining oil and the diced onion and cook about 5 minutes until soft, scraping up the browned bits. | 4. Stir in the uncooked rice and toast 1 to 2 minutes. | 5. Pour in the broth and stir briefly, then set the chicken on top of the rice. | 6. Cover, bring to a full boil on medium-high, then reduce to low and simmer covered 20 minutes without lifting the lid. | 7. Turn off the heat and let it rest covered 5 minutes, then fluff the rice, garnish with parsley and serve.', NULL);
