INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (337, 'Beef Taco Skillet', 'Budget Bytes', 'https://www.budgetbytes.com/beef-taco-skillet/', 25, 25, 0, 4, 4, 0, NULL, NULL, '1. Stir together the chili powder, smoked paprika, cumin, cayenne, oregano, salt and pepper in a small bowl. | 2. Slice the green onion and halve the grape tomatoes. | 3. Brown the ground beef in a skillet over medium heat, draining excess fat if it is 20% fat or more. | 4. Rinse and drain the black beans, add them to the skillet with the seasoning and stir about 2 minutes until heated. | 5. Add the tomatoes and cook about 3 minutes, stirring often, until they begin to break down. | 6. Stir in the tortilla chips. | 7. Scatter the cheddar over the top, cover and heat 1 to 2 minutes until melted. | 8. Sprinkle with green onion and serve.', NULL);
