INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (338, 'Curried Ground Beef with Peas and Potatoes', 'Budget Bytes', 'https://www.budgetbytes.com/curry-beef-with-peas/', 35, 30, 0, 6, 6, 0, NULL, NULL, '1. Cook the garlic, ginger and oil in a large deep skillet over medium heat 1 to 2 minutes. | 2. Add the curry powder, turmeric and red pepper and toast about 1 minute. | 3. Add the ground beef and cook until no pink remains. | 4. Peel the potato and cut into 1/2-inch cubes. | 5. Stir in the potato and broth, cover, raise the heat to medium-high and bring to a boil. | 6. Lower to medium-low and simmer covered about 10 minutes until the potato is tender, then uncover and simmer a few more minutes until most of the broth has evaporated. | 7. Stir in the peas to heat through, season with salt and top with green onions.', NULL);
