INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (339, 'BBQ Beef and Cabbage', 'Budget Bytes', 'https://www.budgetbytes.com/bbq-beef-and-cabbage/', 30, 30, 0, 3, 3, 0, NULL, NULL, '1. Add the olive oil and ground beef to a large skillet over medium heat and break up the beef as it browns. | 2. Finely dice the onion and add it with the paprika, garlic powder and about 1/2 tsp of the salt, cooking until soft. | 3. Finely shred the cabbage. Pour 1/4 cup water into the skillet to loosen the browned bits, add the cabbage, cover and simmer about 5 minutes until it wilts. | 4. Stir in the tomato sauce, vinegar, brown sugar, Worcestershire and Dijon and simmer uncovered a few minutes until the sauce thickens, adding the remaining salt to taste. | 5. Sprinkle the cheddar over the top, cover and heat 1 to 2 minutes until melted. | 6. Top with sliced green onion and serve.', NULL);
