INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (340, 'Mediterranean Hummus Bowls', 'Budget Bytes', 'https://www.budgetbytes.com/mediterranean-hummus-bowls/', 25, 25, 0, 4, 4, 0, NULL, NULL, '1. Cook the ground beef in a skillet over medium heat with the oregano, cumin, garlic powder and salt, stirring, until browned and evenly seasoned. | 2. While it cooks, prep the toppings, soaking the sliced red onion in ice water about 5 minutes to mellow it. | 3. Build each bowl with 1 cup of rice and 1/4 cup of hummus, then divide the beef and remaining toppings among the bowls. | 4. Serve right away, or refrigerate for meal prep and eat cold.', NULL);
