INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (342, 'Baked Spaghetti Casserole', 'Budget Bytes', 'https://www.budgetbytes.com/baked-spaghetti-casserole/', 55, 30, 0, 6, 6, 0, NULL, NULL, '1. Dice the onion and mince the garlic. | 2. Heat the olive oil in a large skillet over medium and brown the Italian sausage. | 3. Add the onion and garlic and cook until the onion is soft and translucent. | 4. Stir in the tomato paste, crushed tomatoes, Italian seasoning, salt and water, bring to a simmer, then lower the heat and simmer while the pasta cooks. | 5. Heat the oven to 350°F and boil the spaghetti in salted water until just shy of tender, then drain without rinsing. | 6. Stir the spaghetti into the sauce. | 7. Mix the cottage cheese, Parmesan and pepper in a bowl. | 8. In a greased casserole dish layer half the spaghetti, then the cheese mixture, then the rest of the spaghetti, and top with the mozzarella. | 9. Cover with foil and bake 30 minutes, rest 5 to 10 minutes, then slice and garnish with parsley.', NULL);
