INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (343, 'One Pot Spinach and Artichoke Pasta', 'Budget Bytes', 'https://www.budgetbytes.com/spinach-artichoke-wonderpot/', 25, 25, 0, 6, 6, 0, NULL, NULL, '1. Slice the mushrooms, drain and chop the artichoke hearts, and slice the onion and garlic. | 2. Combine the broth, olive oil, mushrooms, artichokes, onion and garlic in a large pot, add the fettuccine (broken in half if needed), and season with the oregano, thyme and pepper. | 3. Press everything under the broth, cover and bring to a rolling boil over high heat. | 4. Stir as soon as it boils, lower to a simmer, cover and cook 10 to 15 minutes, stirring every couple of minutes, until the pasta is tender and most of the liquid is absorbed. | 5. Stir in the spinach and let it wilt in the residual heat. | 6. Serve hot topped with red pepper and feta if desired.', NULL);
