INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (344, 'Greek Marinated Chicken', 'Budget Bytes', 'https://www.budgetbytes.com/greek-marinated-chicken/', 75, 20, 0, 8, 8, 0, 8.0, 'piece', '1. Stir together the yogurt, olive oil, garlic, oregano, salt and pepper in a bowl. | 2. Grate the lemon zest into the bowl, squeeze in 1 to 2 Tbsp juice and stir until blended. | 3. Chop about a quarter bunch of parsley and stir it in. | 4. Put the chicken and marinade in a gallon zip-top bag, press out the air, massage to coat and refrigerate 30 minutes. | 5. Heat the oven to 375°F. | 6. Arrange the chicken in a 9x13 dish without pouring on the leftover marinade. | 7. Bake uncovered 45 to 60 minutes until golden and 165°F inside.', NULL);
