INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (345, 'Slow Cooker Coconut Curry Lentils', 'Budget Bytes', 'https://www.budgetbytes.com/slow-cooker-coconut-curry-lentils/', 270, 30, 0, 10, 10, 0, NULL, NULL, '1. Dice the onion, mince the garlic, peel and dice the sweet potato into 1/4 to 1/2-inch cubes and peel and slice the carrots. | 2. Add the onion, garlic, sweet potato, carrots, lentils, curry powder, cloves, diced tomatoes, tomato sauce and broth to a 6-quart slow cooker and stir. | 3. Cover and cook on high 4 hours or low 7 to 8 hours until the lentils are tender and most of the liquid is absorbed. | 4. Stir in the coconut milk and adjust the salt and spices. | 5. Serve 1 cup of the lentils over 1 cup of cooked rice and garnish with diced red onion and cilantro.', NULL);
