INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (346, 'BBQ Chicken Burrito Bowls', 'Budget Bytes', 'https://www.budgetbytes.com/bbq-chicken-burrito-bowls/', 20, 20, 0, 4, 4, 0, NULL, NULL, '1. Cook 4 cups of rice if you do not already have it. | 2. Chop or shred the cooked chicken breast and toss it with 2 to 3 tablespoons of the BBQ sauce. | 3. Drain and rinse the black beans, cube the zucchini into 1/4 to 1/2-inch pieces, shred the pepper jack, slice the green onions and slice the avocado. | 4. Put 1 cup of rice in each of four bowls and divide the chicken, beans, corn, zucchini, cheese, green onions and avocado among them. | 5. Drizzle about 1 Tbsp more BBQ sauce over each bowl and serve, or refrigerate for lunches.', NULL);
