INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (348, 'Potato Leek Soup', 'Budget Bytes', 'https://www.budgetbytes.com/potato-leek-soup/', 50, 35, 0, 8, 8, 0, NULL, NULL, '1. Boil the whole potatoes, skins on, in salted water 15 to 20 minutes until fork-tender, then drain. | 2. Trim and rinse the leeks well and mince the leeks, garlic and green onion. | 3. In the same pot melt the butter with the olive oil over medium heat and cook the leeks, garlic, salt and pepper about 8 minutes until soft. | 4. Dice about 2 cups of the cooked potatoes into 1/2-inch pieces and set aside. | 5. Return the remaining whole potatoes to the pot with the thyme, bay leaf, vinegar and broth and bring to a gentle simmer, mashing the potatoes in the pot and leaving some texture. | 6. Remove the bay leaf and thyme stem, temper the cream with a ladleful of hot broth and stir it into the pot, then simmer gently 5 to 8 minutes without boiling. | 7. Cool a couple of minutes, blend about half the soup until smooth and stir it back in. | 8. Stir in the reserved diced potatoes and green onion and adjust the salt and pepper.', NULL);
