INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (349, 'Creamy Mushroom Soup', 'Budget Bytes', 'https://www.budgetbytes.com/creamy-mushroom-soup/', 35, 35, 0, 4, 4, 0, NULL, NULL, '1. Wipe the mushrooms clean, slice them and mince the garlic. | 2. Sauté the mushrooms with the olive oil and a pinch of salt and pepper in a soup pot over medium heat until they release their moisture, it evaporates and they turn very dark brown, then add the garlic for 1 minute. | 3. Add the butter and flour and cook about 2 minutes, stirring, until deep golden brown. | 4. Add the broth, soy sauce and thyme, stirring to loosen the flour, and simmer until slightly thickened. | 5. Stir in the cream, adjust the salt and pepper and serve with crusty bread.', NULL);
