INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (351, 'Lentil and Cranberry Salad', 'Budget Bytes', 'https://www.budgetbytes.com/lentil-and-cranberry-salad/', 35, 35, 0, 6, 6, 0, NULL, NULL, '1. Simmer the rinsed lentils in 3 cups of water, covered with the lid slightly tilted, about 20 minutes until tender but still holding their shape, then drain and rinse with cold water. | 2. Whisk the lemon juice, vinegar, Dijon, sugar, garlic powder, salt and pepper in a small bowl, then slowly whisk in the oil until smooth. | 3. Combine the cooled lentils and spinach in a large bowl and fold in the cranberries, apple, feta and walnuts. | 4. Pour the vinaigrette over and toss to coat.', NULL);
