INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (352, 'Easy Homemade Falafel', 'Budget Bytes', 'https://www.budgetbytes.com/falafel/', 100, 40, 0, 4, 6, 1, 19.0, 'falafel', '1. Process the chickpeas, onion, parsley, cilantro, garlic, cumin, cayenne and salt in a food processor into a chunky paste, scraping down the bowl. | 2. Move to a bowl and stir in the baking powder, then add the flour 2 Tbsp at a time until the mixture holds its shape and does not stick to your hands. | 3. Refrigerate at least 1 hour. | 4. Scoop about 2 Tbsp per falafel and shape into small patties (optionally freeze them on a parchment-lined sheet and bag them). | 5. Heat the oil in a skillet over medium heat until shimmering and fry the patties in batches, fresh or frozen, until deep golden on each side. | 6. Drain on paper towels or parchment.', NULL);
