INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (353, 'One Pot Veggie Rice Bowl', 'Budget Bytes', 'https://www.budgetbytes.com/one-pot-veggie-rice-bowl/', 25, 10, 0, 1, 1, 0, NULL, NULL, '1. Put the rice, garlic and frozen vegetables in a small saucepot. | 2. Mix 1 tsp of the soy sauce into the water, pour it in and stir. | 3. Rinse the egg and set it in the center on top of the rice. | 4. Cover, bring to a full boil over high heat, then reduce to low and simmer 15 minutes without lifting the lid. | 5. Turn off the heat, remove the egg, replace the lid and rest the rice 5 minutes while the egg cools in cold water. | 6. Fluff the rice and vegetables with a fork and season with the sesame oil and the remaining soy sauce. | 7. Serve in a bowl topped with the peeled egg, green onion and sriracha.', NULL);
