INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (354, 'Golden Rice Bowls', 'Budget Bytes', 'https://www.budgetbytes.com/golden-rice-bowls/', 60, 25, 0, 6, 6, 0, NULL, NULL, '1. Dice the onion and mince the garlic and cook them in the butter in a medium pot over medium-low 3 to 5 minutes until soft. | 2. Add the rice, turmeric, cumin and cinnamon and toast about 3 minutes, stirring, until the rice crackles slightly. | 3. Add the broth and bay leaf, cover, bring to a full boil, then reduce to low and simmer 20 minutes. | 4. Turn off the heat and leave covered and undisturbed 20 minutes, then fluff. | 5. Sauté a minced garlic clove in the olive oil in a large pot 1 to 2 minutes, add the spinach and cook about 3 minutes until wilted, and season with salt and pepper. | 6. Fry or soft-boil the eggs. | 7. Fill each bowl with about 1 cup of rice, 1/2 cup of spinach and an egg.', NULL);
