INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (355, 'Homemade Chicken Yakisoba', 'Budget Bytes', 'https://www.budgetbytes.com/chicken-yakisoba/', 30, 30, 0, 6, 6, 0, NULL, NULL, '1. Peel and grate the ginger, grate the carrots, cut the cabbage into thin strips, thinly slice the onion, cut the broccoli into bite-size pieces and slice the chicken into thin strips. | 2. Bring a medium pot of water to a boil for the noodles. | 3. Heat the oil in a large skillet over medium-high, sauté the ginger 30 to 60 seconds, add the chicken and cook about 5 minutes until no longer pink. | 4. Add all the vegetables and stir-fry 5 to 10 minutes until wilted. | 5. Cook the ramen noodles 2 to 3 minutes until just tender, drain and toss with the sesame oil. | 6. Stir together the soy sauce, Worcestershire, ketchup, sriracha and sugar. | 7. Pour the sauce over the chicken and vegetables over medium-high heat, add the noodles and toss until heated through.', NULL);
