INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (356, 'Ham and Bean Soup for One', 'One Dish Kitchen', 'https://onedishkitchen.com/ham-bean-soup/', 20, 20, 0, 1, 1, 0, NULL, NULL, '1. Melt the butter in a 2-quart saucepan over medium-high heat and cook the carrot, celery, onion and garlic about 3 minutes, stirring, until softened. | 2. Stir in the Creole seasoning and cook 30 seconds. | 3. Add the ham, beans and broth, bring to a gentle boil, then reduce the heat and simmer 15 minutes, stirring now and then. | 4. Adjust the seasoning and serve hot.', NULL);
