INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (357, 'Chicken and Yellow Rice for One', 'One Dish Kitchen', 'https://onedishkitchen.com/chicken-and-golden-rice-for-one/', 25, 15, 0, 1, 1, 0, NULL, NULL, '1. Heat the oil in a 1-quart saucepan over medium-high heat and cook the garlic about 30 seconds. | 2. Stir in the turmeric and rice and cook about 1 minute. | 3. Pour in the broth, add the salt and pepper, bring to a boil, then lower the heat, cover and simmer 20 minutes until the rice is tender and the liquid is absorbed. | 4. Mix the chicken, onion, tomato and lemon juice in a bowl. | 5. Add the cooked rice and fold gently. | 6. Whisk the soy sauce and hot sauce together and drizzle over the top or serve on the side.', NULL);
