INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (358, 'Cheesy Baked Eggs for One', 'One Dish Kitchen', 'https://onedishkitchen.com/cheesy-baked-eggs-for-one/', 20, 10, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 400°F and butter the inside of a 10-ounce oven-safe ramekin. | 2. Whisk the eggs and cream in a small bowl. | 3. Stir in the cheddar, Parmesan, salt and pepper. | 4. Pour into the ramekin, set it on a rimmed baking sheet and bake 15 to 18 minutes until the center is set. | 5. Rest 5 minutes before serving.', NULL);
