INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (360, 'Egg Wrap with Ham and Cheese', 'One Dish Kitchen', 'https://onedishkitchen.com/egg-wrap-recipe/', 10, 10, 0, 1, 1, 0, NULL, NULL, '1. Beat the eggs with the salt and pepper in a small bowl. | 2. Melt the butter in an 8-inch skillet over medium heat and pour in the eggs, lifting the edges so uncooked egg flows underneath, and tilt the pan to spread them thin. | 3. Cook 30 to 60 seconds until the edges are set, flip and cook the other side 30 to 60 seconds. | 4. Lay the ham and cheese over the egg in the pan so the cheese melts. | 5. Roll up and serve warm.', NULL);
