INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (361, 'Bacon, Egg and Cheese Cup', 'One Dish Kitchen', 'https://onedishkitchen.com/bacon-egg-cheese-cup/', 20, 10, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 400°F and butter a 10-ounce oven-safe ramekin. | 2. Whisk the eggs and cream in a small bowl. | 3. Stir in the bacon, cheddar, Parmesan, green onions, salt and pepper. | 4. Pour into the ramekin and bake 15 to 18 minutes until the eggs are set. | 5. Serve warm.', NULL);
