INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (362, 'Zuppa Toscana for One', 'One Dish Kitchen', 'https://onedishkitchen.com/zuppa-toscana-recipe/', 25, 25, 0, 1, 1, 0, NULL, NULL, '1. Fry the bacon in a 2-quart saucepan over medium-high heat about 3 minutes until crisp and move it to a paper towel-lined plate. | 2. Add the sausage, onions, garlic and chili powder to the pan and cook about 5 minutes, breaking up the sausage, until browned. | 3. Pour in the broth, stir in the potato, bring to a boil, then simmer on medium-low about 12 minutes until the potato is slightly tender. | 4. Stir in the spinach and cook 3 minutes. | 5. Turn off the heat and stir in the cream. | 6. Ladle into a bowl and top with the crumbled bacon.', NULL);
