INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (363, 'Biscuit and Sausage Gravy for One', 'One Dish Kitchen', 'https://onedishkitchen.com/biscuit-sausage-gravy/', 20, 20, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 400°F and line a baking sheet with parchment. | 2. Whisk the flour, baking powder, sugar and salt, then rub in the cold butter until it looks like coarse sand. | 3. Stir in the 1/4 cup milk until the dough just comes together and drop it onto the baking sheet. | 4. Bake 10 to 12 minutes until golden. | 5. Meanwhile brown the crumbled sausage in a hot 10-inch skillet. | 6. Sprinkle in the flour and stir 1 minute, then slowly stir in the 1/2 cup milk and stir about 5 minutes until the gravy thickens and bubbles, then stir in the Creole seasoning. | 7. Split the biscuit and spoon the gravy over and between the halves.', NULL);
