INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (364, 'Mac and Cheese for One', 'One Dish Kitchen', 'https://onedishkitchen.com/macaroni-cheese-recipe-for-one/', 20, 20, 0, 1, 1, 0, NULL, NULL, '1. Boil salted water in a 1-quart saucepan and cook the macaroni 7 to 8 minutes until al dente, then drain and wipe the pan dry. | 2. Melt the butter in the same pan over medium heat, whisk in the flour and cook about 1 minute until pale golden. | 3. Slowly whisk in the milk and cook about 2 minutes until it coats the back of a spoon. | 4. Off the heat, stir in the cheddar and dry mustard until smooth. | 5. Add the pasta and stir to coat, adding a pinch of salt if needed.', NULL);
