INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (365, 'Twice Baked Potato Casserole for One', 'One Dish Kitchen', 'https://onedishkitchen.com/twice-baked-potato-casserole/', 100, 30, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 425°F, prick the scrubbed potato with a fork and bake on a baking sheet 40 to 50 minutes until a fork slides in easily, then cool it. | 2. Lower the oven to 375°F, halve the potato and scoop the flesh into a bowl. | 3. Mash it, leaving some small chunks, and stir in the melted butter, sour cream, milk, salt, pepper and egg. | 4. Fold in the bacon and a little over half of the cheese. | 5. Butter a 10-ounce ramekin, fill it with the potato mixture, top with the remaining cheese and set it on a rimmed baking sheet. | 6. Bake about 25 minutes until the cheese melts and the center is hot.', NULL);
