INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (372, 'Apple Dutch Baby for One', 'One Dish Kitchen', 'https://onedishkitchen.com/apple-dutch-baby-recipe/', 25, 10, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 400°F and put the butter in a 5-inch baking dish or small cast iron skillet in the oven to melt. | 2. Whisk the egg, milk, vanilla and 1 tsp sugar until smooth. | 3. Whisk in the flour, salt and 1/8 tsp cinnamon until no lumps remain. | 4. Pull the hot pan from the oven and swirl the melted butter to coat the bottom. | 5. Spread the apple slices in the pan and slowly pour the batter over them. | 6. Mix the topping sugar and cinnamon and sprinkle it over the batter. | 7. Bake 20 to 25 minutes until the edges are tall and golden and the center is puffed and set, and serve warm.', NULL);
