INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (373, 'Caprese Pasta for One', 'One Dish Kitchen', 'https://onedishkitchen.com/caprese-pasta-recipe/', 20, 20, 0, 1, 1, 0, NULL, NULL, '1. Cook the angel hair in salted water about 8 minutes until al dente, then drain. | 2. Heat 1 Tbsp of the oil in a 10-inch skillet over medium heat and cook the garlic and Italian seasoning about 30 seconds. | 3. Add the tomatoes and 1/8 tsp of the salt and sauté 2 minutes. | 4. Add the pasta and toss. | 5. Off the heat, add the remaining oil, mozzarella, basil and Parmesan and toss to combine. | 6. Season with salt and pepper and serve.', NULL);
