INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (377, 'Peanut Butter Oatmeal', 'One Dish Kitchen', 'https://onedishkitchen.com/peanut-butter-oatmeal/', 15, 15, 0, 1, 1, 0, NULL, NULL, '1. Combine the oats, milk or water and salt in a 1-quart saucepan. | 2. Bring to a boil over medium-high heat, then lower to medium and cook 5 to 7 minutes, stirring now and then, until the oats are tender and thick. | 3. Take off the heat, cover and rest 2 minutes. | 4. Stir in the peanut butter until smooth, then the honey and a pinch of cinnamon. | 5. Serve warm with sliced banana or berries if you like (or microwave the oats, milk and salt 2 minutes, stir, rest 5 minutes and add the rest).', NULL);
