INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (378, 'Stuffed Pepper Skillet', 'Taste of Home', 'https://www.tasteofhome.com/recipes/beef-pepper-skillet/', 30, 30, 0, 6, 6, 0, NULL, NULL, '1. Brown the ground beef in a large heavy skillet over medium heat 6 to 8 minutes, breaking it into crumbles, then drain the fat. | 2. Add the tomatoes with their liquid, the broth, chili powder, salt and garlic powder and bring to a boil. | 3. Stir in the rice and sliced peppers, lower the heat and simmer covered 8 to 10 minutes until the liquid is absorbed. | 4. Take off the heat, sprinkle with the cheese and let it stand covered until melted.', NULL);
