INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (383, 'Hamburger Hash Brown Casserole', 'Taste of Home', 'https://www.tasteofhome.com/recipes/beefy-hash-brown-bake/', 50, 30, 1, 4, 4, 0, NULL, NULL, '1. Heat the oven to 350°F and mix the frozen hash browns with the oil and pepper. | 2. Press into a greased 8-inch square baking dish and bake uncovered 25 to 30 minutes until set. | 3. Meanwhile brown the beef 5 to 7 minutes in a large saucepan and drain. | 4. Stir in the water, gravy mix and garlic salt, boil and stir 2 minutes, then add the mixed vegetables and cook 5 minutes. | 5. Stir in half the fried onions and half the cheddar and spread the filling over the potatoes. | 6. Bake uncovered 10 minutes, top with the remaining onions and cheese and bake about 5 minutes more until melted.', NULL);
