INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (386, 'Taco-Stuffed Pepper Cups', 'Taste of Home', 'https://www.tasteofhome.com/recipes/taco-stuffed-pepper-cups/', 30, 30, 0, 2, 2, 0, NULL, NULL, '1. Heat the oven to 350°F, halve the peppers lengthwise, seed them and boil in a large pot 3 to 5 minutes until crisp-tender, then drain, rinse with cold water and set aside. | 2. Cook the beef and onion in a large skillet over medium heat until no longer pink, crumbling the beef, and drain the fat. | 3. Stir in the beans, tomato sauce and taco seasoning, bring to a boil and simmer uncovered 5 to 6 minutes. | 4. Spoon the filling into the pepper halves and set them in an ungreased 8-inch square baking dish. | 5. Bake uncovered 10 to 12 minutes until the peppers are tender, then top with the sour cream, cheese and tomato.', NULL);
