INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (405, 'Crepes for One', 'The Solo Spoon', 'https://www.thesolospoon.com/crepe-recipe-for-one/', 47, 17, 1, 1, 1, 0, 3.0, 'crepe', '1. Whisk the egg, sugar and melted butter in a medium bowl, then whisk in the milk and add all the flour at once. | 2. Whisk until smooth, stir in the vanilla, then cover and refrigerate 30 minutes. | 3. Heat an 8-inch nonstick pan over medium heat and coat lightly with cooking spray. | 4. Pour in 2 to 3 tablespoons of batter and tilt the pan to spread it thin. | 5. Cook the first side 60 to 90 seconds until the edges look dry, flip and cook the other side 20 to 30 seconds. | 6. Stack the finished crepes on a plate, repeat with the remaining batter and add your toppings.', NULL);
