INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (407, 'Hashbrown Egg Bake Meal Prep', 'The Solo Spoon', 'https://www.thesolospoon.com/hashbrown-egg-bake-meal-prep/', 55, 20, 0, 4, 4, 0, NULL, NULL, '1. Dice the red and green bell peppers. | 2. Heat the oven to 350°F. | 3. Whisk the eggs, egg whites, garlic powder, salt and pepper in a large bowl. | 4. Stir in the peppers, hash browns, turkey sausage crumbles and cheddar. | 5. Spoon the mixture into 1-cup wells of a silicone tray or muffin tin, filling each about three-quarters full. | 6. Bake 35 to 45 minutes until the eggs are set with no wet spots. | 7. Cool in the tray 15 minutes, then pop out and pack in containers.', NULL);
