INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (408, 'Baked Chicken Thighs for One', 'One Dish Kitchen', 'https://onedishkitchen.com/baked-chicken-thighs/', 35, 10, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 400°F and pat the chicken thighs dry. | 2. Mix the garlic powder, onion powder, paprika, oregano, salt and pepper, set aside 1/4 teaspoon, then stir the olive oil into the rest. | 3. Coat the thighs evenly with the mixture, working some under the skin. | 4. Set the thighs on a wire rack over a baking sheet and sprinkle with the reserved seasoning. | 5. Bake 30 to 35 minutes until the inside reads 170°F. | 6. Rest 5 minutes before eating.', NULL);
