INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (409, 'Baked Chicken Breast for One', 'One Dish Kitchen', 'https://onedishkitchen.com/baked-chicken-breast/', 25, 10, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 400°F and line a baking sheet with parchment or foil. | 2. Stir the salt, pepper, garlic powder and smoked paprika together in a small bowl. | 3. Set the chicken on the sheet, pour the oil over it and rub it over the whole surface. | 4. Sprinkle half the seasoning over the top, flip and season the other side with the rest. | 5. Bake 20 to 25 minutes until a thermometer reads 165°F. | 6. Cover loosely with foil and rest 5 to 10 minutes before slicing.', NULL);
