INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (418, 'Slow Cooker Chicken Tacos', 'Taste of Home', 'https://www.tasteofhome.com/recipes/lime-chicken-tacos/', 345, 10, 1, 6, 6, 0, NULL, NULL, '1. Put the chicken in a 3-quart slow cooker, pour the lime juice over it and sprinkle on the chili powder. | 2. Cover and cook on low 5 to 6 hours until tender. | 3. Move the chicken to a board and shred it with two forks once it is cool enough to handle. | 4. Return the chicken to the slow cooker with its juices, stir in the corn and salsa and cook on low about 30 minutes. | 5. Warm the tortillas and spoon the filling into them with your favorite toppings.', NULL);
