INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (419, 'Slow Cooker Tortellini and Meatballs', 'Taste of Home', 'https://www.tasteofhome.com/recipes/meatball-tortellini/', 190, 10, 1, 6, 6, 0, NULL, NULL, '1. Combine the thawed meatballs and the tortellini in a 3-quart slow cooker. | 2. Whisk the soup, water and Creole seasoning together in a bowl and pour over the meatballs and tortellini; stir well. | 3. Cover and cook on low 3 to 4 hours until the tortellini are tender. | 4. Stir in the thawed vegetables during the last half hour of cooking.', NULL);
