INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (420, 'Slow Cooker Pulled Pork Sandwiches', 'Taste of Home', 'https://www.tasteofhome.com/recipes/slow-cooker-pulled-pork-sandwiches/', 530, 20, 1, 10, 10, 0, NULL, NULL, '1. Cut the pork roast in half and set it in a 5-quart slow cooker. | 2. Mix the beef broth with 1/3 cup of the Worcestershire sauce and 1/3 cup of the hot sauce and pour over the pork. | 3. Cover and cook on low 8 to 10 hours until tender. | 4. Lift out the pork, throw away the cooking juices and shred the meat with two forks, then put it back in the slow cooker. | 5. Stir the ketchup, molasses, mustard and the remaining Worcestershire and hot sauce together and pour over the pork. | 6. Cover and cook on high 30 minutes until hot, then pile onto split rolls.', NULL);
