INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (421, 'Cheeseburger Stuffed Pasta Shells', 'Taste of Home', 'https://www.tasteofhome.com/recipes/cheeseburger-stuffed-pasta-shells/', 45, 45, 0, 6, 6, 0, NULL, NULL, '1. Heat the oven to 350°F and cook the shells to the package directions, then drain, rinse in cold water and drain again. | 2. Brown the beef and onion in a large skillet over medium-high heat for 6 to 8 minutes, crumbling the beef, and drain. | 3. Stir in the tomato sauce, ketchup, mustard and pepper, then stir in 3/4 cup of the cheddar. | 4. Spoon about 2 tablespoons of filling into each shell and set the shells in a greased 11x7-inch baking dish. | 5. Cover and bake 12 to 15 minutes, sprinkle on the rest of the cheese and bake uncovered about 5 minutes until melted.', NULL);
