INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (422, 'Baked Feta Pasta', 'Taste of Home', 'https://www.tasteofhome.com/recipes/baked-feta-pasta/', 45, 15, 1, 8, 8, 0, NULL, NULL, '1. Heat the oven to 400°F. Put the tomatoes, garlic and 1/4 cup of the olive oil in a 13x9-inch baking dish. | 2. Set the block of feta in the center, drizzle with the rest of the oil, and season with salt and pepper. | 3. Bake 30 to 40 minutes until the tomato skins split and the garlic is soft. | 4. Meanwhile cook the pasta to al dente, drain and save 1 cup of the cooking water. | 5. Stir the feta and tomatoes together, pressing the tomatoes, then add the pasta and toss. | 6. Thin with pasta water as needed and top with basil.', NULL);
