INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (423, 'Salsa Verde Chicken Casserole', 'Taste of Home', 'https://www.tasteofhome.com/recipes/salsa-verde-chicken-casserole/', 30, 30, 0, 6, 6, 0, NULL, NULL, '1. Heat the oven to 400°F and mix the chicken, sour cream and 3/4 cup of the salsa verde in a bowl. | 2. Spread 1/4 cup of salsa verde across the bottom of a greased 8-inch square baking dish. | 3. Layer half the tortillas, half the chicken mixture, half the tomatoes, all the cilantro and half the cheese. | 4. Repeat with the remaining tortillas, chicken mixture, tomatoes and cheese. | 5. Bake uncovered 20 to 25 minutes until bubbly and serve with the remaining salsa verde.', NULL);
