INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (424, 'Flavorful Chicken Fajitas', 'Taste of Home', 'https://www.tasteofhome.com/recipes/flavorful-chicken-fajitas/', 270, 25, 1, 6, 6, 0, NULL, NULL, '1. Mix 2 tablespoons of the oil with the lemon juice, seasoned salt, oregano, cumin, garlic powder, chili powder, paprika and pepper flakes in a large bowl. | 2. Toss in the chicken strips, cover and refrigerate 1 to 4 hours. | 3. Saute the red and green peppers, green onions and chopped onion in the remaining 2 tablespoons oil in a heavy skillet until crisp-tender, then set aside warm. | 4. Drain the chicken, discard the marinade and cook in the same skillet over medium-high heat 5 to 6 minutes until no longer pink. | 5. Return the vegetables to the pan to heat through, then spoon into warmed tortillas and fold.', NULL);
