INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (425, 'Slow Cooker Mexican Beef Stuffed Peppers', 'Taste of Home', 'https://www.tasteofhome.com/recipes/mexican-beef-stuffed-peppers/', 315, 25, 1, 4, 4, 0, NULL, NULL, '1. Cut the tops off the peppers and remove the seeds. | 2. Brown the ground beef in a large skillet until no longer pink and drain. | 3. Stir in the rice, 1-1/2 cups of the cheese, the salsa and the pepper sauce. | 4. Spoon the filling into the peppers, stand them in a 5-quart slow cooker and pour the water around them. | 5. Cover and cook on low 5 to 6 hours until the peppers are tender. | 6. Top with the remaining cheese and the cilantro.', NULL);
