INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (426, 'Risotto for One', 'One Dish Kitchen', 'https://onedishkitchen.com/how-to-make-risotto-for-one/', 30, 30, 0, 1, 1, 0, NULL, NULL, '1. Heat the broth in a 2-quart saucepan on low until barely simmering and keep it warm. | 2. Melt 1 tablespoon of the butter with the olive oil in a deep 10-inch skillet over medium heat and cook the mushrooms about 1 minute. | 3. Add the onions, garlic and salt and cook about 1 minute until the onions soften. | 4. Stir in the rice and toast about 2 minutes until the edges turn translucent. | 5. Pour in the wine and stir until nearly gone, about 2 minutes. | 6. Add 1/4 cup of warm broth at a time, stirring until each addition is absorbed, for about 20 minutes until the rice is tender with a slight bite. | 7. Off the heat, stir in the remaining butter and the Parmesan, adjust the salt and serve right away.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (426, 1, NULL, 'chicken broth', 1.75, 1.75, 'cup', 'low sodium', NULL, 0, '1 ½ to 2 cups low sodium chicken broth');
