INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (427, 'Turkey Cutlet with Gravy', 'One Dish Kitchen', 'https://onedishkitchen.com/turkey-cutlets-recipe-for-one/', 20, 20, 0, 1, 1, 0, NULL, NULL, '1. Season the cutlet with the Italian seasoning, salt and pepper and melt 1 tablespoon of the butter in a medium skillet over medium heat. | 2. Cook the cutlet 2 to 3 minutes per side until no longer pink, then move it to a plate and cover. | 3. Melt the remaining butter in the same skillet and cook the onions and garlic about 2 minutes. | 4. Stir in the flour and cook about 1 minute, then pour in the broth and stir about 2 minutes until the sauce thickens. | 5. Return the cutlet to the pan on low heat, spoon the sauce over it and cook 2 more minutes.', NULL);
