INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (428, 'Carne Asada for One', 'One Dish Kitchen', 'https://onedishkitchen.com/carne-asada-recipe/', 60, 30, 0, 1, 1, 0, NULL, NULL, '1. Whisk 1/4 cup of the olive oil with the soy sauce, lime juice, vinegar, sugar, pepper and cumin, then stir in the garlic, jalapeño and cilantro. | 2. Seal the steak and marinade in a zip-top bag and refrigerate 30 minutes to 3 hours. | 3. Heat a heavy 10-inch skillet over medium-high heat 1 minute, add the 1/2 tablespoon olive oil and heat 30 seconds. | 4. Sear the steak 4 to 5 minutes per side for medium rare to medium. | 5. Rest the steak 10 minutes, then slice across the grain at an angle. | 6. Serve with warm tortillas, salsa, onion, guacamole and lime if you like.', NULL);
