INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (430, 'Harvest Sheet Pan Dinner', 'Two Cloves Kitchen', 'https://twocloveskitchen.com/harvest-sheet-pan-dinner/', 35, 35, 0, 4, 4, 0, NULL, NULL, '1. Heat the oven to 400°F and line a baking sheet with parchment if you like. Cut the sausages into thick diagonal pieces. | 2. Slice the shallots into rings, peel and cube the sweet potato, and halve the Brussels sprouts after removing any browned outer leaves. | 3. Finely chop the rosemary. | 4. Toss the sweet potato, sprouts, shallots, sausage, rosemary, olive oil, garlic powder, salt and pepper together until coated. | 5. Spread on the baking sheet and roast 15 minutes, flip, and roast another 15 minutes until browned at the edges.', NULL);
