INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (431, 'Sheet Pan Chicken Sausage and Veggies', 'Healthyish Appetite', 'https://healthyishappetite.com/sheet-pan-chicken-sausage-and-veggies/', 40, 40, 0, 4, 4, 0, NULL, NULL, '1. Heat the oven to 400°F and line two sheet pans with parchment. | 2. Toss the halved potatoes with 2 tablespoons of the olive oil, the salt, pepper and granulated garlic on the first pan and roast 10 minutes. | 3. Put the sliced sausage and the peppers on the second pan and toss only the peppers with the remaining oil and a pinch of salt. | 4. Add the second pan to the oven and roast both 20 more minutes until the potatoes are fork-tender and the peppers are soft. | 5. Stir the mayonnaise, lemon zest and juice, basil and 1/2 teaspoon granulated garlic together and season with salt and pepper. | 6. Serve the sausage, peppers and potatoes in shallow bowls with the aioli drizzled over.', NULL);
