INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (441, 'Juicy Lucy Burger', 'One Dish Kitchen', 'https://onedishkitchen.com/juicy-lucy-recipe-for-one/', 40, 10, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 375°F and lightly grease a small baking dish. | 2. Mix the ground beef with the burger seasoning. | 3. Divide the beef in half and flatten each half into a thin patty. | 4. Cut the cheese into 4 squares and set them in the middle of one patty, leaving a 1/2-inch border. | 5. Top with the second patty and pinch the edges closed to seal in the cheese. | 6. Bake 30 minutes without pressing on the burger, then cover and rest 5 minutes. | 7. Serve on the bun with toppings.', NULL);
