INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (442, 'Pasta Carbonara for One', 'One Dish Kitchen', 'https://onedishkitchen.com/pasta-carbonara-recipe/', 20, 20, 0, 1, 1, 0, NULL, NULL, '1. Whisk the egg, 1 tablespoon Parmesan, salt and pepper in a small bowl and set aside. | 2. Cook the bacon in a medium skillet over medium heat until crisp and drain it on paper towels. | 3. Boil the spaghetti until al dente, 8 to 10 minutes, save 1/2 cup pasta water and drain. | 4. Cook the sliced garlic in the bacon fat about 1 minute, add the hot pasta and stir 30 seconds, then take the pan off the heat. | 5. Stir in a little pasta water to cool the pan, then slowly pour in the egg mixture while stirring until a smooth sauce forms. | 6. Loosen with more pasta water as needed, crumble in the bacon and serve with extra Parmesan and parsley.', NULL);
