INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (443, 'Bangers and Mash for One', 'One Dish Kitchen', 'https://onedishkitchen.com/bangers-mash-recipe/', 50, 40, 0, 1, 1, 0, NULL, NULL, '1. Simmer the quartered potatoes with the milk, cream, smashed garlic and coriander in a 2-quart saucepan 15 to 20 minutes until fork-tender. | 2. Drain over a bowl to save the cream, mash the potatoes and garlic with enough cream to be smooth, stir in the butter and olive oil, season and keep warm. | 3. Brown the sausage in the oil in a skillet 3 to 4 minutes per side until cooked through, then set aside covered. | 4. Lower the heat, cook the onion, garlic and a pinch of salt in the butter about 3 minutes, then stir in the flour for 1 minute. | 5. Slowly stir in the broth and simmer about 2 minutes until thick, then return the sausage to the skillet. | 6. Serve the sausage on the mash with the onion gravy over the top.', NULL);
