INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (450, 'Vegetarian Enchiladas for One', 'One Dish Kitchen', 'https://onedishkitchen.com/vegetarian-enchiladas-for-one/', 30, 25, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 350°F and warm the avocado oil in a 10-inch skillet over medium heat. | 2. Soften each tortilla in the oil 15 to 20 seconds and drain on paper towels. | 3. Cook the zucchini with the cumin, salt and pepper in the olive oil in an 8-inch skillet about 5 minutes until tender. | 4. Stir the zucchini together with the black beans and 1/4 cup of the salsa. | 5. Spread 2 tablespoons of salsa in a 5x5-inch baking dish and layer a tortilla, half the zucchini mixture and 2 tablespoons of cheese. | 6. Repeat with a second tortilla, the rest of the zucchini and 2 more tablespoons of cheese, then top with the last tortilla, remaining salsa and cheese. | 7. Cover and bake 15 minutes, uncover and bake 5 more minutes until the cheese melts.', NULL);
