INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (451, 'Cacio e Pepe', 'Budget Bytes', 'https://www.budgetbytes.com/cacio-e-pepe/', 20, 20, 0, 4, 4, 0, NULL, NULL, '1. Bring 6 cups of water and 3/4 teaspoon salt to a boil in a large skillet, add the spaghetti and cook 2 minutes less than the package says. | 2. Save 1 cup of the pasta water, drain the spaghetti into a bowl and keep it warm. | 3. Melt 2 tablespoons of the butter with the black pepper in the same skillet over medium heat until fragrant. | 4. Add 1/2 cup of the pasta water and stir until glossy. | 5. Lower the heat, add the spaghetti, Parmesan and remaining 2 tablespoons butter and toss quickly with tongs until creamy. | 6. Serve right away with extra pepper and Parmesan.', NULL);
