INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (452, 'Air Fryer Chicken Thighs', 'Budget Bytes', 'https://www.budgetbytes.com/air-fryer-chicken-thighs/', 25, 25, 0, 4, 4, 0, NULL, NULL, '1. Stir the corn starch, paprika, garlic powder, onion powder, oregano, cayenne, salt and pepper together in a small bowl. | 2. Heat the air fryer to 400°F and pat the chicken dry. | 3. Toss the chicken with the oil, then coat it evenly with the spice mix. | 4. Set the thighs skin side up in the basket and cook 10 minutes. | 5. Flip and cook 8 minutes, then flip skin side up and cook 2 more minutes. | 6. Check for 165°F inside, cooking 1 to 2 minutes longer if needed.', NULL);
