INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (454, 'One Pot Sausage and Sun Dried Tomato Pasta', 'Budget Bytes', 'https://www.budgetbytes.com/one-pot-sausage-sun-dried-tomato-pasta/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Brown the sausage in the olive oil over medium heat (slice links into medallions and brown both sides), move it to a bowl and pour off all but about 1 tablespoon of fat. | 2. Saute the garlic and frozen broccoli 3 to 5 minutes until the broccoli is bright green, then add it to the sausage bowl. | 3. Pour the broth into the skillet, scrape up the browned bits and add the sliced sun dried tomatoes, pasta and red pepper. | 4. Cover, bring to a boil, stir, then simmer covered about 7 minutes, stirring every couple of minutes, until the pasta is tender. | 5. Stir in the sausage and broccoli, top with the Parmesan and serve right away.', NULL);
