INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (455, 'One Pot Veggie Pasta', 'Budget Bytes', 'https://www.budgetbytes.com/one-pot-veggie-pasta/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Mince the garlic, dice the onion and slice the carrots, then saute them in the olive oil in a large pot over medium heat until the onion is soft. | 2. Slice the mushrooms and add them, then keep sauteing. | 3. Dice the zucchini and bell pepper and add them with the rotini, basil, oregano and vegetable broth. | 4. Cover, bring to a boil over medium-high, stir, then lower to medium-low and simmer about 10 minutes with the lid on until the pasta is tender. | 5. Stir in the pasta sauce and sprinkle the cheese on top, cover and heat a few minutes until melted.', NULL);
