INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (457, 'Apple-Glazed Chicken Thighs', 'Taste of Home', 'https://www.tasteofhome.com/recipes/apple-glazed-chicken-thighs/', 25, 25, 0, 6, 6, 0, NULL, NULL, '1. Season the chicken with the seasoned salt and pepper and brown it on both sides in the oil in a large skillet over medium-high heat, then take it out. | 2. Add the apple juice and thyme to the skillet, bring to a boil and scrape up the browned bits. | 3. Simmer until the liquid has reduced by half. | 4. Return the chicken, cover and cook over medium heat 3 to 4 minutes until it reads 170°F.', NULL);
