INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (458, 'Breaded Pork Tenderloin', 'Taste of Home', 'https://www.tasteofhome.com/recipes/breaded-pork-tenderloin/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Slice the pork crosswise into 1/2-inch pieces. | 2. Mix the flour, cornbread mix, salt and pepper in one shallow bowl and put the beaten egg in another. | 3. Dip each slice in the egg and press it into the flour mixture so the coating sticks. | 4. Heat 2 tablespoons of oil in a large skillet over medium heat and cook half the pork 3 to 4 minutes per side until it reads 145°F, then drain on paper towels. | 5. Wipe the skillet and repeat with the remaining oil and pork, and serve with ranch or barbecue sauce if you like.', NULL);
