INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (461, 'Caesar Chicken', 'Taste of Home', 'https://www.tasteofhome.com/recipes/caesar-chicken/', 50, 10, 1, 6, 6, 0, NULL, NULL, '1. Heat the oven to 350°F, pat the chicken dry and season it with the salt, pepper and garlic powder, then set it in a greased 13x9-inch baking dish. | 2. Mix the Caesar dressing with the sour cream and spread it over the chicken. | 3. Stir the crushed croutons, Parmesan and melted butter together and sprinkle over the top. | 4. Bake uncovered 45 to 55 minutes until the chicken reads 165°F. | 5. Sprinkle with parsley before serving.', NULL);
