INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (462, 'Pizza Chicken Roll-Ups', 'Taste of Home', 'https://www.tasteofhome.com/recipes/pizza-chicken-roll-ups/', 50, 15, 1, 4, 4, 0, NULL, NULL, '1. Heat the oven to 350°F and flatten each chicken breast to about 1/4 inch thick. | 2. Top each with 3 pepperoni slices and 1 slice of mozzarella, roll up tightly and fasten with toothpicks. | 3. Set the rolls in a greased 11x7-inch baking dish and spoon the pizza sauce over them. | 4. Cover and bake 35 to 40 minutes until the chicken is no longer pink. | 5. Uncover, add the remaining mozzarella and bake 5 more minutes until melted.', NULL);
