INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (463, 'Cheeseburger Pockets', 'Taste of Home', 'https://www.tasteofhome.com/recipes/cheeseburger-pockets/', 40, 40, 1, 5, 5, 0, NULL, NULL, '1. Heat the oven to 400°F and cook the beef with the onion, salt and pepper in a large skillet over medium heat until no pink remains, then drain and cool. | 2. On a floured surface, overlap 2 biscuits and roll them into a 5-inch oval. | 3. Spoon about 1/4 cup of the beef mixture onto one half, add a folded cheese slice, fold over the dough and seal the edge with a fork. | 4. Repeat with the remaining biscuits, beef and cheese. | 5. Set the pockets on a greased baking sheet, prick the tops with a fork and bake about 10 minutes until golden.', NULL);
