INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (464, 'Spicy Apricot-Glazed Chicken', 'Taste of Home', 'https://www.tasteofhome.com/recipes/spicy-apricot-glazed-chicken/', 20, 20, 0, 4, 4, 0, NULL, NULL, '1. Heat the broiler. | 2. Heat the apricot preserves, chili sauce, hot mustard, salt and pepper in a small saucepan over medium heat, stirring, until warm. | 3. Set the chicken in a 15x10x1-inch pan coated with cooking spray. | 4. Broil 3 to 4 inches from the heat 6 to 8 minutes per side until the chicken reads 165°F, brushing with the apricot mixture during the last 5 minutes.', NULL);
