INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (465, 'Spinach Pizza Quesadillas', 'Taste of Home', 'https://www.tasteofhome.com/recipes/spinach-pizza-quesadillas/', 20, 20, 0, 6, 6, 0, NULL, NULL, '1. Heat the oven to 400°F. | 2. On one half of each tortilla, spread about 2 tablespoons of pizza sauce and top with 1/2 cup cheese and 1/2 cup spinach. | 3. Fold each tortilla over the filling and set on baking sheets coated with cooking spray. | 4. Bake 10 to 12 minutes until the cheese melts and serve with extra pizza sauce if you like.', NULL);
