INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (466, 'Honey-Mustard Breaded Chicken', 'Taste of Home', 'https://www.tasteofhome.com/recipes/honey-mustard-breaded-chicken/', 20, 20, 0, 4, 4, 0, NULL, NULL, '1. Pound the chicken to about 1/4 inch thick. | 2. Mix the bread crumbs with 1 teaspoon of the mustard in a shallow bowl and the honey with the remaining 2 tablespoons mustard in another. | 3. Dip each piece of chicken in the honey mustard and coat it in the crumbs. | 4. Cook in the butter in a nonstick skillet over medium heat 4 to 6 minutes per side until the juices run clear.', NULL);
