INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (467, 'Poor Man''s Steak', 'Taste of Home', 'https://www.tasteofhome.com/recipes/old-fashioned-poor-man-s-steak/', 445, 35, 1, 9, 9, 0, NULL, NULL, '1. Combine the cracker crumbs, water, salt and pepper in a large bowl, crumble in the beef and mix lightly but thoroughly. | 2. Press the mixture into an ungreased 9-inch square pan, cover and refrigerate at least 3 hours. | 3. Cut the chilled mixture into 3-inch squares and dredge them in the flour. | 4. Brown the squares in the oil in a large skillet over medium heat 2 to 3 minutes per side. | 5. Move them to a 3-quart slow cooker with a slotted spatula and pour on the soup. | 6. Cover and cook on high about 4 hours until no pink remains, then serve over noodles or mashed potatoes.', NULL);
