INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (469, 'Slow Cooker Chicken Tostadas', 'Taste of Home', 'https://www.tasteofhome.com/recipes/shredded-chicken-tostadas/', 190, 10, 1, 8, 8, 0, NULL, NULL, '1. Put the chicken in a 3- or 4-quart slow cooker, sprinkle on the taco seasoning and top with the tomatoes and green chiles. | 2. Cover and cook on low 3 to 4 hours until the chicken reads 165°F. | 3. Shred the chicken with two forks, return it to the slow cooker, stir in the salt and heat through. | 4. Spoon the chicken onto the tostada shells and top with the cheese and any extra toppings.', NULL);
