INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (471, 'Italian Beef Sandwiches', 'Taste of Home', 'https://www.tasteofhome.com/recipes/family-favorite-italian-beef-sandwiches/', 490, 10, 1, 12, 12, 0, NULL, NULL, '1. Mix the pepperoncini with its liquid, the tomatoes with their liquid, the onion, water, dressing mix, oregano and garlic powder in a bowl. | 2. Set the roast in a 5- or 6-quart slow cooker and pour the mixture over it. | 3. Cover and cook on low 8 to 10 hours until tender. | 4. Lift out the roast, let it cool slightly, skim the fat from the juices and shred the beef with two forks. | 5. Return the beef to the slow cooker with the juices, heat through and serve on split rolls.', NULL);
