INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (473, 'Slow Cooker Teriyaki Chicken Thighs', 'Taste of Home', 'https://www.tasteofhome.com/recipes/teriyaki-chicken-thighs/', 255, 15, 1, 8, 8, 0, NULL, NULL, '1. Put the chicken in a 4- or 5-quart slow cooker. | 2. Stir the sugar, soy sauce, vinegar, garlic, ginger and pepper together in a small bowl and pour over the chicken. | 3. Cover and cook on low 4 to 5 hours until tender. | 4. Move the chicken to a platter and keep warm, then pour the juices into a small saucepan, skim off the fat and bring to a boil. | 5. Stir the cornstarch and cold water until smooth, whisk into the boiling juices and cook 1 to 2 minutes until thick. | 6. Serve the sauce over the chicken, with rice if you like.', NULL);
