INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (474, 'Slow Cooker Beef Stew', 'Taste of Home', 'https://www.tasteofhome.com/recipes/slow-cooker-beef-stew/', 445, 25, 1, 8, 8, 0, NULL, NULL, '1. Layer the potatoes, carrots, onion and celery in a 5-quart slow cooker. | 2. Toss the stew meat with the flour in a shallow dish and brown it in the oil in batches in a large skillet, then lay it over the vegetables. | 3. Mix the tomatoes, broth, mustard, salt, pepper, thyme and browning sauce if using, and pour over the beef. | 4. Cover and cook on low 7 to 8 hours until the meat and vegetables are tender. | 5. Top with fresh thyme if you like.', NULL);
