INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (475, 'Shredded Beef au Jus', 'Taste of Home', 'https://www.tasteofhome.com/recipes/shredded-beef-au-jus/', 370, 10, 1, 8, 8, 0, NULL, NULL, '1. Cut the roast in half and set it in a 4- or 5-quart slow cooker. | 2. Mix the water, bouillon, oregano, garlic salt, seasoned salt and rosemary and pour over the meat. | 3. Cover and cook on low 6 to 8 hours until tender. | 4. Lift out the beef, let it cool slightly and skim the fat from the juices. | 5. Shred the beef with two forks and return it to the cooker, then pile it on the bottoms of the buns with a slotted spoon. | 6. Serve with extra cooking liquid on the side for dipping.', NULL);
