INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (486, 'Chicken Tetrazzini for One', 'One Dish Kitchen', 'https://onedishkitchen.com/chicken-tetrazzini-recipe/', 30, 30, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 375°F and warm half the olive oil in a 10-inch skillet over medium-high heat. | 2. Season the chicken with 1/8 teaspoon of the salt and the pepper and brown it 1 to 2 minutes per side, then set aside. | 3. Add the rest of the oil, lower the heat and cook the onions about 2 minutes, then the garlic 30 seconds. | 4. Turn the heat up, add the mushrooms and cook about 2 minutes, then pour in the broth. | 5. Off the heat, stir in the sour cream, heavy cream, cheddar, mozzarella, remaining salt and Italian seasoning. | 6. Add the chicken and cooked spaghetti and toss, then move to a greased 5x5-inch dish on a rimmed baking sheet. | 7. Cover with foil and bake 25 minutes, then uncover and top with Parmesan and parsley if you like.', NULL);
