INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (487, 'Chicken Pot Pie for One', 'One Dish Kitchen', 'https://onedishkitchen.com/chicken-pot-pie-for-one/', 40, 30, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 400°F and melt half the butter in a 10-inch skillet over medium heat. | 2. Season the chicken with 1/8 teaspoon each salt and pepper and cook about 4 minutes per side until done, then set aside covered. | 3. Add the rest of the butter, the onions, garlic, basil and remaining salt and pepper to the skillet and cook about 3 minutes. | 4. Stir in the flour and cook 2 minutes, then pour in the broth and simmer 3 minutes. | 5. Add the peas and carrots and simmer 3 more minutes. | 6. Chop the chicken, stir it into the sauce and spoon into a ramekin or small oven-safe skillet. | 7. Lay the puff pastry over the top, cut two small slits and bake 12 to 15 minutes until golden, then let cool slightly.', NULL);
