INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (488, 'Taco Casserole for One', 'One Dish Kitchen', 'https://onedishkitchen.com/taco-casserole-for-one/', 40, 40, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 350°F and warm the oil in a small pan over medium-high heat, then cook the onions 2 minutes and the garlic 1 minute. | 2. Add the beef and cook 5 to 6 minutes until browned and cooked through. | 3. Stir in the salsa, water and taco seasoning, lower the heat and simmer 4 minutes until slightly thick. | 4. Lightly spray a small baking dish and layer a tostada, half the beef and 1/2 cup cheese. | 5. Add a second tostada, the remaining beef and 1/4 cup cheese, then the last tostada and the final 1/4 cup cheese. | 6. Bake 25 minutes until the cheese is melted and serve with toppings if you like.', NULL);
