INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (496, 'Air Fryer Pork Chop', 'One Dish Kitchen', 'https://onedishkitchen.com/air-fryer-pork-chop/', 25, 15, 0, 1, 1, 0, NULL, NULL, '1. Heat the air fryer to 390°F for 5 minutes. | 2. Mix the garlic powder, onion powder, paprika, salt and pepper in a small bowl. | 3. Pat the pork chop dry, rub the oil over it and press the spice mix into the meat. | 4. Air fry 10 minutes, flipping halfway, until a thermometer reads 140°F. | 5. Cover with foil and rest 10 minutes so it climbs to at least 145°F, then slice.', NULL);
