INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (497, 'Mini French Toast Casserole', 'One Dish Kitchen', 'https://onedishkitchen.com/croissant-breakfast-bread-pudding-for-one/', 50, 20, 0, 1, 1, 0, NULL, NULL, '1. Heat the oven to 350°F, grease a 5-inch square baking dish and spread the cubed croissants in it. | 2. Whisk the milk, egg, cream, brown sugar, maple syrup and vanilla together and pour over the bread. | 3. Mix the sugar and cinnamon and sprinkle it over the top, then scatter on the apples and pecans. | 4. Dot with the butter and set the dish in a larger roasting pan, pouring boiling water halfway up its sides. | 5. Bake about 30 minutes until golden and set, then cool 5 minutes on a rack.', NULL);
