INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (510, 'Baked Cheddar Eggs and Potatoes', 'Taste of Home', 'https://www.tasteofhome.com/recipes/baked-cheddar-eggs---potatoes/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Heat the oven to 400°F and melt the butter in a 10-inch ovenproof skillet over medium-high heat. | 2. Cook the potatoes until golden and tender, then stir in the parsley, garlic, salt and pepper. | 3. Make four wells in the potatoes and crack two eggs into each. | 4. Bake 9 to 11 minutes until the whites are set and the yolks are thick but still soft. | 5. Top with the cheese and bake about 1 minute more until melted.', NULL);
