INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (511, 'Beef Taco Pasta Skillet', 'Spend With Pennies', 'https://www.spendwithpennies.com/beef-taco-pasta-skillet/', 30, 30, 0, 6, 6, 0, NULL, NULL, '1. Brown the beef with the onion and garlic for 5 to 6 minutes until no pink remains, then drain the fat. | 2. Stir in the taco seasoning, green pepper, 2 cups of the water, salsa, tomato sauce and macaroni. | 3. Cover and simmer over medium-low heat about 20 minutes, stirring now and then, until the pasta is tender, adding the rest of the water if the pan gets dry. | 4. Take off the heat and stir in the cheddar.', NULL);
