INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (521, 'Creamy Jerk Shrimp Pasta for One', 'Nourish Nutrition Blog', 'https://www.nourishnutritionblog.com/jerk-shrimp-pasta/', 12, 12, 0, 1, 1, 0, NULL, NULL, '1. Cook the pasta until al dente, keep 1 tablespoon of the pasta water, then drain. | 2. Toss the shrimp with half the jerk seasoning and thinly slice the bell pepper. | 3. Cook the shrimp in a hot skillet 1 to 3 minutes per side until pink, then set aside. | 4. In the same skillet cook the pepper with the rest of the oil and jerk seasoning until soft. | 5. Lower the heat and add the pasta, shrimp, pasta water, cream, Parmesan, spinach and a pinch of salt, stirring until the sauce thickens and the spinach wilts.', NULL);
