INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (526, 'Garlic Shrimp and Orzo Skillet', 'Budget Bytes', 'https://www.budgetbytes.com/garlic-shrimp-and-orzo-skillet/', 35, 35, 0, 4, 4, 0, NULL, NULL, '1. Slice the lemon, mince the garlic, dice the onion and chop the sun-dried tomatoes, and thaw the shrimp. | 2. Melt the butter in a large skillet over medium-high heat and cook the onion 4 to 6 minutes until soft. | 3. Pat the shrimp dry, toss with the chili flakes, salt, pepper and paprika, and cook in the oil 2 to 3 minutes per side until pink; set aside. | 4. Toast the orzo, garlic and sun-dried tomatoes in the skillet for a few minutes. | 5. Pour in the broth, add the lemon wheels and simmer on medium-low 8 to 10 minutes until the orzo is tender. | 6. Stir in the spinach, return the shrimp and warm through 1 to 2 minutes.', NULL);
