INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (527, 'Summer Vegetable Pasta Salad', 'Budget Bytes', 'https://www.budgetbytes.com/summer-vegetable-pasta-salad/', 35, 35, 0, 10, 10, 0, NULL, NULL, '1. Whisk the oil, red wine vinegar, Dijon, oregano, garlic, salt and pepper together and set aside. | 2. Cook the pasta to the package directions, drain, rinse briefly to cool and drain well. | 3. Chop the tomatoes, squash, zucchini, broccoli and parsley and slice the roasted peppers and red onion. | 4. Combine the pasta and vegetables in a large bowl. | 5. Whisk the dressing again, pour it over, stir to coat and adjust the seasoning, then serve or chill.', NULL);
