INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (528, 'Broccoli Pasta Salad with Tomato Vinaigrette', 'Budget Bytes', 'https://www.budgetbytes.com/broccoli-pasta-salad-with-tomato-vinaigrette/', 25, 25, 0, 4, 4, 0, NULL, NULL, '1. Whisk the tomato paste, vinegar, basil, garlic powder, sugar, salt and pepper until smooth, then whisk in the oil a tablespoon at a time. | 2. Cook the rotini 7 to 10 minutes until tender, then drain, rinse briefly and drain well. | 3. Cut the broccoli into small pieces and finely dice the onion. | 4. Put the cooled pasta in a large bowl with the broccoli, onion and sunflower seeds and crumble the feta on top. | 5. Pour on the dressing and toss to coat.', NULL);
