INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (529, 'Tomato Mozzarella Pasta Salad', 'Budget Bytes', 'https://www.budgetbytes.com/tomato-mozzarella-pasta-salad/', 25, 25, 0, 6, 6, 0, NULL, NULL, '1. Boil the pasta in salted water until tender, then drain, rinse briefly and let it drain well. | 2. Blend or shake all the dressing ingredients in a jar until combined. | 3. Chop the spinach, halve the tomatoes and cube the mozzarella into half-inch pieces. | 4. Put the spinach, tomatoes and mozzarella in a large bowl and add the cooled pasta. | 5. Toss with about half the dressing and add more to taste, or store the salad undressed to serve later.', NULL);
