INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (530, 'Shrimp Alfredo Pasta', 'Budget Bytes', 'https://www.budgetbytes.com/shrimp-alfredo-pasta/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Thaw and peel the shrimp, then boil the fettuccine 7 to 10 minutes, keep half a cup of pasta water and drain. | 2. Pat the shrimp dry, season lightly and cook in 1 tablespoon of the butter 1 to 2 minutes per side until pink; move to a bowl with any juices. | 3. Lower the heat, add the rest of the butter and the garlic and cook 1 to 2 minutes without browning. | 4. Pour in the cream, scrape up the browned bits and bring to a simmer, then whisk in the Parmesan until smooth. | 5. Add the pasta, shrimp and juices, toss, loosen with pasta water if needed, and garnish with parsley.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (530, 1, NULL, 'shrimp', 0.5, 0.5, 'lb', 'peeled and deveined', NULL, 0, '½ lb. frozen shrimp (or fresh medium shrimp, 36/40, peeled and deveined)');
