INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (531, 'Pesto Shrimp Pasta', 'Budget Bytes', 'https://www.budgetbytes.com/pesto-shrimp-pasta/', 25, 25, 0, 4, 4, 0, NULL, NULL, '1. Thaw frozen shrimp under cool running water, peel, remove the tails and pat dry. | 2. Cook the pasta about 7 minutes in boiling water, keep half a cup of the pasta water and drain. | 3. Saute the shrimp in 1 tablespoon of the oil for 2 to 3 minutes until pink, then move them to a bowl. | 4. Add the rest of the oil, the tomatoes and garlic to the skillet and cook over medium heat until the tomatoes burst, adding a little water if the garlic browns. | 5. Add the pasta, pesto and half the pasta water, toss, return the shrimp and top with Parmesan.', NULL);
