INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (532, 'Chicken Broccoli Casserole', 'Budget Bytes', 'https://www.budgetbytes.com/chicken-broccoli-casserole/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Thaw the broccoli slightly, chop large florets and cut the chicken into 1-inch pieces. | 2. Toss the chicken with 1 teaspoon of the salt, the pepper, garlic powder, onion powder and paprika. | 3. Melt the butter with the oil in a broiler-safe skillet and brown the chicken 12 to 15 minutes until cooked through. | 4. Stir in the orzo for 2 minutes, then pour in the broth and lower the heat. | 5. Stir in the milk, add the broccoli and simmer about 8 minutes until the orzo is tender. | 6. Stir in half the cheddar, top with the rest and the remaining salt, and broil 3 to 5 minutes until golden; rest 5 minutes.', NULL);
