INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (533, 'Garlic Butter Baked Cod', 'Budget Bytes', 'https://www.budgetbytes.com/garlic-butter-baked-cod/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Heat the oven to 400°F. | 2. Mix the butter, olive oil, garlic, paprika, salt and parsley in a small bowl until fairly smooth. | 3. Set the cod in a baking dish and spread the garlic butter over each fillet. | 4. Slice half the lemon over the fish and cut the other half into wedges. | 5. Bake 15 to 20 minutes until the fish flakes and reaches 145°F, then spoon the pan juices over and serve with the wedges.', NULL);
