INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (534, 'Air Fryer Pork Chops', 'Budget Bytes', 'https://www.budgetbytes.com/air-fryer-pork-chops/', 30, 30, 0, 2, 2, 0, NULL, NULL, '1. Preheat the air fryer to 420°F for at least 5 minutes. | 2. Mix the paprika, garlic powder, onion powder, mustard, brown sugar, salt and pepper in a small bowl. | 3. Pat the chops dry, brush both sides with the oil and rub on the seasoning, saving at least 1 tablespoon. | 4. Air fry 7 minutes, flip, sprinkle with the saved seasoning and cook 8 minutes more. | 5. Check for 145°F inside, adding 1 to 2 minutes if needed, then rest 3 minutes.', NULL);
