INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (536, 'Chicken Burger', 'Budget Bytes', 'https://www.budgetbytes.com/chicken-burger/', 20, 20, 0, 4, 4, 0, NULL, NULL, '1. Heat a grill or grill pan to medium (about 400°F). | 2. Saute the minced onion in the oil for 2 to 3 minutes until soft and take it off the heat. | 3. Mix the chicken, cooked onion, panko, mayonnaise, parsley, Worcestershire, salt, garlic powder and pepper just until combined. | 4. Shape four patties of about 4 oz each with a shallow thumbprint in the center. | 5. Toast the buns cut side down for 1 to 2 minutes, then grill the patties 4 to 5 minutes per side to 165°F. | 6. Rest briefly and serve on the buns with your toppings.', NULL);
