INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (537, 'Philly Cheesesteak', 'Budget Bytes', 'https://www.budgetbytes.com/philly-cheesesteak-recipe/', 30, 30, 0, 5, 5, 0, 5.0, 'sandwich', '1. Slice the pepper, onion and mushrooms. | 2. Heat 1 tablespoon each of butter and oil in a large skillet over medium heat and cook the mushrooms 2 to 3 minutes. | 3. Add the onion and pepper and cook about 3 minutes until softened, then move the vegetables to a plate. | 4. Melt another tablespoon each of butter and oil in the skillet and brown the shaved steak. | 5. Return the vegetables with the salt, garlic powder, pepper and Worcestershire and cook 1 to 2 minutes, then lay the provolone on top and turn off the heat to melt it. | 6. Heat the oven to 350°F, spread the remaining softened butter inside the split rolls and toast them until golden. | 7. Divide the filling among the rolls and serve hot.', NULL);
