INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (538, 'Muffaletta Roll-Ups', 'Budget Bytes', 'https://www.budgetbytes.com/muffaletta-roll-ups/', 35, 35, 0, 7, 7, 0, NULL, NULL, '1. Pulse the olives, giardiniera, Italian herbs and garlic in a food processor until chunky. | 2. Heat the oven to 400°F and roll the pizza dough out thinly on parchment to about 10 x 14 inches. | 3. Layer on the provolone, leaving a border, then the salami and ham. | 4. Spread the olive salad over the meat, draining off as much liquid as you can, and add the mozzarella. | 5. Roll up from a short end into a log, pinch the seam shut, brush with beaten egg, cut three vent slits and sprinkle with sesame seeds. | 6. Bake 20 to 25 minutes until golden, cool 5 to 10 minutes and slice into 2-inch portions.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (538, 1, 'muffaletta salad', 'green olive', 0.5, 0.5, 'cup', NULL, NULL, 0, '½ cup green olives');
