INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (539, 'Crispy Baked Honey Sriracha Chicken Drumsticks', 'Budget Bytes', 'https://www.budgetbytes.com/crispy-baked-honey-sriracha-chicken-drumsticks/', 55, 15, 0, 6, 6, 0, NULL, NULL, '1. Heat the oven to 400°F, line a baking sheet with foil and set wire racks on top. | 2. Toss the drumsticks with a pinch of salt and pepper, then coat them with the cornstarch. | 3. Arrange the drumsticks on the racks and bake about 50 minutes until golden and crispy. | 4. Warm the sriracha, butter and honey together in a small saucepan over low heat for about 5 minutes until smooth. | 5. Brush the sauce generously over the finished drumsticks.', NULL);
