INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (540, 'Everything Bagel Rice Bowl', 'Budget Bytes', 'https://www.budgetbytes.com/everything-bagel-rice-bowl/', 35, 25, 0, 2, 2, 0, NULL, NULL, '1. Bring the water to a boil in a covered pot, add the rinsed rice, 1/4 tsp of the salt and 2 tablespoons of butter, and stir. | 2. Simmer uncovered about 3 minutes until steam vents form, then cover tightly, lower the heat and cook 15 minutes; rest off the heat 10 minutes. | 3. Brown 2 tablespoons of butter in a pan, add the onion and cook about 3 minutes, then add the garlic for 1 minute. | 4. Add the spinach and remaining salt and saute about 3 minutes until wilted. | 5. Make two wells in the spinach, slide in the eggs and cook uncovered about 3 minutes until the whites are set. | 6. Fluff the rice and mix in the last tablespoon of diced butter and the seasoning, then top with the spinach and eggs.', NULL);
