INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (541, 'Blistered Green Bean Rice Bowl', 'Budget Bytes', 'https://www.budgetbytes.com/blistered-green-bean-rice-bowl/', 30, 25, 0, 2, 2, 0, NULL, NULL, '1. Bring the water to a boil, add the rice and butter, and when steam vents form cover and cook on medium-low for 15 minutes without lifting the lid. | 2. Meanwhile simmer the eggs in an inch of water for 6 minutes, then move them to cold water. | 3. Heat the oil in a large skillet, add the green beans with the salt and pepper and let them brown undisturbed 4 to 5 minutes. | 4. Rest the rice covered for 10 minutes, then fluff. | 5. Divide the rice between two bowls and top with the beans, chili crisp and a halved peeled egg.', NULL);
