INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (542, 'Pork and Cherry Rice Bowls', 'Budget Bytes', 'https://www.budgetbytes.com/pork-and-cherry-rice-bowl/', 35, 30, 0, 4, 4, 0, NULL, NULL, '1. Melt 2 tablespoons of butter in a heavy pot, toast the rice until fragrant, then add the boiling water and half of the first measure of salt. | 2. Cover and cook 15 minutes once it boils, then rest with the lid on for 10 minutes. | 3. Meanwhile melt 1 tablespoon of butter in a skillet, soften the onion about 2 minutes and add the garlic for 30 seconds. | 4. Brown the sausage about 5 minutes, stir in the parsley, then remove the pork and keep the drippings. | 5. Pour the wine into the pan and scrape up the browned bits, add the quartered cherries and simmer about 5 minutes into a thin syrup. | 6. Off the heat stir in the rest of the salt, red pepper, black pepper and lemon juice, then melt in the last tablespoon of butter. | 7. Fluff the rice, divide among four bowls, top with the pork and cherry sauce and garnish with parsley.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (542, 1, NULL, 'butter', 4.0, 4.0, 'tbsp', NULL, NULL, 0, '4 Tbsp salted butter, divided');
