INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (545, 'Crockpot White Chicken Chili', 'Budget Bytes', 'https://www.budgetbytes.com/slow-cooker-white-chicken-chili/', 255, 15, 0, 6, 6, 0, NULL, NULL, '1. Dice the onion, mince the garlic and seed and dice the jalapeno if using, then add them to the slow cooker with the chicken breast. | 2. Add the drained beans, cumin, oregano, cayenne and black pepper and pour the salsa verde on top. | 3. Pour in the broth, stir briefly, cover and cook on high 4 hours or low 8 hours until the chicken reaches 165°F. | 4. Shred the chicken and return it to the pot, then mash some beans against the side of the pot to thicken. | 5. Serve with any toppings you like.', NULL);
