INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (553, 'Brothy Rice Bowls', 'Spend With Pennies', 'https://www.spendwithpennies.com/brothy-rice-bowls/', 35, 35, 0, 4, 4, 0, NULL, NULL, '1. Stir 2 tablespoons of the oil, lime juice, brown sugar, garlic and salt together, coat the chicken and marinate 10 minutes to 4 hours. | 2. Slice the green onions, keeping whites and greens apart. | 3. Cook the chicken in the remaining tablespoon of oil over medium heat 7 to 9 minutes, turning, until browned and 165°F inside, then cover to keep warm. | 4. Boil the broth with the garlic, ginger, soy sauce, sesame oil and green onion whites. | 5. Whisk the cornstarch with a tablespoon of water, stir it in and cook at a gentle boil 10 minutes. | 6. Slice the chicken, ladle the broth over the rice and top with the chicken, onion greens, and any garnishes you like.', NULL);
