INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (554, 'Crock Pot Chicken and Dumplings', 'Spend With Pennies', 'https://www.spendwithpennies.com/crock-pot-chicken-and-dumplings/', 320, 20, 0, 4, 4, 0, NULL, NULL, '1. Put the diced onion in a 6-quart slow cooker and lay the chicken breasts on top. | 2. Mix the two soups with the parsley, poultry seasoning and pepper, spread over the chicken and pour the broth on top. | 3. Cover and cook on high 5 hours. | 4. About an hour before serving, roll each biscuit thin and cut it into 4 strips. | 5. Stir in the thawed vegetables, lay the biscuit strips on top, cover and cook about 60 minutes until the dumplings are done. | 6. Shred the chicken, return it to the pot, stir and cook 10 more minutes.', NULL);
