INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (555, 'Greek Chicken Bowls', 'Spend With Pennies', 'https://www.spendwithpennies.com/greek-chicken-bowls/', 80, 40, 1, 4, 4, 0, NULL, NULL, '1. Slice thick chicken breasts in half horizontally into cutlets. | 2. Whisk 3 tablespoons of the oil, 2 tablespoons lemon juice, the garlic, half the oregano, the dill, half the salt and the pepper, coat the chicken and chill 30 minutes to 3 hours. | 3. Melt the butter in a saucepan and brown the rice about 5 minutes. | 4. Add the broth, remaining lemon juice, oregano and salt, bring to a boil, cover and simmer 15 to 20 minutes, then stand covered 5 minutes and fluff. | 5. Cook the chicken in the last tablespoon of oil 2 to 3 minutes per side to 165°F, rest 5 minutes and slice. | 6. Divide the rice among bowls and top with the chicken, tzatziki and any toppings.', NULL);
