INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (556, 'Easy Crockpot Chili', 'Spend With Pennies', 'https://www.spendwithpennies.com/easy-crock-pot-chili-recipe/', 255, 30, 0, 10, 10, 0, NULL, NULL, '1. Stir the seasoning ingredients together in a small bowl. | 2. Mix half of the seasoning into the ground beef. | 3. Brown the beef with the onions and garlic until no pink remains, drain, add the beer and simmer until most of the liquid has cooked off. | 4. Move the beef mixture to a slow cooker and add the kidney beans, both cans of tomatoes, tomato sauce, green pepper and the rest of the seasoning. | 5. Cook on high 4 hours or low 7 to 8 hours and let cool slightly before serving.', NULL);
