INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (574, 'Mediterranean Turkey Burgers', 'Budget Bytes', 'https://www.budgetbytes.com/greek-turkey-burgers/', 45, 45, 0, 5, 5, 0, 5.0, 'burger', '1. Stir the yogurt, lemon juice, garlic powder, dill and salt together for the sauce and refrigerate it. | 2. Chop the sun-dried tomatoes, mince the onion, crumble the feta and squeeze the thawed spinach dry. | 3. Mix the turkey with the tomatoes, onion, feta, spinach, oregano, garlic powder and salt. | 4. Shape five wide, flat patties. | 5. Cook three patties in half the oil over medium heat 5 to 7 minutes per side, then repeat with the rest. | 6. Serve on buns with the sauce, cucumber and red onion.', NULL);
