INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (575, 'Baked Spicy Chicken Sandwiches', 'Budget Bytes', 'https://www.budgetbytes.com/baked-spicy-chicken-sandwiches/', 40, 40, 0, 2, 2, 0, 2.0, 'sandwich', '1. Heat the oven to 425°F and set a wire rack over a baking sheet. | 2. Mix the breadcrumbs, garlic powder, paprika, cayenne, 1/8 tsp salt and pepper with the oil until it looks like damp sand. | 3. Stir the yogurt, 1/8 tsp salt and hot sauce together in a shallow dish. | 4. Pound the chicken to no more than 3/4 inch thick, halve it and season with a pinch of salt and cayenne. | 5. Dip each piece in the yogurt, coat in the crumbs and set on the rack. | 6. Bake about 25 minutes, flipping once, until it reaches 165°F. | 7. Whisk the mayonnaise, yogurt, honey, Dijon, vinegar, salt and pepper, toss through the slaw mix, and pile onto the chicken in the buns.', NULL);
