INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (576, 'Chicken Salad with Apples', 'Budget Bytes', 'https://www.budgetbytes.com/chicken-n-apple-salad/', 15, 15, 0, 4, 4, 0, NULL, NULL, '1. Cook raw chicken breasts in a skillet with a little oil until golden and 165°F, then cool 5 to 10 minutes, or start with rotisserie chicken. | 2. Chop the chicken and apple small and finely dice the onion. | 3. Put the chicken, apple, onion and cranberries in a large bowl. | 4. Whisk the mayonnaise, yogurt, Dijon, vinegar, salt and pepper together, pour over the salad and stir to coat. | 5. Serve now or chill.', NULL);
