INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (577, '1-Pot Kale Sweet Potato Curry', 'Minimalist Baker', 'https://minimalistbaker.com/kale-sweet-potato-curry/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Heat the oil in a large pot over medium heat and saute the shallot, ginger, garlic and chili 2 to 3 minutes. | 2. Stir in the curry paste and sweet potato and cook 2 more minutes. | 3. Add the coconut milk, maple syrup, turmeric and a pinch of salt and bring to a simmer. | 4. Add the peas if using, lower the heat and simmer gently 5 to 10 minutes until the potato is soft. | 5. Taste and adjust the sweetness, salt and curry paste. | 6. Add the kale, cashews and lemon juice, cover and simmer 3 to 4 minutes, then serve over rice or quinoa.', NULL);
