INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (578, '5-Ingredient Sweet Potato Black Bean Chili', 'Minimalist Baker', 'https://minimalistbaker.com/5-ingredient-sweet-potato-black-bean-chili/', 55, 20, 0, 6, 6, 0, NULL, NULL, '1. Warm the oil in a large pot over medium heat and cook the onion with a pinch of salt and pepper until soft. | 2. Add the sweet potatoes and any spices and cook about 3 minutes. | 3. Stir in the salsa, water and vegetable stock and bring to a low boil, then reduce to a simmer. | 4. Add the black beans, cover and cook at least 20 minutes, ideally 30, until the sweet potato is fork-tender and the chili thickens. | 5. Serve with your choice of toppings.', NULL);
