INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (585, 'Mustard Pork Chops', 'Taste of Home', 'https://www.tasteofhome.com/recipes/dijon-pork-chops/', 30, 30, 0, 6, 6, 0, NULL, NULL, '1. Heat the oven to 375°F, season the chops with salt and spread the mustard over the tops and sides. | 2. Set them on a greased baking sheet. | 3. Mix the bread crumbs with pepper and press onto the tops and sides of the chops, misting with cooking spray for better browning if you like. | 4. Bake 20 to 25 minutes until lightly browned and 145°F inside, then rest 5 minutes.', NULL);
