INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (586, 'Baked Balsamic Chicken', 'Taste of Home', 'https://www.tasteofhome.com/recipes/balsamic-roast-chicken/', 155, 20, 1, 12, 12, 0, NULL, NULL, '1. Heat the oven to 350° and mix the rosemary, garlic, salt and pepper. | 2. Spread the onions in a roasting pan and set the chicken on top, breast up. | 3. Pat the chicken dry, loosen the skin, rub the herb mixture underneath, secure the skin with toothpicks and tuck the wings under. | 4. Mix the wine and vinegar and pour over the chicken, then roast 2 to 2-1/2 hours until the thigh reads 170° to 175°, tenting with foil if it browns too fast. | 5. Rest 15 minutes under foil, skim the fat from the onions and drippings, and serve the chicken with the onion sauce.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (586, 1, NULL, 'rosemary', 2.0, 2.0, 'tbsp', 'minced', NULL, 0, '2 tablespoons minced fresh rosemary, or 2 teaspoons dried rosemary, crushed');
