INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (588, 'No-Fold Blanket Dumplings', 'Spend With Pennies', 'https://www.spendwithpennies.com/blanket-dumplings/', 25, 25, 0, 6, 6, 0, NULL, NULL, '1. Mix the filling ingredients together in a medium bowl. | 2. Set about 1 heaping tablespoon of filling per dumpling on a plate, lay a wrapper over each mound and press it gently around the top and sides, leaving the bottom open. | 3. Heat the oil in a large nonstick skillet, add the dumplings with space between them, pour the water around them, cover and steam 6 to 8 minutes until the pork reaches 145°F. | 4. Uncover and cook until the water evaporates and the bottoms crisp, then garnish with green onion and serve hot with dumpling sauce.', NULL);
