INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (590, 'Southwest Tofu Scramble', 'Minimalist Baker', 'https://minimalistbaker.com/southwest-tofu-scramble/', 30, 30, 0, 2, 2, 0, NULL, NULL, '1. Press the tofu dry in a clean towel under something heavy for about 15 minutes. | 2. Stir the dry sauce spices with enough water to make a pourable sauce. | 3. Soften the onion and red pepper in the oil with a pinch of salt and pepper about 5 minutes. | 4. Add the kale, season, and cover to steam 2 minutes. | 5. Crumble the tofu, push the vegetables aside and saute the tofu 2 minutes, then pour the sauce over and stir right away. | 6. Cook 5 to 7 minutes more until lightly browned and serve at once.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (590, 1, 'scramble', 'tofu', 8.0, 8.0, 'oz', NULL, NULL, 0, '8 ounces extra-firm tofu');
