INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (591, 'Weeknight Lemon Chicken Breasts', 'Damn Delicious', 'https://damndelicious.net/2022/08/05/weeknight-lemon-chicken-breasts/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Pat the chicken dry and season both sides with salt and pepper. | 2. Sear the chicken in the oil in batches over medium heat 4 to 5 minutes per side until golden. | 3. Lower the heat, flip the chicken, cover and cook about 8 minutes more to 165°F, then set it aside warm. | 4. Melt 1 tablespoon of the butter in the skillet and cook the garlic, shallot and rosemary about 2 minutes. | 5. Whisk in the flour for a minute, then stir in the stock, scraping up the browned bits, bring to a boil and simmer 4 to 5 minutes until thickened. | 6. Stir in the lemon juice and remaining butter, adjust the seasoning and return the chicken to the pan.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (591, 1, NULL, 'chicken breast', 1.5, 1.5, 'lb', 'small, boneless, skinless', NULL, 0, '4 small boneless skinless chicken breasts, about 1 1/2 pounds');
