INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (593, 'Greek Chicken Meal Prep Bowls', 'Damn Delicious', 'https://damndelicious.net/2016/11/16/greek-chicken-meal-prep-bowls/', 75, 40, 1, 5, 5, 1, NULL, NULL, '1. Marinate the chicken in a zip-top bag with 1/4 cup of the oil, garlic, lemon juice, vinegar, oregano, salt and pepper for 20 minutes to 1 hour, then drain. | 2. Cook the chicken in 2 tablespoons of oil about 3 to 4 minutes per side, cool and dice it. | 3. Toss the sliced cucumbers, red onion, lemon juice, oil, vinegar, garlic and oregano for the salad. | 4. Stir the yogurt, diced cucumber, garlic, dill, lemon juice, zest and mint into a tzatziki, season, drizzle with oil and chill at least 10 minutes. | 5. Cook the brown rice in 2 cups of water to the package directions. | 6. Divide the rice among containers and top with the chicken, cucumber salad, cherry tomatoes and tzatziki.', NULL);
