INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (594, 'Creamy Chicken and Orzo Skillet', 'Budget Bytes', 'https://www.budgetbytes.com/creamy-chicken-and-orzo-skillet/', 45, 45, 0, 4, 4, 0, NULL, NULL, '1. Mix the paprika, oregano, thyme, garlic powder, onion powder, salt and pepper and rub it over the dried chicken thighs. | 2. Brown the chicken in the oil in a large deep skillet about 5 minutes per side and set aside. | 3. On low heat cook the onion and garlic in the same skillet about 3 minutes. | 4. Stir in the orzo and broth, scraping up the browned bits, and nestle the chicken back in. | 5. Cover, bring to a boil, then simmer on low about 15 minutes until the orzo is tender. | 6. Take out the chicken, stir the cream and butter in over low heat, then the Parmesan, and return the chicken to the pan.', NULL);
