INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (595, 'Creamy Salsa Chicken Skillet', 'Budget Bytes', 'https://www.budgetbytes.com/creamy-salsa-chicken-skillet/', 30, 30, 0, 4, 4, 0, NULL, NULL, '1. Pat the chicken dry, pound it to about 1/2 inch thick and rub with the chili powder, cumin, garlic powder and salt. | 2. Cook the chicken in the oil in a large deep skillet about 5 minutes per side, then rest it on a board. | 3. On medium-low heat stir the salsa into the skillet, scraping up the browned bits, and add the rinsed black beans and corn. | 4. Warm the sour cream with a few spoonfuls of the hot salsa mixture, then stir it into the skillet off the heat. | 5. Slice the chicken, add it to the skillet, top with the cheese and cilantro and serve over rice.', NULL);
