INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (596, 'Monterey Chicken Skillet', 'Budget Bytes', 'https://www.budgetbytes.com/monterey-chicken-skillet/', 25, 25, 0, 4, 4, 0, NULL, NULL, '1. Stir the chicken, dry pasta, undrained Rotel and broth together in a large skillet. | 2. Cover, bring to a boil on high, then reduce to low and simmer 15 minutes, stirring every 5 minutes. | 3. Meanwhile cook the bacon until crisp, drain and crumble it. | 4. Check the pasta, simmering 5 more minutes covered if it is firm or uncovered if it is tender but soupy. | 5. Drizzle the barbecue sauce over the top, add the cheese, cover on low about 5 minutes until melted, then top with bacon and green onions.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (596, 1, NULL, 'chicken', 2.0, 2.0, 'cup', 'shredded, cooked', NULL, 0, '2 cups shredded pre-cooked chicken (about 1/2 rotisserie chicken)');
