INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (597, 'Skillet Pineapple BBQ Chicken', 'Budget Bytes', 'https://www.budgetbytes.com/skillet-pineapple-bbq-chicken/', 30, 30, 0, 6, 6, 0, NULL, NULL, '1. Warm the oil in a large skillet over medium heat and season the chicken thighs with salt and pepper. | 2. Cook the chicken until golden and done on each side and move it to a plate. | 3. Drain the pineapple and keep the juice. | 4. On low heat stir about 1/2 cup of the pineapple juice into the pan, scraping up the browned bits, then stir in the barbecue sauce until thick. | 5. Return the chicken and pineapple slices to the skillet and turn to coat. | 6. Broil about 5 minutes until the sauce caramelizes, then top with jalapeno and green onions.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (597, 1, NULL, 'canola oil', 1.0, 1.0, 'tbsp', NULL, NULL, 0, '1 Tbsp cooking oil');
