INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (598, 'Creamy Garlic Chicken', 'Budget Bytes', 'https://www.budgetbytes.com/creamy-garlic-chicken/', 40, 40, 0, 4, 4, 0, NULL, NULL, '1. Cut each chicken breast into two thinner cutlets, season with the Italian seasoning, salt and pepper and coat in the flour. | 2. Cook the chicken in the oil and 1 tablespoon of the butter about 4 minutes per side and keep it warm. | 3. Smash the peeled garlic cloves and brown them in the remaining butter over medium-low heat about 3 minutes. | 4. Add the broth, cream and garlic powder, scrape up the browned bits and simmer 8 to 10 minutes until reduced by about half. | 5. Season the sauce, return the chicken and heat through, garnishing with parsley if you like.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (598, 1, NULL, 'chicken breast', 1.3, 1.3, 'lb', 'boneless, skinless', NULL, 0, '2 boneless, skinless chicken breasts (about 1.3 lbs total)');
