INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (599, 'Creamy Tomato Chicken', 'Budget Bytes', 'https://www.budgetbytes.com/creamy-tomato-chicken/', 35, 35, 0, 4, 4, 0, NULL, NULL, '1. Slice each chicken breast in half lengthwise into four cutlets, pat dry and season with half the salt and pepper. | 2. Sear the chicken in 2 tablespoons of the oil 4 to 5 minutes per side to 165°F and set aside. | 3. Cook the onion and garlic about 3 minutes, then stir in the tomato paste for 1 to 2 minutes. | 4. Add the last tablespoon of oil and the flour and cook a minute, then slowly whisk in the milk, Italian seasoning, garlic powder and remaining salt and pepper and simmer about 2 minutes. | 5. Stir in the diced tomatoes and return the chicken and its juices to the pan to warm through.', NULL);
