INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (601, 'Sesame Tempeh Bowls', 'Budget Bytes', 'https://www.budgetbytes.com/sesame-tempeh-bowls/', 20, 20, 0, 4, 4, 0, NULL, NULL, '1. Whisk the soy sauce, 2 tablespoons water, sesame oil, brown sugar, rice vinegar, ginger, garlic, sesame seeds and cornstarch until smooth. | 2. Cut the tempeh into 8 squares, then into triangles, and slice each triangle in half horizontally. | 3. Simmer the tempeh in a skillet with 1/2 cup water over medium-high heat, flipping, until the water has cooked off, 5 to 8 minutes. | 4. Lower the heat, pour in the sauce and stir 1 to 2 minutes until it thickens, then take it off the heat. | 5. Thaw the broccoli and build bowls with the rice, tempeh and sauce, broccoli and green onion.', NULL);
