INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (604, 'Taco Casserole', 'Budget Bytes', 'https://www.budgetbytes.com/taco-casserole/', 45, 45, 0, 8, 8, 0, NULL, NULL, '1. Heat the oven to 350°F and grease a 9x13-inch dish. | 2. Brown the beef with the onion and green pepper about 5 minutes, then blot off the fat. | 3. Stir in the chili powder, cumin, paprika, oregano, cayenne, salt and pepper for about a minute. | 4. Add the salsa and black beans and cook about 4 minutes until thick. | 5. Layer two overlapping tortillas, a third of the filling and a third of the cheese, and repeat for three layers. | 6. Bake uncovered about 20 minutes until bubbly, rest 5 minutes and slice into 8 portions.', NULL);
