INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (611, 'Taco Bake', 'Spend With Pennies', 'https://www.spendwithpennies.com/taco-bake/', 40, 40, 0, 8, 8, 0, NULL, NULL, '1. Heat the oven to 375°F and grease a deep 9x13-inch dish. | 2. Cook the beef and onion in a large skillet until no pink remains and drain. | 3. Add the bell pepper, corn, water and taco seasoning and simmer about 4 minutes, then stir in the salsa and take off the heat. | 4. Mix the refried beans and sour cream. | 5. Layer half the crushed chips, half the bean mixture, half the meat and 1 cup of cheese, then repeat with 2 cups of cheese on top. | 6. Bake uncovered 20 to 25 minutes until bubbly and browned.', NULL);
