INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (615, 'Crockpot Chicken Noodle Soup', 'Spend With Pennies', 'https://www.spendwithpennies.com/crockpot-chicken-noodle-soup/', 390, 20, 0, 6, 6, 0, NULL, NULL, '1. Put the chicken breasts in the bottom of a 6-quart slow cooker. | 2. Layer the onion, carrots, celery, garlic, thyme, rosemary, salt, pepper and bay leaf over the chicken. | 3. Dollop on the bouillon, pour in the broth, stir gently and cook on low 6 to 8 hours or high 3 to 4 hours. | 4. Shred the chicken, discard the bay leaf and return the chicken to the pot. | 5. Cook the egg noodles separately until al dente, stir them in and cook on low 5 minutes. | 6. Serve with parsley and black pepper.', NULL);
