INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (616, 'Slow Cooker Lentil Soup', 'Spend With Pennies', 'https://www.spendwithpennies.com/slow-cooker-lentil-soup/', 270, 15, 0, 6, 6, 0, NULL, NULL, '1. Put the diced potato in the bottom of a 6-quart slow cooker. | 2. Add the broth, celery, carrots, lentils, Italian seasoning and garlic and stir. | 3. Cover and cook on high 4 to 6 hours or low 6 to 8 hours until the lentils and vegetables are tender. | 4. Stir in the diced tomatoes and red wine vinegar and cook 15 more minutes, seasoning with salt and pepper. | 5. Pulse a few times with an immersion blender for a thicker, creamier soup.', NULL);
