INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (618, 'Slow Cooker Chicken Pot Pie Soup', 'Spend With Pennies', 'https://www.spendwithpennies.com/slow-cooker-chicken-pot-pie-soup/', 260, 25, 0, 6, 6, 0, NULL, NULL, '1. Soften the onion in the butter in a small skillet over medium heat, about 5 minutes. | 2. Layer the onion, celery and garlic in a slow cooker, set the chicken on top and add the broth, bouillon, poultry seasoning, thyme, salt and pepper. | 3. Cook on high 3 hours or low 6 hours until the chicken is tender. | 4. Shred the chicken, return it to the pot and stir in the peas and carrots. | 5. Whisk the half and half with the cornstarch, stir it in and cook about 20 minutes until thickened.', NULL);
