INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (619, 'Crockpot Potato Soup', 'Spend With Pennies', 'https://www.spendwithpennies.com/crockpot-potato-soup/', 300, 30, 0, 6, 6, 0, NULL, NULL, '1. Cook the bacon until crisp, crumble it and set aside, then soften the onion in a spoonful of the bacon fat. | 2. Put the potatoes, garlic, thyme, onion, salt, pepper and broth in a slow cooker and stir. | 3. Cook on high about 4 hours or low 6 to 8 hours until the potatoes are fork-tender. | 4. Blend about half the soup with an immersion blender and lightly mash the rest. | 5. Stir the cream and cornstarch together, then stir in with the cheese, sour cream and half the bacon and heat 15 to 20 minutes on high until thickened. | 6. Top with the remaining bacon and green onions.', NULL);
