INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (620, 'Slow Cooker Ham and Potato Soup', 'Spend With Pennies', 'https://www.spendwithpennies.com/easy-ham-potato-crockpot-soup/', 440, 20, 0, 8, 8, 0, NULL, NULL, '1. Peel the potatoes if they are russets and cut into ¾-inch pieces. | 2. Put the potatoes, ham, onion, carrot, parsley, thyme, salt and pepper in a 6-quart slow cooker and pour the broth over. | 3. Cook on low 7 hours or high 3 hours until the potatoes are tender. | 4. Scoop out 2 to 3 cups of the potatoes and carrots, mash them and stir back in to thicken. | 5. Stir in the milk and sour cream, cook 15 more minutes and adjust the seasoning.', NULL);
