INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (621, 'Slow Cooker Chicken Tortilla Soup', 'Spend With Pennies', 'https://www.spendwithpennies.com/slow-cooker-chicken-tortilla-soup/', 255, 25, 0, 6, 6, 0, NULL, NULL, '1. Cook the onion, garlic and jalapeño in the olive oil until softened and put them in the slow cooker. | 2. Add the cumin, chili powder, crushed tomatoes, tomatoes with chilies, broth, black beans, corn and chicken. | 3. Cook on high 4 hours until the chicken is cooked through. | 4. Shred the chicken and return it to the pot with the cilantro. | 5. Fry the tortilla strips in hot oil in small batches until crisp, drain, salt lightly and serve on top.', NULL);
