INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (630, 'Cheesy Taco Skillet', 'Spend With Pennies', 'https://www.spendwithpennies.com/one-pot-taco-pasta-skillet/', 23, 23, 0, 4, 4, 0, NULL, NULL, '1. Brown the beef in a large deep skillet and drain the fat. | 2. Stir in the taco seasoning, then add the water, salsa and uncooked pasta. | 3. Bring to a boil, cover and simmer about 10 minutes until the pasta is tender, adding water if needed. | 4. Stir in the cubed cheese until smooth and creamy.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (630, 1, NULL, 'ground beef', 1.0, 1.0, 'lb', 'lean', NULL, 0, '1 lb lean ground beef');
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (630, 2, NULL, 'taco seasoning', 2.0, 2.0, 'tbsp', NULL, NULL, 0, '2 tbsp taco seasoning');
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (630, 3, NULL, 'water', 2.75, 2.75, 'cup', NULL, NULL, 0, '2¾ cups water');
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (630, 4, NULL, 'salsa', 0.75, 0.75, 'cup', NULL, NULL, 0, '¾ cup salsa');
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (630, 5, NULL, 'pasta', 3.5, 3.5, 'cup', 'uncooked', NULL, 0, '3½ cups medium pasta (such as penne or rotini), uncooked');
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (630, 6, NULL, 'processed cheese', 8.0, 8.0, 'oz', 'cubed', NULL, 0, '8 oz Velveeta, cut into ½-inch cubes');
INSERT INTO recipes (recipe_id, recipe_name, source_site, source_url, total_time_minutes, active_time_minutes, total_time_is_estimated, servings_min, servings_max, servings_is_estimated, yield_quantity, yield_unit, steps, duplicate_group) VALUES (631, 'Million Dollar Spaghetti', 'Spend With Pennies', 'https://www.spendwithpennies.com/million-dollar-spaghetti-casserole/', 85, 45, 0, 12, 12, 0, NULL, NULL, '1. Heat the oven to 350°F, grease a 9x13-inch dish and cook the spaghetti until al dente, then toss with one jar of sauce. | 2. Brown the sausage with the onion and garlic, drain and stir in the second jar of sauce and 2 teaspoons Italian seasoning. | 3. Blend the cottage cheese, cream cheese, sour cream, 1 cup mozzarella and 1 teaspoon Italian seasoning until smooth. | 4. Layer half the spaghetti, the cheese mixture, then the remaining spaghetti and pour the meat sauce over. | 5. Bake uncovered 35 to 45 minutes, adding the remaining mozzarella for the last 20, then rest 15 minutes.', NULL);
INSERT INTO recipe_ingredients (recipe_id, line_number, component, ingredient, quantity_min, quantity_max, unit, preparation, substitute, is_optional, original_text) VALUES (631, 1, NULL, 'spaghetti', 16.0, 16.0, 'oz', NULL, NULL, 0, '16 oz spaghetti');
